/* 平成20年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h20.committeeSessions.push(...[{"id":"h20-20080304-3","meetingId":"h20-c-budget","date":"2008年3月4日","dateIso":"2008-03-04","committee":"予算特別委員会","time":"午前１０時０３分～午後６時１３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を187件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２０年度品川区一般会計予算","agenda":"平成２０年度品川区一般会計予算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"ロケーション・写真撮影のところですが、大体この項目からイメージしますと、ドラマ、ＣＭ等も含まれた、そういった場合の公園等の貸し出しかなと思うんですが、その辺の概要説明と、主な場所、あるいは１件当たりの許可を出した際の金額、そして主な事例と、どんな相手先か、まずこの辺をお伺いしたいと思います。","respondent":"松代管理工事課長","answer":"その際の占用料の単価ですけれども、ロケーションの場合は１時間当たり１万８７５円、写真撮影の場合は１時間当たり１,２３２円ということで、平成１８年度の実績で申し上げますと、ロケーションが１３７件、時間数にしまして２７５時間、２６７万円余の収入となっています。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"できる名所、そしてお薦め撮影場所リストみたいなものを、そのような形ですぐ対応が準備できることと、これは難しいのかもしれないのですが、営業ではないという前提で、誘致を、あるいはＰＲの働きかけが可能かどうか、この辺のご見解をお伺いできればと思います。","respondent":"松代管理工事課長、中川原広報広聴課長","answer":"できればホームページなんかでもこの公園の特徴というところでＰＲをしていますので、そういったところで問い合わせにきちっと対応していきたい、そのように思っているところです。ただいま公園のことでお話ししていますが、広報広聴を窓口としまして、フィルムコミッションにつきましては総合的な窓口として対応しております。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問・要望","question":"前向きな話題なので、ぜひ僕らも何かいい企画を出せるように頑張りたいと思います。続いて、公園運動使用料の点でお伺いしたいと思います。歳入で、クラブハウスの項目でありますが、クラブハウス等、いろいろなスポーツをし終わったあとのひとときの場という点で期待されていると思いますが、まず主な場所を確認の意味でお教えいただきたいと思います。","respondent":"富田生涯学習課長","answer":"クラブハウスということですが、品川中央公園のミーティングルーム、こちらが定員１５名、あと天王洲公園のミーティングルーム、こちらは定員２０名ということで、２カ所です。","voiceIndex":9,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問","question":"そこには箱ものといいますか、机いすだけではなくて、私がお見受けする限りでも、よく各運動施設で設置されている中では飲料水の販売機等、やはりそこにひとときを過ごすための工夫をいろいろされていると思うんですが、飲料水自動販売機に関して何か基準等があるのか、お伺いしたいと思います。","respondent":"松代管理工事課長","answer":"自動販売機等です。これにつきましては、今ご質問にございましたクラブハウス等々があるスポーツ施設、そういったところに利用される方のサービス提供ということで設置をしております。","voiceIndex":11,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"質問・要望","question":"経費との兼ね合いもあると思いますが、設置台数と内容充実について、要望とあわせてお伺いしたいと思います。というのも、季節とか日時によるものなんですが、そういう前提で、大会利用などのときに多くの利用者が訪れて、よく夏場とか秋は売り切ればかりで十分に水分補給ができないという苦労話もよく伺います。ご見解をお伺いします。","respondent":"松代管理工事課長","answer":"そういったものの拡大も今後少しずつ検討してまいりまして、なるべく利用者のニーズ、そういったものに合ったような、それでスポーツで使いながら、附帯的な形で使っていただいて満足いただけるような、そういったものを今後検討してまいりたいと考えているところです。","voiceIndex":13,"id":"exchange-005"},{"speaker":"金野委員","kind":"質問・要望","question":"４節のこの歩道橋の維持費の収入、これは大森歩道橋というふうになっているんですが、大森の歩道橋というのは具体的にはどこのことなのか、それを教えていただきたいことと、またこの受託事業の概要、また事業を進めるに当たってのわかる範囲で、このタイムスケジュールというんでしょうか、教えていただきたいと思います。","respondent":"藤田道路公園課長","answer":"平成２０年度につきましては、加えまして、エスカレーターの踏みつらといいますか、踏む板のところがだいぶ経年で劣化をしてきておりまして、それの昇りのほうの改修工事を予定をしております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"金野委員","kind":"質問","question":"管理は品川区でするということで、これは１年に１回のメンテナンスということではなく、今回は昇るところの踏み板のところを主に改修をするということですけれども、エスカレーターのいわゆるメンテナンスというんでしょうか、これは年に何回かするんでしょうか。","respondent":"藤田道路公園課長","answer":"メンテナンスの関係ですけれども、エスカレーターのほうの点検等につきましては、当然法定の点検等がありますので、月に１回点検をするような形になっております。","voiceIndex":18,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"以前でしたか、エスカレーターの事故というのもありました。大田区とのこれは折半でということなんですが、こういった区境での、例えば港区等もうちは区境がありますし、目黒区でもありますし、そういったところでは、こういった折半の事業というのはあるんでしょうか。","respondent":"藤田道路公園課長","answer":"基本的には施設ではなく、通常の道路等であれば、お互いお互いにこちらの道路は品川区で、あるいは港区でというような形での役割分担をしていますので、特に道路の真ん中で分けてそれを折半して相手相手にということではなく、お互いの関係の中で、受託ということではなく。","voiceIndex":20,"id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"次の７節の公園復旧費のほうですが、こちらは鈴ヶ森公園ということで、先ほども下水道工事ということでご説明があったんですが、こちらの概要というんでしょうか、それと、この復旧に当たっての下水道工事の件と、それから、たしかこの平成２０年度の予算の中に公園の改修工事というところもあったと思うんですが、わかる範囲で結構です。概要説明をお願いしたいと思います。","respondent":"松代管理工事課長","answer":"そういったことから復旧費に当たる費用を下水道局のほうからいただきまして、あわせて区が全面的に改修をしようと、このように考えているところです。","voiceIndex":22,"id":"exchange-009"},{"speaker":"金野委員","kind":"質問・要望","question":"今のご説明の中に、消防署のところの土地も購入をしてということで、もともとあそこは大井消防署の土地があったところで、実は地域の方が、あそこの町会の方が、消防署のいわゆる防災設備の一つを一貫して置きたいという要望を私も受けておりまして、ぜひ何とか、今は別々の２カ所に分けておいてあるということもあったので、そういったところでも、公園の中でそういうことができるのかどうか。","respondent":"松代管理工事課長","answer":"区の改修のまさに今計画を進めているところでございまして、地域の町会長を含め、地域の方々とお話をしております。そういった中で、委員から今お話があったような防災上、そういったものの倉庫的なものの集約、そういったもののご相談を受けております。","voiceIndex":24,"id":"exchange-010"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひ地域の方のご要望が反映ができるよう、私からも要望をしたいというふうに思います。ここの公園の復旧工事とともに改修工事が行われるということですので、今後、この説明会等々はどのようなふうになっているのでしょうか。","respondent":"松代管理工事課長","answer":"説明会は３月１９日の夜に予定をしておりまして、そこの中で、地域の方々と少し事前にいろいろとご意見を受けたもの、そういったものを踏まえて、まず計画案というものをお示ししていろいろご意見を伺い、それを集約したものを平成２０年度工事という形で進めたい。","voiceIndex":26,"id":"exchange-011"},{"speaker":"金野委員","kind":"質問・要望","question":"ぜひこの説明会の中で、その計画案の中に皆さんのご要望も含めて、いい公園に改修できますよう要望したいと思います。公明党からも以前から要望しておりました、公園を改修するに当たってだけではないですが、公園の中にも健康器具というか、健康遊具みたいなものの設置をという要望をこれまでもしてまいりましたけれども、ぜひそこの点も含めていただいて、改修工事をぜひよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":28,"id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"事項別明細書の５４ページや９６ページなど、収入についてお伺いいたします。５４ページ、地方譲与税から１項自動車重量譲与税、２項地方道路譲与税、５８ページ、７款自動車取得税交付金、そして９６ページからの国庫補助金の土木費補助金から１節都市計画道路整備費、１１節電線類地中化事業費、１２節橋梁改修事業費、１３節踏切改良事業費、これで間違いないでしょうか。","respondent":"日下部企画財政課長","answer":"では特定財源がなくなった場合の影響ということでありますけれども、実際には特定財源としてあらかじめ今年度の予算の中に見込んでおりますので、その分が減になるということは、それはそれなりに事業の運営上、執行上、やはりその分の財源の裏打ちがなくなりますので。","voiceIndex":30,"id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"例えば、先ほど言いました国庫補助金の中で、どれだけが道路特定財源なのかというのは、こちらでわかるものなのですか。","respondent":"阿部都市計画課長","answer":"先ほどのご質問にございましたように、国庫補助金の中で、具体的には電線類地中化事業あるいは橋梁改修事業、踏切改修、あと都市計画道路事業、そのほかにも市街地再開発事業の中にも道路特定財源が入ってありますので、そういう事業が国庫補助金の対象になっているです。","voiceIndex":32,"id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"どれぐらい入っているかということをちょっとお伺いしたいんですけど、具体的に。","respondent":"阿部都市計画課長","answer":"当初予算ベースでは、国庫補助としては４億７,３５０万円余です。そのほかに臨時特例交付金、これが道路特定財源の配分対象になってありますので、これについては１０億８,７００万円余です。","voiceIndex":34,"id":"exchange-015"},{"speaker":"安藤委員","kind":"質問","question":"必要な事業は一般財源でも十分できるし、区は必要な財源を確保せよというべきであって、政府の方針にわざわざ乗って道路特定財源から出せとまで要請するのはおかしい話だと私は指摘したいと思います。次に、区の立場についてお伺いしたいんですが、道路特定財源暫定税率は廃止すべきと考えているんでしょうか。それとも維持すべきだと考えているんでしょうか。あわせてその理由についてもお聞かせください。","respondent":"日下部企画財政課長、阿部都市計画課長","answer":"道路特定財源につきましては、私ども区側の見解としては、これは、先ほどもちょっと申し上げましたけれども、平成２０年度予算を編成するに当たりまして、先ほどの例えば地方道路譲与税等も含めまして。先ほどの１９億円の話ですけれども、それについては、先ほどのお尋ねは国庫補助分ということでしたので、１９億円については地方税収分も入ってありますので、その差額があるです。","voiceIndex":36,"id":"exchange-016"},{"speaker":"安藤委員","kind":"意見","question":"立場について、維持すべきかどうかということについて、ちょっとわからなかったので、懸念はあるということはわかりました。維持すべきと考えているのか、廃止すべきだと考えているのか、お答えください。","respondent":"岩田まちづくり事業部長","answer":"当議会でも審議をしていただいて事業を進めております都市計画道路３本、これについても区民生活に密着した事業ですし、最も影響のある補助金ベースではなくて、地方税収分として入ってくる分、これは日常の街路灯の電気代とか。","voiceIndex":39,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問","question":"先ほど世論調査は紹介いたしましたが、私は区民の方からお話を伺いました。ある、従業員が１０人程度の運送会社の社長にお話を伺いました。そんな状態です。こういう中で「暫定税率についてどうですか」と聞きましたら、すぐ「もうそれは廃止大歓迎」と。そういったことを守るために下げてほしいと言っています。そうした区民の皆さんの立場にしっかり立つべきだと思いますが、いかがでしょうか。","respondent":"福田企画部長","answer":"品川区は、道路も福祉も大切に考えております。いままでもそうでしたし、この考えを変えるつもりはございません。","voiceIndex":41,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問","question":"こうしたもと、福祉が削られに削られて、ガソリン税率も上がって国民生活が大変だという実態があるということを私は懸念しており、そして指摘しているんですが、そこに関する考えはいかがでしょうか。","respondent":"福田企画部長","answer":"予算案をお目通しいただければおわかりだと思います。それぞれの各施策の分野、政策の分野につきまして充実を図ってきております。","voiceIndex":43,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"私は、ホームページで見たんですけれども、一般にも報道されていますので皆さんご存じだと思いますが、濱野区長が特別区長会で暫定税率を維持するための法案の年度内成立を図ることと、一般財源化することがないようにということを求める要請行動に参加しているというのを見たんですけれども、これは行政側や執行側の。","respondent":"福田企画部長","answer":"予算の編成の要諦は「入るを計って出るを制する」にあります。そうしますとこの財源がおぼつかなくなる、こういうことですと、執行機関として責任を持ってこの予算案を議会にご提案することができない。そういう意味で先ほどから申し上げているものです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"国全体、世界全体で見れば、確かに品川区は便利になるかもしれません。しかし大変なことになる事態もあります。この特定財源があるために。だったら、それは区のことだけを考えるのではなくて、やはり環境問題、経済問題、福祉の問題で、しっかりと区民の利益の立場に立つべきではないかと思うんですが、いかがでしょうか。ぜひその立場に立っていただきたいと思うんですが。","respondent":"本間副区長","answer":"区民の立場に立った予算編成をさせていただき、その予算の執行に影響が出るということで、いままでご説明をしていますので、ご理解のほどをよろしくお願いをいたします。","voiceIndex":47,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ区民の立場に立って、この道路特定財源に関しては廃止の方向で頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-022"},{"speaker":"稲川委員","kind":"質問","question":"５２ページの特別区のたばこ税についてですが、品川区にとって、たばこ税のあり方というか、今、前年度が３３億円で、本年度、３０億７,０００万円で減少しているんですが、その減少の理由と、あと、品川区にとってのたばこ税のあり方というか、どう思われているか、教えてください。","respondent":"武内税務課長","answer":"徴税コストという部分がほとんどかからないという部分においては、増収という部分については区にとっては大きいんですけれども、また反面、区民の健康ということでは、どうなのかと考えているところです。","voiceIndex":51,"id":"exchange-023"},{"speaker":"稲川委員","kind":"質問","question":"私も何気なくたばこを吸っているんですが、例えばいろいろＪＴのホームページとかを見ますと、たばこ１箱に対して相当な税金がかかっている中で、２９％ぐらいが都道府県税と市区町村税というんですか、になっているというのを見たんですが、実際に品川区にはどのような形でその税金が戻ってくるのかを教えてください。","respondent":"武内税務課長","answer":"そういった意味では、たばこの卸売業者、製造会社というのは２社が大きいんですけれども、そのほかに今言ったように外国産たばこの販売会社が数社ありまして、品川区としては１４社ほどが区にたばこ税をお支払いいただくという。","voiceIndex":53,"id":"exchange-024"},{"speaker":"稲川委員","kind":"質問","question":"今回も、そういうことで、今度は完全に今たばこを吸われている方は自動販売機での販売が、結構８割方占めているという話もあるんですが、それで例えば小売業者が仕入れを抑える、抑えたことによって、やはり品川区に対して税収が入ってこないんじゃないかと思うんですが、その辺はいかがでしょうか。","respondent":"武内税務課長","answer":"その影響につきましては、自動販売機だけを置いてある場所においては当然売り上げが下がるのかなというふうには思いますけれども、区内にある小売業者は、そのお店の方が横にいて、さらに自動販売機で売っているというような状況。","voiceIndex":55,"id":"exchange-025"},{"speaker":"稲川委員","kind":"質問","question":"窓口といいますが、先ほども申し上げましたように、たばこの自販機での売り上げが結構多いと。ここに前年度比で３３億円から減収で、３０億円ですか、３億円落ちているというのは、健康増進法とか、本数を減らしているとかいろいろあるとは思うんですが、この金額よりも僕はもっと、３０億円を切ってしまうんではないかなという素人ながらの考えがあるんですが、絶対に影響はないとお考えですか。","respondent":"武内税務課長","answer":"それは委員言われるとおり、区内でたばこを買っていただくということが非常に大切ですので、区民の喫煙者の方に、このタスポというものをより効果的にＰＲするということも非常に大切ですので、こういうシステムになったということを。","voiceIndex":57,"id":"exchange-026"},{"speaker":"稲川委員","kind":"質問","question":"喫煙者もマナーを守ってしっかりとやっておりますので、ぜひその辺、よろしくお願いをいたします。８１ページのグラウンドの使用料ですが、先ほど企画財政課長のほうから前年比で減った理由はお伺いしたので、このグラウンドの使用料というのは実際どういう形で決められているのかを教えてください。","respondent":"富田生涯学習課長","answer":"野球場等の使用料ですが、区条例等で、野球場については区内料金２時間当たり１,５００円ということで決めている、あるいは区外の団体が利用するときには、その倍額ということでもって決めしています。","voiceIndex":59,"id":"exchange-027"},{"speaker":"稲川委員","kind":"質問・要望","question":"この２時間１,５００円ですか、これが高いか安いかという議論になって、僕は安いというか、すごくリーズナブルな使用料だなとは思うんですが、やはり地域を回っていますと、やっぱり１,５００円は高いという人もいるんですが、実際にいろいろグラウンドの維持費とかさまざまかかってくると思うんですが、品川区として、今後それが上に行くのか、下に行くのか、値上がるのか。","respondent":"岩田まちづくり事業部長","answer":"公園の有料施設の使用料の算定方法は、原則、他の区有施設と同じでございまして、維持管理費、ランニングコストのおおむね３割程度で物事をまず考えます。","voiceIndex":61,"id":"exchange-028"},{"speaker":"稲川委員","kind":"質問・要望","question":"とは言いながらも、やはり地域を回っていますと本当に１,５００円でも高いという話が多いので、それはぜひ今のままを維持していただければと、これは熱い思いで要望をいたします。今でも高いという人がいるので、よろしくお願いをいたします。ちなみに、何面とれるかも。よろしくお願いします。","respondent":"富田生涯学習課長","answer":"予算計上するに当たりまして、その上の八潮北野球場、こちらも１面ですが、ご覧いただけばわかるように若干遠いということもありますので、どれほどのご利用がいただけるか不明のところもありますので、野球場の使用料についてはそういったところの約半分強ということで。","voiceIndex":63,"id":"exchange-029"},{"speaker":"稲川委員","kind":"質問・要望","question":"前段に申し上げましたグラウンドの使用料の件は、以後ぜひ維持していただきたいということで、この質問を終わります。次に、６４ページの教育費負担金というのがありまして、３２７万５,０００円、旧八潮北小学校管理費負担金ということなんですが、これについて、内訳というか、教えていただきたいんですが、お願いします。","respondent":"古里学務課長","answer":"この小学校管理費負担金ですけれども、学校の中のさまざまな空調設備その他いろいろな機材がありますけれども、その機材の１年間の保守点検あるいは運転にかかわる費用、そうしたものです。","voiceIndex":65,"id":"exchange-030"},{"speaker":"稲川委員","kind":"質問","question":"僕も素人ながらあれなんですが、これは家賃という言い方はおかしいんですが、それが大体どれぐらいなのか、教えてください。","respondent":"古里学務課長","answer":"こちらは家賃ということではなくて、あくまでも小学校の中で１年間快適に過ごすためのさまざまな設備機器の運転にかかわる経費の案分の費用ということで、歳入として３２７万５,０００円を計上しています。そのような内容ですので、家賃という性格のものではございません。","voiceIndex":67,"id":"exchange-031"},{"speaker":"稲川委員","kind":"質問","question":"それがちょっと聞きたかったので、すみません。１１８ページにつきましては、あと１０秒を切りましたので、これで私の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":69,"id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"１点目の特別区民税の件ですけれども、普通徴収分と特別徴収分で、品川区は非常に高い収入率が見込まれ、過去においてもずっと高い率を示しているわけですけれども、いろいろと三位一体をはじめ、今後の社会情勢、経済情勢において、この収入率がどのように推移していくのか、見込まれる見通しというか、ご意見がありましたら、お伺いしたいと思います。","respondent":"武内税務課長","answer":"そういった意味では、現年分についての滞納者を増やさないということで、我々職員が日々努力して徴収率を上げているわけですけれども、そういった意味では、今後この数字を下回らないような目標を設定して頑張っていくという、そういう考えでおります。","voiceIndex":71,"id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"いずれにしましても９０％台ということですから、高い収入率だと思うんですけれども、今ご答弁にありましたように滞納をさせないというので、それでは一体滞納するという部分で、滞納をする人、またはせざるを得ない人がいるわけですけれども、それぞれどんなケースがあるのか、たくさんのケースがあろうかと思いますが、主たるケースがありましたら一つ二つお伺いしたいと思います。","respondent":"武内税務課長","answer":"滞納者の状況ですけれども、いわゆる住民税につきましては、前年の所得に対して、３月の時点から計算しまして５月に課税をするという現状です。","voiceIndex":73,"id":"exchange-034"},{"speaker":"大沢委員","kind":"質問","question":"今、主たるものを聞きました。その上においては、税を払う、滞納するということで、本来であれば義務の先送りをするということで不利益を被る場合があります。不利益を被る項目があると思いますけれども、そのうちで大きなものは三つぐらい、何がありますでしょうか。","respondent":"武内税務課長","answer":"私どもも課税証明書、納税証明書というのを発行するんですけれども、その証明書をとりに来られる方は、ほとんどの方が例えば住宅を購入するための銀行ローンを組むだとか、あるいは都営住宅に入居しているための税の確認だとかということで証明書をとりに来るんですけれども。","voiceIndex":75,"id":"exchange-035"},{"speaker":"大沢委員","kind":"質問","question":"ちょっと今１８億円余と、収入額が３億６,０００万円余ということで収入率を１９.６％、これは平成１６年度、平成１７年度、平成１８年度、平成１９年度、平成２０年度と、大体この１９.５％と２０％台の収入率を見込まれておりますけれども、これに対して、確かにこれは滞納分を、上げれば上げるに越したことはないと思いますが、この数字に関してどのように認識をされているのか。","respondent":"武内税務課長","answer":"そういった意味では、当初の今年度の見積もりについては、もうちょっと上げ幅もできるのかなというふうな予測はしているところなんですけれども、やはり社会の状況に応じてこれがマイナスになったときのことを考えますと、安定という意味で。","voiceIndex":77,"id":"exchange-036"},{"speaker":"大沢委員","kind":"質問","question":"これは次の質問につながるから２点残したわけでありまして、何かと言いましたら、来年９月から例のグレーゾーン金利が廃止されるわけでありまして、このグレーゾーンの金利が違法とされる判例が出ました。それによって返還を受けている方も現にいる。これは賛否両論ありますけれども、この回収の仕方について、どのようにお考えになりますか、お聞かせください。","respondent":"田中区民生活事業部長","answer":"その点で、この整理に向けて東京都等もいろいろな形で区市町村と連携した協議会等をつくって、その対応策を今検討しておりますので、国保、税を含めまして、多重債務、グレーゾーン金利で回収できるものについては東京都等と連携をとりながら、改善。","voiceIndex":79,"id":"exchange-037"},{"speaker":"大沢委員","kind":"質問","question":"では次の質問に移らせていただきます。住基カード、前年１,５００件から本年５,５００件ということで大幅な増を見込んでおりますけれども、これは区民カード廃止に伴う増加と、増加に伴って、その分の件数を多くした、こういう予算というか見積もりを立てたということで理解をしてよろしいでしょうか。","respondent":"上川内戸籍住民課長","answer":"それが全国的に伴っていますので、生産ラインがなかなか追いつかなくて、入るのにも６カ月待たなくてはいけないという状況もございまして、大幅にそれを推計しまして、区民カードから移行する方の分も入れまして、このように予算を計上したものです。","voiceIndex":81,"id":"exchange-038"},{"speaker":"大沢委員","kind":"意見","question":"昨日のある新聞で、手詰まり状態だと、本区は非常に違って、いいという、非常に住基カードに対する関心、理解が高いということで、利便性をよく認知されているということでいいと思うんですが、この普及率を上げるために、さらに今後どのように対処していくか、もう一回お聞かせ願いたいと思います。","respondent":"上川内戸籍住民課長","answer":"ですから、国や都が中心となりまして、検討をしながら推進策を進めているところです。","voiceIndex":83,"id":"exchange-039"},{"speaker":"大沢委員","kind":"質問","question":"それで、ただいまの普及に向けた工夫をこれからされるですが、やはりこれもほかの自治体にあります、高齢者、要するに６５歳以上の方々が免許証の自主返納を目的とし、そのかわりに住基カードをつくることを支援をいたしますよと、これは一つの交通事故対策にもなると思うんですが、そこの部分の議論というのは出ておりますでしょうか。","respondent":"岩田まちづくり事業部長","answer":"現在警視庁のほうで、お年寄りの免許証の自主返納について、プラスアルファのものをつけることをいろいろ検討はしておりますけれども、今ご指摘のような住基カードとのリンクというお話はちょっと承っておりません。","voiceIndex":85,"id":"exchange-040"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっと私が調べたところで、身分証明を住基カードにかえること、免許を自主返納することによって住基カードをつくる。それと、最後に簡単にお伺いいたします。弁償金なんですけれども、全部で３点ありますけれども、二つについては、標識弁償金と、物についての弁償金ということで、ある程度想像できますが、生活保護費の弁償金について、簡単でいいですので説明をいただきたいと思います。","respondent":"志村生活福祉課長","answer":"生活保護費は１カ月分前払いをいたします。ですけれども、例えばいろいろなご事情によりまして、入院をする、あるいは転居によりまして、過払いが生じた際の返還に対応した科目です。","voiceIndex":87,"id":"exchange-041"},{"speaker":"山元委員","kind":"質問・要望","question":"私は、９０ページの中国残留邦人等支援事業費、また１０２ページの同じく中国残留邦人等支援事業委託金について、そして時間があれば７６ページの教育使用料の中の学校施設使用料についてお伺いしたいと思います。最初に、この９０ページと、また１０２ページの中国残留邦人等支援事業委託金、また支援事業費について、この中身を教えていただきたいと思います。","respondent":"志村生活福祉課長","answer":"詳しくは歳出予算のほうに計上してございまして、都内で１,２００人を予定していますけれども、私ども品川区では現在のところ３９人というふうに承知しています。","voiceIndex":90,"id":"exchange-042"},{"speaker":"山元委員","kind":"質問","question":"今、平均年齢が７０歳ぐらいというお話がありましたけれども、この７０歳前後の方たちというのは、日本語はほとんどお話ができないんでしょうか。","respondent":"志村生活福祉課長","answer":"この２月に、今度４月からそちらの制度に移行していきますよということをご説明しましたときに、２日間かけて行いましたけれども、やはりそのときには通訳の方が必要で、よくあります、私どもで言ったことを通訳していただいて。","voiceIndex":92,"id":"exchange-043"},{"speaker":"山元委員","kind":"質問","question":"やはりそうしますと、本当にこれからいろいろ考えていただけると思いますが、そういう日本語の勉強をするとかというのはあると思うんですが、この相談員が何人かいらっしゃると思うんですけれども、この相談員というのは今現在何人いらっしゃるのでしょうか。教えていただけますでしょうか。","respondent":"志村生活福祉課長","answer":"現在は東京都が国の委託を受けまして、こうした方についての生活相談といいますか、広範な相談に当たっているところですけれども、今回、私どもの仕事になってまいりますので、４月１日からこの相談員の方を予定しています。","voiceIndex":94,"id":"exchange-044"},{"speaker":"山元委員","kind":"質問","question":"日本語が話せない、また入りたくてもその手だてがわからないということでご相談いただいたんですが、この１９世帯３９人の中にいらっしゃるかどうかは別といたしましても、万が一そういう保育園に入りたいという場合には、私たち日本人と同じような、そういう申し込みというんでしょうか、そういう手続をしないといけないのでしょうか。","respondent":"志村生活福祉課長","answer":"ただ、私どもでまだ把握してございません、いわゆる生活保護を受けていらっしゃらない方が１８世帯いらっしゃいますので、その方の状況については、実は４月１日申請にお見えになってからでないとわからない状況ですので、ちょっとそこら辺の細かなところについては。","voiceIndex":96,"id":"exchange-045"},{"speaker":"山元委員","kind":"質問","question":"その点、ぜひよろしくお願いしたいと思います。では、次に７６ページの教育使用料の学校施設使用料についてお伺いをしたいと思います。こちらに教室また屋内運動場云々と書いてありますけれども、お借りする場合の一般料金と言っていいんでしょうか、またはその団体に入っていると割引があると思うんですが、その料金等を教えていただけますでしょうか。","respondent":"富田生涯学習課長","answer":"学校施設を利用する場合の料金ですが、体育館につきましては１区分１,６００円、武道場また第二体育館につきましては８００円、校庭につきましては１区分８００円です。そういった利用に当たりまして、社会教育登録団体の場合には減額ということで、半額になるものです。","voiceIndex":98,"id":"exchange-046"},{"speaker":"山元委員","kind":"質問","question":"その施設を借りる場合の申し込みの手順というんでしょうか、そちらを教えていただいてもよろしいですか。","respondent":"富田生涯学習課長","answer":"申し込みまして、予約をいたしますと、利用の申請書をお渡しし、使用料をお支払いいただきまして、承認書を受け取ってというような、承認書を持って学校の利用に行っていただくということになります。","voiceIndex":100,"id":"exchange-047"},{"speaker":"山元委員","kind":"質問・要望","question":"実は先輩が平成１０年の予算特別委員会のときにやはり同じ質問をいたしました。私自身も今回学校をお借りするに当たりまして、今おっしゃったとおりの手だてをいたしました。そのときに、ちょっと疑問といいますか、この学校に申し込みに行ったときに、そこで料金を払えたらいいのになと思います。要望でありますが、その辺また検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-048"},{"speaker":"渡部委員","kind":"質問・要望","question":"私のほうから３点質問させていただきたいと思います。初めに、このリサイクル資源売払収入なんですが、今年の１０月にサーマルリサイクルのこの全戸回収が始まるに当たって、昨年度予算から比べましても相当増えているんだなと認識しておりますが、この資源回収事業等を含めまして、このお金というのはどこから区に支払われてくるのか、教えていただけますでしょうか。","respondent":"秋山資源循環推進課長","answer":"資源化センターのほうで中間処理をして、そのあと、それぞれの問屋がありますので、問屋を通してメーカーのほうに売っているということで、売払いの金額がそういう個々の品目ごとにメーカー、問屋がありますので、そちらのほうに売払ってその収入が入ってきているという状況です。","voiceIndex":104,"id":"exchange-049"},{"speaker":"渡部委員","kind":"意見","question":"それと１２節の水族館運営費収入の部分なんですが、１億３,７３６万８,０００円で、しながわ水族館運営事業費収入分配金等とあります。私自身、入館者がこんなに減るはずもないなと思いつつ、減らないと思うんですけれども、もしかしたら長期の休みか何か、大きな改修か何かが入るのかなとも思ったんですが、この１２節の水族館運営収入の部分についてお教えください。","respondent":"藤田道路公園課長","answer":"その事業を進める中で、当然水族館運営のための光熱費、水族館ですから水を使ったり、あるいはポンプがあったり、エアーを送ったりするということで電気代がかかるということで、その費用の分については利益が上がった場合については、まず。","voiceIndex":106,"id":"exchange-050"},{"speaker":"渡部委員","kind":"質問","question":"内容はわかりました。ただ、平成１９年度予算と比較していいのかどうかわからないんですけれども、大幅にここの数字が下がっている理由というのが何なのかというのを一つお願いします。","respondent":"藤田道路公園課長","answer":"そういった分を差し引くと、この収入となってくる、もとになる利益のほうが減ってくる。その中で分配してくるので、こうした形で金額が減ってきているものです。","voiceIndex":108,"id":"exchange-051"},{"speaker":"渡部委員","kind":"質問","question":"それこそ公園の施設を利用したときに施設使用料を納めたりする中で、現金の移動というのがあったり、例えば口座引き落としですとか、そのようないろいろな方法があると思うんですが、例えばこれから先を見据えた中で、また今のこの時代の流れとかを考えた中で、いわゆる一つのクレジットカードによる収納というのは区としてどのようにお考えでしょうかというのが大きく伺いたいところです。","respondent":"日下部企画財政課長","answer":"今後のやはりいろいろな社会全体の動きを見ますと、この問題もやはり避けては通れないというふうに考えておりますので、その辺は十分これから検討してまいりたい、このように考えております。","voiceIndex":110,"id":"exchange-052"},{"speaker":"渡部委員","kind":"質問","question":"これからキャッシュレスというのではないでしょうけれども、電子マネーですとか、いろいろな部分で普及が進んでいくと思います。一覧表で経費が出てくるのがわかりやすいとかということもありますので、ぜひこれから検討を進めていただいて、そのような形で取り入れられればいいなと思って質問を終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":112,"id":"exchange-053"},{"speaker":"菊地委員","kind":"質問・要望","question":"私のほうは、先ほどもありましたけれども５０ページの特別区民税と、それから５６ページの株式等譲渡所得割交付金、この辺をあわせてお聞きをさせていただきたいと思います。それから、区民のところでの収入の変化ですか、この辺のことについてもあわせてお聞かせを願いたい。それから、特別区民税の仕組み、どういうふうにこれが上がってくるのか、増えるのか。それで合計約２００億円もの減税を受けている。","respondent":"武内税務課長","answer":"そういった意味で、２万人の方の生活状況というのを把握することは、実際のところ、とてもではないけれどもできないわけです。ところが払っていないですから督促状を発付する。それは地方税法の中でも決まっていることです。","voiceIndex":114,"id":"exchange-054"},{"speaker":"菊地委員","kind":"質問","question":"それで帰って来て、店をあけて、９時１０時まで店をあけているわけですから、ずっと働き詰めでもなかなか生活し切れないというような話を聞きますし、高齢者のところでは暖房も使わずに、暖房費がもったいないから室内で外出するときのようにコートを着たまま、こういう生活をしていらっしゃるわけです。お聞きしたいのは、政策的にやはり低所得者の施策を最大限に強化をしていく。","respondent":"日下部企画財政課長、武内税務課長","answer":"１点目のご質問ですけれども、この間申し上げておりますように、品川区におきましては低所得の方、福祉から教育に至るまで、すべての施策全般にわたって、バランスよく。上場株式の取引のことにつきましては、やはりその平成１６年の地方税法の改正の中で、システムを変えることによって、そういう投資家の方を活性化させるという大きなねらいがあるのかなというふうに思います。","voiceIndex":116,"id":"exchange-055"},{"speaker":"菊地委員","kind":"意見","question":"もちろん収入がそこそこにある人たちは、どういう負担でもできるでしょうし、必要なサービスも受けることはできるわけです。私はこの所得の少ない人たち、いままでも品川区に長い間住んで、その中で税を納め、生活をしてきた、こういう皆さんのところへの配慮が、あまりにも今の状況というのは足りないのではないかというふうに考えているわけです。改めてこの辺の見解をお願いしたいと思います。","respondent":"日下部企画財政課長","answer":"福祉の面におきましては、負担の軽減策でありますとか、今回も平成２０年度予算におきましても、その辺は十分に配慮した中身として構成をしているものです。","voiceIndex":119,"id":"exchange-056"},{"speaker":"山内委員","kind":"質問・要望","question":"私は１３３ページのリサイクル資源売払収入の資源回収事業について、それから、戻りますけれども８７ページの廃棄物処理手数料について、それからあと、１３４ページの宝くじ等の助成金の収入について、お伺いをさせていただきたいと思います。もし想定をしているのであれば、大体どれぐらいの数字というものを考えているのか、ちょっと教えていただきたいと思います。","respondent":"秋山資源循環推進課長","answer":"持ち去りの金額というご質問ですけれども、持ち去りにつきまして、正確な量というのがなかなか把握が難しいですけれども、行政回収のほうで一番多かった時期、平成１３年度から今年度を引きますと大体３,０００ｔ強が平成１３年度から平成１８年度ですけれども、減っております。","voiceIndex":123,"id":"exchange-057"},{"speaker":"山内委員","kind":"質問・要望","question":"今お答えいただきました３,０００ｔという、それは古紙ならびにペットボトルとか缶とかすべてを含んだ数字と考えてよろしいのでしょうか。その辺を鑑みまして、今度、持ち去り禁止の条例が制定されるということなんですけれども、その持ち去り禁止、いわゆる条例の制定に伴いまして、具体的な要綱とかそういうものが、もし今の時点でお答えできるのであれば、教えていただきたいなと思うんです。","respondent":"秋山資源循環推進課長","answer":"施行が７月を予定しておりますので、それまでの間にそういう細かいものを詰めて、７月より持ち去りの禁止の条例を施行して、持ち去り禁止の防止の行動をしていきたいというふうに考えております。","voiceIndex":125,"id":"exchange-058"},{"speaker":"山内委員","kind":"質問・要望","question":"この条例ですけれども、本当に大事な大事な条例になってくるのではないかなと考えていますので、皆様としっかりとお話し合いをしていただいて、それでしっかりとした条例をつくっていただきたいと思います。それから、あともう１点伺いたいのが、ごみを出す側、それからそれを回収する側の、これは一つの問題というか、これはどうなっているのかなと思うんです。","respondent":"秋山資源循環推進課長","answer":"古紙ですとかの、リサイクルの秩序というんですか、区民の方に出していただく、集団回収、行政回収に出していただいて区が収集して資源化をするという、そういうリサイクルの輪を乱す行為を禁止するという条例のつくりですので。","voiceIndex":127,"id":"exchange-059"},{"speaker":"山内委員","kind":"質問・要望","question":"わかりました。２月２９日の毎日新聞に、ペットボトルの預かり金という記事が載っていました。これはリターナブル化ということで、ペットボトルにデポジットを上乗せして販売するという回収が、環境大臣のほうから表明があったということなんですが、この件につきまして、品川区の見解をちょっと教えていただきたいと思います。","respondent":"秋山資源循環推進課長","answer":"業界のほうも、そういう形でペットボトルのリターナブル化については、まだ検討をしているような記事の内容でもございましたので、私どもとしては大臣の会見にありました研究会等の推移を見ていきたい、注目していきたいというふうに考えております。","voiceIndex":129,"id":"exchange-060"},{"speaker":"山内委員","kind":"確認","question":"次に廃棄物処理の手数料についてお伺いをいたします。これは、どこからどう見ても値上げをしたということがわかるんですけれども、改めて確認なんですけれども、１枚当たりの金額と、それから値上げ率というのを教えてください。","respondent":"秋山資源循環推進課長","answer":"事業系の有料ごみ処理券の金額の変更についてですけれども、券種が四つあります。１０ｌ券が１０枚セットです。","voiceIndex":131,"id":"exchange-061"},{"speaker":"山内委員","kind":"質問・要望","question":"これもまた確認をちょっとさせていただきたいんですけれども、事業系のごみの収集の仕方、これは家庭ごみと一緒に集めているのかなという認識があるんですが、具体的に事業系のごみの集め方を教えてください。","respondent":"秋山資源循環推進課長","answer":"それ以上の大規模な事業者は、一般廃棄物の収集運搬の許可業者というのがありますので、そちらのほうに収集を依頼して処理をするという、大きく分けて２通りということになってあります。","voiceIndex":133,"id":"exchange-062"},{"speaker":"山内委員","kind":"質問","question":"事業系のごみと、それから家庭系のごみを収集をして、これは清掃工場のほうへ持っていくわけですよね。ちょっと数字的にはあれなんですが、たしか払っているはずなんです。その場合、家庭系と事業系、いわゆる事業系のシールを貼ったものが一緒に混在されて持っていかれるということになると、その辺ちょっとどういう形で見分けているのかというのを教えてください。","respondent":"秋山資源循環推進課長","answer":"収集のときには、同じ収集車がシールを貼った袋と家庭系の袋と一緒に入れてしまいますので、重さを見分けるということはできないです。","voiceIndex":135,"id":"exchange-063"},{"speaker":"山内委員","kind":"質問・要望","question":"私は単純にその答弁を求めたいと思うんですが、それの仕分け方を今聞きたかったんですが、最後にそれだけ。","respondent":"秋山資源循環推進課長","answer":"ですから、一般の収集の中では仕分けてはいないです。","voiceIndex":137,"id":"exchange-064"},{"speaker":"本間委員","kind":"質問","question":"私は、６７ページ、区民斎場使用料と、７２ページから７３ページにかけて、中小企業センター使用料、そして７５ページ、自転車駐車場使用料についてお伺いします。最初に、なぎさ会館の件についてです。このなぎさ会館の利用状況について、ここ数年の利用実績と傾向について、簡単で結構ですが、教えてください。","respondent":"鷹倉区民課長","answer":"平成１９年度、今１月末現在で締めておりますが、現在のところ２７４件ということで、あと２カ月でおそらく３００件の台に乗るかなです。したがいまして、４００件のところにはちょっと届かないような状況が今のところ続いているという傾向です。","voiceIndex":140,"id":"exchange-065"},{"speaker":"本間委員","kind":"質問","question":"地域の人に大変利用されている状況が出てきておりますけれども、それだけにここを利用する方々からの、これまで何回か質問させていただいたことがありますが、幾つかの改善点について、例えば３階の和室、それからトイレ等々につきまして、改善された内容について教えてください。","respondent":"鷹倉区民課長","answer":"なかなか使いにくいようになっているわけですけれども、その中で便座等をかえたりして、できるだけ改善して、できるだけ区民の皆様に使っていただくように改善を、いままでもしてまいりましたし、これからもしていく予定です。","voiceIndex":142,"id":"exchange-066"},{"speaker":"本間委員","kind":"質問・要望","question":"少しずつ改善されているというふうなことです。去る先週の日曜日ですが、ある高齢者クラブの旅行会がございましたら、３０人そこそこの方が参加しているわけですけれども、その６割以上が、ちょっと座いすがないかと、あるいは低いいすがないかというふうなことを宿泊施設側に申し出ましたら、２人、３人どころか、やはり半数近くが要望したというようなことをお聞きしました。","respondent":"鷹倉区民課長","answer":"２０年近くかかるというようなお話を聞いておりましたから、平成２４年ぐらいに終わる予定というふうに聞いております。したがいまして、最初、都にお貸しするときに約款等を結んでいると思いますが、その現状回復の部分でどこまでしていただけるか、その部分だと思います。","voiceIndex":144,"id":"exchange-067"},{"speaker":"本間委員","kind":"質問・要望","question":"次に行きます。中小企業センターの使用料の件ですが、この中には、私どももこれまで懐かしい勤労者福祉会館時代のことを思い出すわけですが、非常に気軽に利用しやすい、低料金でまた気軽な立場で利用しやすいという場所なんですけれども、この中に昨年ですか、大規模改修をしたということのお話を伺っておりますが、あそこの中にカラオケ使用が可能な部屋が幾つありますか。","respondent":"金子産業振興課長","answer":"中小企業センターのカラオケ使用のお尋ねなんですけれども、私どもの部屋で防音の設備を施しておりますのが、大会議室ほか３部屋ありますので、食堂のほうは除きまして３部屋です。","voiceIndex":146,"id":"exchange-068"},{"speaker":"本間委員","kind":"質問","question":"カラオケができるというのは防音装置を施しているですけれども、そこでやはり何といいますか、無料貸し出しかもわかりませんけれども、カラオケの道具を持ち込みをして、これまでやってきた方がいらっしゃるわけですけれども、そういうことでなくして、あそこの中にカラオケ利用できるような装置というか、そういう道具が借りられるような方法がありますでしょうか。","respondent":"金子産業振興課長","answer":"設備のほうのお尋ねだと思いますけれども、カラオケ関係といいますか、そうでなくても音楽関係でさまざま使用をいただくようにできている部屋が、その３部屋ともそういう形で整っております。","voiceIndex":148,"id":"exchange-069"},{"speaker":"本間委員","kind":"意見","question":"最後になりますが、７５ページの自転車駐車場使用料の件ですが、年々、この定期利用、一時利用の数が増えてきておりますし、またその実績もここに出ておりますが、特に今回の場合には、一時利用が昨年と比べて大幅に増えてきております。この辺の新しい取り組みのポイントといいますか、ねらいはどこにあるのか、お知らせください。","respondent":"松嶋交通安全担当課長","answer":"一時利用が大幅に増えるですけれども、これは路上駐輪場を自転車とバイクそれぞれ、自転車につきましては１３０台、バイクにつきましては６０台分、これを増設ですけれども、新たにつくっております。そういったものを利用率の向上にということで計上しております。","voiceIndex":152,"id":"exchange-070"},{"speaker":"本間委員","kind":"意見","question":"それと同時に、また地域の事業者のご理解を得ながら、例えばイトーヨーカドーだとか阪急デパートだとか、あるいは品川郵便局というような形の中で、いろいろ事業者の力も得ているかと思いますが、その辺の部分はあらかじめ協力をお願いして無料というような形でされているのか、あるいは自然のままにしているのかという点についてお考えをお聞かせください。","respondent":"松嶋交通安全担当課長","answer":"私どもは区営の駐輪場というものは通勤、通学、買い物客、こういったものの利用に使ってもらっているわけでございまして、もちろんその中に阪急の買い物客だとかイトーヨーカドー、そういったところの買い物客、そういったものも当然この中の利用者の中には含まれているです。","voiceIndex":154,"id":"exchange-071"},{"speaker":"本間委員","kind":"質問","question":"非常に不勉強で申しわけなかったんですが、一時利用は無料なんですか。","respondent":"松嶋交通安全担当課長","answer":"一時利用は自転車につきましては１５０円、バイクにつきましては２５０円、有料です。","voiceIndex":156,"id":"exchange-072"},{"speaker":"本間委員","kind":"意見","question":"これも、やはり何回も申し上げておりますが、駅周辺の駐車の中で有料と、それから無料で置いているというふうな姿が、これはやはり特に日曜、祭日なんかに顕著に見られると思います。片一方でそのようになっている、無料であるということの中で、非常にアンバランスといいますか、区民の感情がなかなか割り切れないものが出てきていると思いますので、その辺ちょっと一言、考え方についてお知らせください。","respondent":"松嶋交通安全担当課長","answer":"そういったものはやはり集客、自分のところに来るお客様ですから、そういったものの収容施設等は、それぞれ事業者が責任を持って設置をしていただきたい、そういうものは以前から申し入れているところです。","voiceIndex":158,"id":"exchange-073"},{"speaker":"本間委員","kind":"質問・要望","question":"まだまだＪＲの駅の下の部分の駐輪場だとかいろいろありますけれども、やはりお金を払ってきちっと管理をしていただく部分と、いわゆる無造作にいろいろ置かれて交通の障害になるような部分があってはならないということで、何かの機会にやはりご指導いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":160,"id":"exchange-074"},{"speaker":"武内委員","kind":"質問","question":"初めに民生費負担のほうと補助金のほうと、あわせてお聞きしたいと思いますが、児童扶養手当が、この４月１日から一部改定が行われる予定となっておりますけれども、今回のこの国庫補助金、国庫負担金の児童扶養手当の約２億５,７００万円ぐらいですか、このものが、そうしたことの改正の見込んだ予算になっているかどうかということと、それから、母子家庭の自立支援給付金事業補助金ですね。","respondent":"諸岡児童課長","answer":"これを受けまして、私どもでは早速受給者の方々にお知らせをしなければならないということで、事務手続等もありますので、内部で事務手続等についての検討を行いまして、２月２９日付、先週ですけれども、児童扶養手当の受給に関する重要なお知らせということで。","voiceIndex":162,"id":"exchange-075"},{"speaker":"武内委員","kind":"質問","question":"母子家庭の自立支援給付のほうのお話が抜けていたと思うので、あとでお聞きしたいと思うんですが、そうすると、ちょっと時期的なもので予算書には正確なところは反映されていないというふうに受けとめたんですけれども、そうしますと、当初は大幅な、ほとんどの母子家庭の方が２分の１を最大限にして削減される予定という中で。","respondent":"諸岡児童課長","answer":"この方に対しては、自立支援のプログラムに参加していただくとか、そういった方法をとって、お勧めをして、就労活動を行っていただくというようなことで、支援をしていきたいというふうに思っております。","voiceIndex":164,"id":"exchange-076"},{"speaker":"武内委員","kind":"質問","question":"さっきも申し上げたんですけれども、もう一つの９４ページのほうの母子家庭自立支援給付の補助金が新たに昨年から６０万円増えている。これの内容も教えてください。","respondent":"諸岡児童課長","answer":"若干増えておりますのは、これは、母子家庭の自立支援プログラム事業というのも平成２０年度から新たに始まる予定です。これは児童課のほうに、ハローワークのＯＢの方を非常勤として配置をして、個別のプログラムを策定するというものです。","voiceIndex":166,"id":"exchange-077"},{"speaker":"武内委員","kind":"確認","question":"そうすると、歳出のほうで出てくる３６０万８,０００円という自立支援プログラム策定費用というのが、この歳入のほうの６０万円という理解でいいんでしょうか。わかりました。対象の方にはお知らせを郵送しますのでご確認ください」という内容だけなんです。「一部の方」というふうになっているんですけれどもこれは大丈夫なのかというご質問をいただきました。","respondent":"諸岡児童課長","answer":"政令によりますと、もちろん今、委員がおっしゃいましたように、働いていること、それから求職活動を行っているですので、実際には就労していなくても、それに向けていろいろ努力をなさっている方、こういう方々も一部支給適用除外の対象となってまいります。","voiceIndex":168,"id":"exchange-078"},{"speaker":"武内委員","kind":"質問","question":"そうしますと、また細かい部分になるとあれなんですけれども、もう既に書類を送っているということなので、おそらくそれが何名ぐらいかというのはわかっていらっしゃると思うんですけれども、そうしたものが行った方で、例えばまた区のほうに問い合わせがあって、こういうのが来たけれどもと、内容はちょっとわかりませんけれども、そこで例えば場合によってはそこでこう、いろいろなお話し合いの中で。","respondent":"諸岡児童課長","answer":"そういう方には、窓口までご相談においでくださいということの中で、お越しくださった方には先ほど申し上げましたプログラムの策定事業、個別のケースワークということで、策定委員がきめ細かくいろいろ支援をする。","voiceIndex":170,"id":"exchange-079"},{"speaker":"武内委員","kind":"質問・要望","question":"それで、ちょっと歳出のほうになっちゃうかもしれないんですけれども、例えば今母子家庭の話になったんですけれども、隣の港区ですけれども、父子家庭に対しても同じような児童扶養手当と、今、国では母子家庭に限られているわけですけれども、昨年のたしか予算特別委員会の中で、どなたか委員の質問へのご答弁で、たしか品川区は３５１人という１８歳未満のお子さんのいる。","respondent":"諸岡児童課長","answer":"やはり東京都の行いました調査によりましても、就労している母親のうち、約５割ぐらいが非正規の就労ということで、収入もかなり低いということで、やはり優先的には母子家庭への経済的支援が優先かなというふうに思っています。","voiceIndex":172,"id":"exchange-080"},{"speaker":"武内委員","kind":"質問","question":"時間がなくなったので、しながわ水族館の件は午前中も出て、減収を見込んでいると、非常に来館者が少ないということなんですが、ちょっと関連しているので、今後どのようにそれを盛り上げていくかということで、先般の一般質問で区長からご答弁で、ヘブンアーティストをしながわ水族館のほうでも今申請を出しているんだという話なんですけれども、何かそれは、そうしたものにつながっていくのかどうかだけ。","respondent":"藤田道路公園課長","answer":"現在ヘブンアーティストのほうは、東京都のほうと細かい調整に入ってあります。当然ながら、さまざまな形で水族館のエリアで皆さんに楽しんでいただきたいということで考えておりますので、こうした活動も入館者の増につながってくるだろうというふうに考えているものです。","voiceIndex":174,"id":"exchange-081"},{"speaker":"藤原委員","kind":"質問","question":"１２８ページの特別区競馬組合についてと、１０６ページの福祉保健基盤等包括補助金などを含めた都の補助金についてお伺いします。競馬組合についてお伺いします。配分金も落ちていくと予想していたんですけれども、不況とかいろいろあると思うんですけれども、そんな中で、まず配分金が減っていることは間違いないのかということと、この３年ぐらいの状況についてお伺いします。","respondent":"桑村総務課長","answer":"その意味では、来年の競馬組合の予算も、分配金についてはまだ計上できないというようなことは予算で決められているものです。","voiceIndex":177,"id":"exchange-082"},{"speaker":"藤原委員","kind":"質問","question":"分配金と配分金のシステムがちょっと変わったという説明を受けたんですけれども、言葉は悪いかもしれないんですけれども、じり貧といいますか、になってきているという感覚はあるんですね。そういう意味において、これからどのように考えているか、もう少し見解をお伺いさせてください。","respondent":"桑村総務課長","answer":"本年の平成２０年の競馬組合のほうの方針ですけれども、その意味では、本来の趣旨のいわゆる２３区の財政に寄与できるように頑張るんだというのが一つの方針で、もう一つは大井競馬の本場の売り上げがそういう意味では落ちてきているので。","voiceIndex":179,"id":"exchange-083"},{"speaker":"藤原委員","kind":"質問","question":"今も課長のほうからそういう形でご答弁いただいたんですけれども、品川区にあるわけですよね。それで、いわゆる本場に行ってくれることが一番の基本ですよというお話なんですけれども、例えば担当課長として月一遍とか大井競馬に行っていますか。競馬場にどんどん皆さん行ってほしいということの品川区としての努力、また担当課長の努力というのはどの辺にあらわれているんでしょうか。","respondent":"桑村総務課長","answer":"入場者数については、かなり増えてきているのは事実です。ただ、実際上、入場した人がどれだけお金をその場で落とすかということについては、昔に比べれば１人当たりの売り上げははるかに落ちているわけですね。そういう意味では非常に多くの方が集まっていただいている。","voiceIndex":181,"id":"exchange-084"},{"speaker":"藤原委員","kind":"確認","question":"１０６ページの都の補助金等についてお伺いします。昨日の審議でも説明がありましたけれども、福祉施策の包括補助金が分割されて、目的別に細分化されたということなんですけれども、この辺について、確認の意味なんですけれども、もう一度説明をしていただけますか。","respondent":"日下部企画財政課長","answer":"今ご質問にもございました福祉包括の補助金ということで、福祉から医療関係、保健関係、いままで一本でやっておりました。それを大ざっぱに申し上げれば福祉保健、それから障害者、高齢社会、医療保険ということで、大きく四つの分野に再編成をしたというものです。","voiceIndex":183,"id":"exchange-085"},{"speaker":"藤原委員","kind":"質問","question":"それは特別区にとってはプラスになるんでしょうか。都の税収がすごく上がっていますよね。まさかないと思うんですけれども、そういうことをやって、先々、補助金全体を減らすという方向を都が考えて、いろいろこういうことをしているんでしょうか。","respondent":"日下部企画財政課長","answer":"金額の面については、いろいろ心配な面がないわけではないんですが、この間の経緯を見ますと比較的金額も増えておりますし、その辺の心配はないだろう、このように考えております。","voiceIndex":185,"id":"exchange-086"},{"speaker":"本多委員","kind":"意見","question":"６０ページの財政調整交付金の対前年１０億円の増、３８５億円というところを聞いていきたいと思います。区内の入ってくる企業、出ていく企業、また２３区内全体といいますか、その辺が把握されているのか、また直接の事務でないのでなかなか難しいのかもしれないんですけれども、その傾向についてお聞かせください。","respondent":"日下部企画財政課長","answer":"本社機能を含めて企業の動向ということでありますけれども、私どもも、さっきご質問にありましたような形での、例えば税務の関係でありますとか、そういう直接的なやりとりがないということもありまして、なかなかその把握が難しいんですけれども、ただこの間。","voiceIndex":188,"id":"exchange-087"},{"speaker":"本多委員","kind":"質問・要望","question":"なかなか直接の事務ではないので難しいとは思うんですが、調整税などの区分で市町村民税の法人分があるわけですけれども、一律的に、このほかの区分と項目、同じように把握しづらいのか、特にこの辺が市町村民税の法人分が把握しづらいのか、その辺だけちょっと教えていただきたいのですが。","respondent":"日下部企画財政課長","answer":"私ども実は財調全体の動きをとらえるときに、例えば品川区でどのくらいの、では例えば直接徴収した場合にどのぐらい入ってくるのかとか、そういうことも含めてかなり注意をしているんですが、東京都の税収の把握の仕方がいろいろな、例えば本社で一括納付とか。","voiceIndex":190,"id":"exchange-088"},{"speaker":"本多委員","kind":"質問・要望","question":"財調以外で、もし歳入全般ですとか経済効果ですとか、もしその辺の傾向がわかれば教えていただきたいんです。かなり昼間人口が伸びておりますので、もちろん正確な数字等は難しいでしょうが、傾向を教えていただきたいんです。","respondent":"日下部企画財政課長","answer":"そうすると、例えばできるだけ近くに住もうではないか。そうすると比較的若い世代、現役世代が品川区に居住をするという、そういう可能性にも結びついてきますので、いろいろそういう面からも、できる限りこれからも把握に努めていきたい、このように考えております。","voiceIndex":192,"id":"exchange-089"},{"speaker":"本多委員","kind":"意見","question":"いままでなかなか実態が把握しづらいので、一つの傾向といいますか、データがないというふうに私も認識していたんですけれども、豊田市の事例を学ばせていただきまして、私自身の認識も変わりまして、自治体と企業との連携というのはもっと積極的にあるべきかなと、私自身の認識が変わったわけなんです。","respondent":"日下部企画財政課長","answer":"ただ企業との連携ということで言いますと、私も以前福祉の分野におりましたときに、企業の方がボランティア、企業の社会的貢献ということで、福祉の、例えば障害者の運動会にもうそれこそ会社ぐるみでお手伝いに来ていただくとか、そういうケースもありますし。","voiceIndex":194,"id":"exchange-090"},{"speaker":"本多委員","kind":"質問・要望","question":"そういうのとはまた別に、例えば区内の野球チームですとか、学校ですとか、そういう地域の企業との結びつきをもっと図る必要があるんじゃないかと、そういう機運が高まっておりまして、企業が区内にあるわけですから、日本ハムの野球チームが、例えばシーズンオフに１年間のうち１日でもいいから野球教室を開催したり、具体的にそういう要望が直接もう進んでおりますので、そういうところをぜひ把握されて。","respondent":"富田生涯学習課長","answer":"ご指摘の日本ハムが大崎に移転をしてきた、また、楽天が東品川に昨年移転してきておりますが、そこでの機器の寄贈等を先週受けたわけでありますけれども、そうした企業のＣＳＲ、地域貢献、社会貢献といったところと、区内のそういった青少年、少年少女を含めたスポーツの普及。","voiceIndex":196,"id":"exchange-091"},{"speaker":"高橋委員","kind":"質問","question":"５１ページから５３ページのところの特別区税で、先ほどちょっとカードの支払いのことがあったのですが、手数料の問題があって今後検討されるというお答えがあったんですが、こちらの税をコンビニエンスストアで納められるということがあるんですが、コンビニエンスストアの場合の手数料というのは幾らなんでしょうか。","respondent":"武内税務課長","answer":"１件につき５７円です。","voiceIndex":199,"id":"exchange-092"},{"speaker":"高橋委員","kind":"質問・要望","question":"そうすると、５３ページの軽自動車税のところで、例えばこれが軽自動車税というのは２,０００円ちょっとでしょうか。これは要望で結構です。それで、この５１ページから５３ページに滞納の収入云々というのがあるんですが、滞納者に対して先ほどちょっとお話があったのですが、どのような督促をされるのか、もう一度確認したいので、お願いします。","respondent":"武内税務課長","answer":"現年度の、お話したとおり普通徴収の場合、４回に分けてお支払いいただくのですけれども、その納期が第１期ですと６月３０日になるわけです。それで１カ月間を過ぎますと、督促状というのを発付します。","voiceIndex":201,"id":"exchange-093"},{"speaker":"高橋委員","kind":"質問","question":"職員の方がご苦労されて、たくさんそういうふうにしているんですが、ある地方自治体ではシルバー人材センターなどに督促業務を委託して電話の督促をしたり、あるいは練馬区などではもう督促自体を民間委託したりしているんですが、いろいろそういう収納率の向上や、あとは職員の方がほかの本来の業務に専念できるような形で、こういう民間委託についてはどうお考えでしょうか。","respondent":"武内税務課長","answer":"電話催告要員ということで、各自治体では民間に委託したりしているところもありますけれども、品川区におきましてはご案内のとおり、現年の収納率は９８％以上ということですので、今すぐ、そういう委託をするということは考えておりません。","voiceIndex":203,"id":"exchange-094"},{"speaker":"高橋委員","kind":"質問・要望","question":"今の滞納に関連してなんですが、この滞納の情報が、例えば区民税を納めていない方、あるいはそのほか、いろいろなものを納めていない方というのは、こちらの役所のほうで一元化はしていらっしゃるんでしょうか。そうすれば一遍にこれとこれをというふうな、訪問して、ご苦労されていると思うんですが、区のほうが働きかけやすいと思うんですが、いかがでしょうか。","respondent":"武内税務課長","answer":"区の税、国保、また保育料とたくさん区民の方に収納というかかわりが出てくるんですけれども、現在のところ、その辺の情報交換というんですか、そういう滞納者のリストをお互いに持ち合わせるということは行っておりません。","voiceIndex":205,"id":"exchange-095"},{"speaker":"高橋委員","kind":"質問","question":"ちょっと今後いろいろ検討していただけるとありがたいと思います。役所のほうでああいうのを発行するときには領収書が出ますから、領収書が必要だったり、何かいろいろな法令の仕組みで、下の食堂にあるようなああいう感じので、シールみたいなので手数料を発行するような形にはできないんでしょうか。何か法令でだめだということになっているのでしょうか。","respondent":"小野情報システム課長","answer":"手数料のお話で、現在、地方自治法の２３１条の２というところで、手数料等の納付については、現金、証紙、口座振替、証券、クレジットカードという形で例が挙げられておりまして、それで納付をするという形になっております。","voiceIndex":207,"id":"exchange-096"},{"speaker":"高橋委員","kind":"質問","question":"小銭を用意できなかったり、職員の方が現金を扱ったりするといろいろあるので、もし可能ならば、その自販機を導入していただけるとありがたいと思います。どうですか。","respondent":"小野情報システム課長","answer":"委員お尋ねの部分については、いろいろな手数料について、現金を直接扱うのではなくて、ほかのいろいろな方法がとれるのではないかというご質問かというふうに承りますけれども、実際の区民の利便性等々、いまの状況の中で。","voiceIndex":211,"id":"exchange-097"},{"speaker":"高橋委員","kind":"質問","question":"学校等いろいろなところの耐震工事はされているんですけれども、そういった文化財の中で、せっかくの貴重な文化財なんですが、地震で壊れたり倒れたり、お寺の鐘が落ちたりとかあったりするとあれなんですが、そういった調査をする予定はありますでしょうか。","respondent":"富田生涯学習課長","answer":"その他、区の指定文化財等については、修理の補助金というような形で区のほうで支出をしているものが別途あります。","voiceIndex":213,"id":"exchange-098"},{"speaker":"中塚委員","kind":"質問・要望","question":"冒頭のやりとりの中で、区民税の徴収について、民間委託のことの中で、今すぐには考えていないというお話が、ちょっと意味がよくわからなかったので教えていただきたいと思います。","respondent":"武内税務課長","answer":"昨年の年度当初、電話催告要員というのはほかの自治体で、先ほど委員の質問があったシルバー人材センター、またあるいは人材派遣のそういう会社が電話催告要員で行っている事例が、先ほどあったように世田谷区とほかの自治体で何区かありましたので、それも検討する中で。","voiceIndex":216,"id":"exchange-099"},{"speaker":"中塚委員","kind":"質問・要望","question":"要は、住民税というのは個人情報のかたまりですよね。前年度の所得、家族の方々の状況、それらの情報を民間委託した際に、個人情報がしっかり守られるのかどうか、そこをどういうふうに検討しているのか、ご答弁いただきたい。私はこれは絶対にやるべきではないと考えています。もう一つは、住民税滞納にはさまざまな理由や実態があるわけですよね。それへの把握はどうなっているのか、教えてください。","respondent":"武内税務課長","answer":"それと滞納者の現状において、どういうふうに考えているかということですけれども、昨年の行財政改革特別委員会の中でもお話したとおり、システムの改修等を含めて、職員がそういう対応をした際にプログラム化を充実させていく中で。","voiceIndex":218,"id":"exchange-100"},{"speaker":"中塚委員","kind":"質問・要望","question":"考えていないということですけれども、すみません、少し説明いただきたいのが、臨時雇用でやるというところが、どの部分をやるということなのか、その中身がよくわからなくて心配をしているんです。そこを教えていただけますか。","respondent":"武内税務課長","answer":"現年分の滞納にならない、いわゆる納め忘れ、いわゆる納期があります。それを電話連絡によって、要するに督促をするのではなくて、ご入金いただけたでしょうかというような連絡を、非常勤職員を採用して行っていくです。","voiceIndex":220,"id":"exchange-101"},{"speaker":"中塚委員","kind":"質問","question":"ということは、その方は、区民の方々の督促を、おそらく郵送でしょうから、住所とか、お名前はもちろん、その人は個人情報を知ることができるわけですよね。そういった個人情報は一体どうやって守るのか。庁内の中でそれはしっかり、それが今の説明の中でよくわからない。教えていただけますか。","respondent":"早津区民生活事業部次長","answer":"今回税務課として採用するのは、区のＯＢ職員を非常勤職員として任用する、こういうものです。","voiceIndex":222,"id":"exchange-102"},{"speaker":"中塚委員","kind":"意見","question":"最後になりますけれども、税の徴収は本当に個人情報のかたまりです。一人ひとりのご家庭にさまざまな事情があります。私はきちんと区の正規の職員でしっかりやる事務、そういうふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":224,"id":"exchange-103"},{"speaker":"若林委員","kind":"質問・要望","question":"こういう構造的な２０億円がこれから入ってこなくなるという中で税収が増えてきて、そういう中で、区のほうといたしましては、この歳入全般に関しまして、平成２０年度においてはどのような努力をして、財源の確保といいますか、そういう努力をされたのかというのを一言成果としてお話をいただきたいというふうに思います。","respondent":"日下部企画財政課長","answer":"ですから、そういった意味では比較的そういう今の状況に支えられている面がありますけれども、ただ、やはりこの間のご質問にもございましたけれども、しっかりした税収の確保等につきましては、さらに一層努力すべきでありますし、さらに例えば特定財源の面におきましては。","voiceIndex":226,"id":"exchange-104"},{"speaker":"若林委員","kind":"質問","question":"いままで品川区の区政の運営としても健全財政ということを再三、予算編成または決算の折には声があったわけですけれども、今回の新しい財政健全化の法律の制定に当たって、今後の品川区の健全財政運営がこのようにされているんだ、またそのように区民の方に広く広報される、そのような方向性というのはどのようにお考えでしょうか。","respondent":"日下部企画財政課長","answer":"これは一般会計だけではなくて、特別会計からあるいは関連する例えば一部事務組合でありますとか、あるいは広い意味では第三セクターも含めて、四つほど指標がありますけれども、それを平成１９年度決算を踏まえて、翌年の秋ということでありますから。","voiceIndex":228,"id":"exchange-105"},{"speaker":"若林委員","kind":"意見","question":"平成１９年度の決算から、また新しい指標に基づいたお知らせを区民にお知らせをしなければいけないということで、平成１８年度まで毎年区報に秋口、確かに決算の状況が出ております。ぜひ平成１９年度、新しい仕組みの中での広報ということになりますので、昨日でしたか、企画財政課長のほうからも、いわゆる家の会計の例を引きながら、大変わかりやすくといいますか、身近な例でご説明がありました。","respondent":"日下部企画財政課長","answer":"この新しい秋口からの公表に当たりましても、そのように最大限努力をしてまいりたいと、このように考えております。","voiceIndex":230,"id":"exchange-106"},{"speaker":"若林委員","kind":"質問・要望","question":"品川区においても、自治体の財政収入においては、一番いやなのが見通しの立たない、また乱高下が非常に激しい、こういうあり方というのが非常に厳しい、予算も立てられない、見通しも立たないという一因にはなると思いますので、一つは今あるのかどうなのかわかりませんけれども、あったら教えていただきたいんですが、中長期的な歳入の、国庫、都の支出金との関連もありますけれども。","respondent":"日下部企画財政課長","answer":"財政運営は単年度ではもちろん予算でご提案していますけれども、その一番のベースというのは中期財政計画といいまして、実施計画を３年スパンで策定をして、これをもとに毎年度、これをローリングいたしまして、それをベースにして。","voiceIndex":232,"id":"exchange-107"},{"speaker":"若林委員","kind":"意見","question":"では１２０ページの基金利子、この一つ一つではなくて、これはたしか多分特定財源だと思いますので、ここら辺の利子がこういうふうに項目で支出をされているんですよという、そういう透明性といいますか、その使途のあり方についてはどのようにされているのかというのをお願いします。","respondent":"日下部企画財政課長","answer":"あるいは基金の運用益を活用する基金につきましてはそれを回しているです。","voiceIndex":234,"id":"exchange-108"},{"speaker":"市川委員","kind":"質問・要望","question":"予算特別委員会の資料で配られた１１ページの教育費の学事制度検討経費、それから同じページの学校安全対策費について、それから款別の８３ページの歳入の品川中央公園多目的広場について、それから１３９ページの議会費について伺います。学事制度検討経費について伺います。これは予算書のどこに入っている経費なのでしょうか、教えていただきたいんです。","respondent":"日下部企画財政課長","answer":"今ご質問にございました学事制度審議会の経費は、歳入につきましては、１０２ページをお開きいただきまして、新教育システム開発プログラム事業費、これが財源として見込んでいるところです。","voiceIndex":237,"id":"exchange-109"},{"speaker":"市川委員","kind":"質問・要望","question":"１０２ページの新教育システム開発プログラム事業費なんですけれども、２００７年度予算と比較すると倍近くに増えているんですけれども、この学事制度検討経費のほかに、どんな事業があるのか教えていただきたいんです。それと、今年増えた事業がありましたら、それもあわせてお願いいたします。","respondent":"古里学務課長","answer":"１０２ページの新教育システム開発プログラム事業費ですが、学事制度審議会経費として１０６万９,０００円、そのほかに一貫教育の検証経費として３,０００万円余が計上され、合わせて３,４７１万１,０００円を計上したものです。","voiceIndex":239,"id":"exchange-110"},{"speaker":"市川委員","kind":"質問","question":"学事制度検討経費が国の委託として採択されたというか、その経過についてお聞きするんですけれども、いつごろどういう基準でつくられたものなのか、また、品川区のほかに、この委託金を受けたところがあるのか、おわかりでしたらお聞きします。","respondent":"古里学務課長","answer":"この新教育システム開発プログラムというのは、文部科学省が平成１８年に教育改革を推進するに当たって、義務教育改革のアイデアを将来の制度改正を見据えて実際にモデル試行し、新たなシステム導入の可能性の検証を行うことを目的として設置をされた実施委託の事業です。","voiceIndex":241,"id":"exchange-111"},{"speaker":"市川委員","kind":"質問・要望","question":"国の委託を受けているということは、国が進めようということを求められているというふうにもとられかねないんですけれども、そういう把握でよろしいんでしょうか。","respondent":"古里学務課長","answer":"先ほど申し上げたとおり、文部科学省は義務教育改革のアイデア、こうしたものを将来の制度改正を見据えて全国の自治体でモデル的な試行、そうしたものを行っているものを集めて、それを検証していって将来の施策に生かしていこうというものでございまして、例えば一貫教育の検証。","voiceIndex":243,"id":"exchange-112"},{"speaker":"市川委員","kind":"質問・要望","question":"学事制度審議会の設置要綱では公開、非公開は審議会で決められるということになっていますので、ぜひ公開して進めることを働きかけていただきたいというふうに要望するんですけれども、この点はいかがでしょうか。","respondent":"古里学務課長","answer":"学事制度審議会については、中間まとめをなるべく早くまとめ、区民に公開するとともに、その後、パブリックコメント等も予定をしています。","voiceIndex":245,"id":"exchange-113"},{"speaker":"市川委員","kind":"質問・要望","question":"非公開で行っていくということなんですけれども、非公開であっても秘密会ではないわけですから、議事録の公開だけでもするほうが自然ではないかなと思います。この議事録の公開というところを審議会の中で強く言っていただきたいと思うんですけれども、この辺はいかがでしょうか。","respondent":"古里学務課長","answer":"審議会については、教育委員会が諮問した内容、これを真剣に、それから幅広く検討するために、非公開という形で審議会の中で決められてスタートしているものです。","voiceIndex":247,"id":"exchange-114"},{"speaker":"市川委員","kind":"質問・要望","question":"事務局が意見を述べるというよりも、そういう意見も挙がっているのでお諮りいただきたいという意味で申し上げました。次に、同じ資料の１１ページの学校安全対策費について伺います。この資料によると都の補助金というふうになっているんですけれども、この事業の内容というのは同じものなんでしょうか。","respondent":"市川庶務課長","answer":"ご質問にあった、昨年まで委託事業で組んでおりましたのは、この指導員、交通安全指導、あるいは通学監視に当たる指導員の講習会の講師の育成という面で東京都の事業を使っておりましたが、この指導に当たる者は大半は警察の関係者であるとか。","voiceIndex":249,"id":"exchange-115"},{"speaker":"市川委員","kind":"質問","question":"ちょっと私も慣れていなくてわからないので、一般的にどういうケースが委託から補助になるのかとか、何かそういうところがあるのか、その辺を伺います。そういうケースがほかにもあるのか、その点も教えてください。","respondent":"日下部企画財政課長","answer":"あるいは財政援助的な性格も強い。そういう意味では若干性格が異なりますので、あまり事例としては多くない、このように承知しております。","voiceIndex":251,"id":"exchange-116"},{"speaker":"市川委員","kind":"質問","question":"次の質問なんですけれども、１３９ページの議会費について伺います。本会議録・委員会記録作成経費と、それから年報作成等が少しずつですが２００７年度予算より減額となっているんですが、この辺は何か理由があるんでしょうか、伺います。","respondent":"市岡区議会事務局長","answer":"これは一言で言えば、これまでの事業執行の効率化を目指して職員が努力した成果が単価の下落等につながっている、こういうものです。","voiceIndex":253,"id":"exchange-117"},{"speaker":"市川委員","kind":"質問","question":"地方自治法では、議会は地方公共団体の長がこれを招集するというふうにありますので、この質問は区長にお尋ねするのが筋かなというふうに思うんですけれども、区のほうは１月から日曜日の開庁も始めていたり、また平成２０年度の施政方針では、区長は区民にとって身近な区政の推進というのを掲げられているんですけれども、現在、品川区は平日に議会が開催されているんですけれども。","respondent":"市岡区議会事務局長","answer":"地方自治法上の招集権を基礎に区長のほうにそれをお尋ねになるというのは、これはむしろ議会運営の内容を議会が長のほうにげたを預けるような議論ですので、これはしかるべき議会の中でしっかりじっくり議論すべき内容だろうというふうに考えます。","voiceIndex":255,"id":"exchange-118"},{"speaker":"市川委員","kind":"質問","question":"わかりました。次に、品川中央公園の多目的広場について伺います。８３ページです。多目的広場の使用状況で、一般開放の利用率がどのように推移しているのか、お聞きします。","respondent":"富田生涯学習課長","answer":"こちらについて、全体の利用に対する一般開放の割合ですが、平成１７年度は１２.７％、平成１８年度につきましては１４.５％ということで、一般開放が増えております。本年度につきましても、これは昨年末までの状況ですが、平成１８年度と同様の１４.５％となっております。","voiceIndex":257,"id":"exchange-119"},{"speaker":"市川委員","kind":"質問・要望","question":"徐々に一般開放の利用が増えているというようなことがわかりました。生活者ネットワークは、以前、予算特別委員会の質問で、一般開放がされていることがわかるように、そういう表示をしてほしいというふうに求めましたけれども、何かこの点について工夫をされているというようなことがあるのか、お聞きします。","respondent":"藤田道路公園課長","answer":"中央公園のほうですけれども、まず、現地で皆さんにわかっていただくのが一番だというふうに考えてありますので、現地のほうに貼り出すということと、あとは知識、その辺よくご理解していただいている方については、ネット上で見ていただければ。","voiceIndex":259,"id":"exchange-120"},{"speaker":"市川委員","kind":"質問・要望","question":"品川区文化芸術・スポーツのまちづくり条例も４月から施行されますけれども、区民が広くスポーツを親しめる施設の開放というのも、また求められています。以前にも月１回でもいいので、区民への無料開放日の設置を要望したんですけれども、品川区文化芸術・スポーツのまちづくり条例にあわせて、区民への無料開放日の設置をぜひお願いしたいと思いますけれども、この辺についてのお考えをお聞かせください。","respondent":"富田生涯学習課長","answer":"先ほども申しましたように、この運動施設は有料の施設でありますということで、無料の利用日を設定する考えはありません。有料でも多くの方々にご利用いただいている状況があるです。","voiceIndex":261,"id":"exchange-121"},{"speaker":"市川委員","kind":"質問・要望","question":"有料の施設であるということですけれども、子どもたちの広く遊べる場所の確保ということも大切なことかと思いますので、ぜひ前向きに検討していただきたいということで、要望して終わりにいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":263,"id":"exchange-122"},{"speaker":"川西委員","kind":"質問","question":"一つは区税収入、二つ目は６２ページ、保育園保育料、三つ目は６６ページの集会所使用料、大きなテーマはここです。企画財政課長の説明の中では、一言で「景気回復の傾向」ということをおっしゃいましたけれども、この区民税の税収の伸びをどういうふうに分析していらっしゃるのか、伺います。二つ目は保育園保育料です。これは、なぜこのように使用回数が違うのか、その辺について伺います。","respondent":"武内税務課長、小林保育課長、中山地域活動課長","answer":"この間の税制改正による大きなところでは、ご存じのとおり、平成１８年に定率減税の廃止ということがありまして、そういう税制改正の要素もあるです。それに対しまして、階層の構造による若干のプラスの要素を加えましても、全体としてはそれだけであれば減収が見込まれるところですが。そのほかに、例えば階段の利用であるとか、西区民集会所などはエレベーターがないとか、そういう施設の対応の差。","voiceIndex":265,"id":"exchange-123"},{"speaker":"川西委員","kind":"質問・要望","question":"質問しなかったんですけれども、答えていただいて、ありがとうございました。区長の施政方針の中にもありますように、これからもっともっと地域コミュニティを、集会所、地域センターを中核として、これから地域コミュニティをどんどん拡大していこうとするときに、やはりこの集会所、地域センターの整備というものを十分お考えいただきたいなというふうに要望して、時間を余らせて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":269,"id":"exchange-124"},{"speaker":"松澤委員","kind":"質問","question":"何点かお聞きします。１点目は７７ページの１２款使用料及び手数料、１項使用料、５目土木使用料、６節区民住宅使用料。区民住宅使用料の中に、駐車場２４２台バイク１０台というふうにありますけれども、これの駐車場の料金はどんなものになっているのか、お聞きしたいと思います。","respondent":"齋藤住宅課長","answer":"バイクにつきましては３,０００円、自動車につきましては住宅ごとに違いがありまして、２万５,０００円から３万円、住宅ごとに違います。","voiceIndex":271,"id":"exchange-125"},{"speaker":"松澤委員","kind":"質問","question":"思っているんですけれども、このために住宅をつくって、これが借上型２９８戸、建設型が７５８戸あります。長く住み続けるうちには、子どもたちがだんだん大きくなっていく。先ほどの自転車がそうですよね。買いかえていくわけですから。やはり高校生なり大学生になる。バイクも欲しいなという子どももいると思うんですけれども、なぜバイクの駐車場は少ないのか、この辺についてお聞きしたいと思います。","respondent":"齋藤住宅課長","answer":"バイクの置き場はファミーユ西五反田にしか設置してございません。","voiceIndex":273,"id":"exchange-126"},{"speaker":"松澤委員","kind":"質問・要望","question":"でも西五反田にはちゃんとバイクの駐車場がある。私はそういうふうに思うんですけれども、なぜバイクがいけないのか。ではどこに置くか。自転車に乗っている子がバイクが欲しい、自転車に今度乗らなくなるわけですから、やはり駐輪場をバイク置き場に替えるとか、そんなことはできないわけがないので、その考え方、なぜ本当に替えられないのかという要望が多いので、その考え方をお聞きしたいと思います。","respondent":"齋藤住宅課長","answer":"基本的に住宅を建てる場合につきましては、区の駐輪場設置の義務づけがあります。は東京都に駐車場設置の義務づけがあります。","voiceIndex":275,"id":"exchange-127"},{"speaker":"松澤委員","kind":"質問・要望","question":"置いていないというのはわかりましたけれども、ここでバイクでも料金を取っているんですから、駐車料金を取っているのでしたら、やはり要望があったら置く努力をする。区民からやはり要望があったら置く努力をするということを、課長、答えていただきたい。規則があるからではなくて。その辺のことを聞きたい。そのために質問をしているので、もう一度ご答弁をお願いします。","respondent":"齋藤住宅課長","answer":"それで、私は住宅課長ではありますが、建築紛争の課長もしておりまして、民間の事業者には、地域の方と約束したことは必ず守れと、こういうふうに指導をしておりまして、建って３年４年経たないのに、地域の皆さんとお約束を違えるという、こういうこともできませんので。","voiceIndex":277,"id":"exchange-128"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはりいろいろな声を聞きながら、話し合いを進めていただきたいと思います。この減った理由は何かということと、中国残留邦人等支援事業費については午前中も質疑が出ましたけれども、裁判があって、その結果、議員立法になったというんですけれども、どういうような裁判があって、どういう結果になって、どういう賛成論の中で議員立法になったかということをもっと詳しくお教えいただきたいと思います。","respondent":"志村生活福祉課長","answer":"補正予算のときにもだいぶ高額な減額補正だということでご質問もいただきました。ということで、現在、私どもの所管しております生活保護者、補正予算のときもご説明しましたとおり３,２００世帯、３,８００人の台で推移をしています。","voiceIndex":279,"id":"exchange-129"},{"speaker":"松澤委員","kind":"質問","question":"この中で、今の話ですと、ベースが生活保護ですから、生活保護という、おれたち帰ってきてこんなに苦労して、生活保護はないだろうという中で、今度はそれを議員立法で変えていった。名前は変わりましたけれども、内容的にはどうなのかなという気がします。先ほどの午前中の話ですと３９人いるということで、生活保護を受けている方がたしか２１人ですか。その辺のことをちょっと聞きたいと思います。","respondent":"志村生活福祉課長","answer":"ですので、６万６,０００円が今度新たに４月１日から給付されます。ですけれども、それについては生活保護の範疇、それから今回の支援給付の中では、それを収入とカウントいたしません。ですので、現在生活保護を受けている方は、そのまま支援給付に移行してまいります。","voiceIndex":281,"id":"exchange-130"},{"speaker":"松澤委員","kind":"質問","question":"この内容については、民生費のほうなんでしょうけれども、相談員が置かれるということなんですけれども、相談窓口ですね、当然ながら、この方たちはいままでですと、生活福祉課の中で保護係の中で対応されていたのが、やはりそれも云々という話なんでしょうけれども、この相談係というのは、帰国された方たちで日本語がわかる方というような話を聞きましたけれども、窓口をどこに置こうとしているのか。","respondent":"志村生活福祉課長","answer":"ですから今回、この事務を始めるに当たりまして、私どもの窓口でいいんだろうかという私どもの思いもあります。ですけれども午前中から説明したとおり、このほとんどの中身については生活保護制度の横引きです。","voiceIndex":283,"id":"exchange-131"},{"speaker":"西本委員","kind":"確認","question":"保育園保育料についてですが、先ほどご質問にありましたけれども、これは確認だけです。もう既に保育料の改正があったと思いますけれども、それに対して、保護者たちはどういう反応であるのか、何か問題等々が起きているのかどうかについて、お聞きしたいと思います。","respondent":"日下部企画財政課長、中島経理課長、小林保育課長","answer":"平成１９年度の段階におきましては、再開発関係も含めて、建築関係でありますとか、その辺が中心でありましたので、一括して計上しておりましたが、ただ。これは普通財産として扱っておりますので、その普通財産の賃貸料といたしまして、こちらにあります金額のうち１,３８２万４,０００円が。平成１９年度現在の保育料につきましては、若干定率減税の圧縮分の影響が出ておりますが、これについては大きな混乱なく、現在保育料の収納をしています。","voiceIndex":287,"id":"exchange-132"},{"speaker":"西本委員","kind":"質問・要望","question":"マイスクール八潮もここに設置されますので、明晴学園とマイスクール八潮、区との関係というところをどのような考えを持っていこうとしているのかということを確認します。ただ、階層が２３階層ですか、増えてきますので、高額所得者の方たちはちょっと不満が出てくるかもしれません。それについては十分にご説明をお願いしたいと、これは要望で終わりたいと思います。よろしくお願いします。","respondent":"日下部企画財政課長、河野指導課長","answer":"地域住宅交付金の、まず何点かご質問がございました。説明欄に補助率の表記がない理由ですけれども、実はこの補助金の制度というのはある意味では非常に柔軟な活用が可能な形になっております。具体的にどのような交流をしていくのかということについては、今後、双方の代表同士の話し合いで詰める予定になっております。","voiceIndex":291,"id":"exchange-133"},{"speaker":"西本委員","kind":"質問・要望","question":"そうすると、企業側の負担率と、それから品川区の一般財源からの持ち出しというのはどのぐらいと考えられますか。それから、明晴学園については、これは要望になりますが、ここの八潮北小学校は芝生の育成等々に地域の方たちが非常に尽力を尽くしております。ですから、区の関与ということも含めて、地域の方とうまくいくような手だても含めて考えていただきたいというふうに要望したいと思います。","respondent":"蓼沼高齢福祉課長","answer":"原小学校跡の費用の負担の関係です。ケアホームを例に申し上げますと、事業費が約５億８,７００万円、そのうちの区負担が３億８,２００万円余、法人負担が２億４００万円余というような内訳です。","voiceIndex":294,"id":"exchange-134"},{"speaker":"西本委員","kind":"質問・要望","question":"これは今後、利用者に対する徴収も出てくると思うんですけれども、その利用料というのも今後考えて行かれると思うんです。その中で一般財源という形、それから国とか都との補助金がある程度使えるのであればどんどん使っていただいて、なるべく入居者、それから利用者の負担を軽くしていくような方策をぜひとっていただきたいと要望して、これで終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":296,"id":"exchange-135"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１１０ページの高齢社会対策包括補助金の中に含まれている緊急通報システムの問題と、それから６８ページの高齢者住宅について、お伺いをしたいと思います。それと、民間型の緊急通報システムの利用料と、区の負担額がどのくらいになっているのか、それから消防庁直結型の区の１人当たりの負担額というのがどれぐらいになるのかをお聞かせいただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"あるいは、区のほうからの経費の点を考えますと、三位一体の関係で都の補助金が廃止されたというような経費の負担ということ等をあわせまして、あるいはその利用申請から機器設置まで、消防庁直結型のほうが時間を要するというような理由がありまして。","voiceIndex":298,"id":"exchange-136"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区の負担の４１６万円は、一般会計の総予算からすると、本当にそんなに大きな額ではないのではないかと思うんですけれども、結局、この民間型と消防庁直結型だと区の負担は消防庁型のほうが多くなるということなんでしょうか。だから、私はこのひとり暮らしの方を孤立化させないという点からも、ぜひ復活させていただきたいというふうに思うんですが、一番初めのコストの面とあわせてお聞かせください。","respondent":"蓼沼高齢福祉課長","answer":"このシステムについてはそういうことで廃止をいたしましたけれども、いろいろな議会の質問でもありましたように、ガスメーターあるいは水道メーターというような器具を使ったものも含めて、それからソフトな、地域でのいろいろな民生委員を含めた見守りの体制の構築も含めて。","voiceIndex":300,"id":"exchange-137"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私の地域の方で１カ月ぐらい前に、自宅で倒れて２日間意識がなかったというので、顔に傷ができていて、「それはどうしたの」と聞いたら、褥瘡だというんですよね。そういう点で言えば、ぜひお金の心配、お金のためにこの制度が使えないという、消防庁直結型をなくしたのであれば、なおさらその無料制度をつくっていただきたいというふうに思うんですけれども、いかがでしょうか。","respondent":"蓼沼高齢福祉課長","answer":"今、利用料についていろいろご意見がございましたけれども、この利用料金も含めまして、あるいはこういうシステムを含めて、地域でのひとり暮らし高齢者を見守る方法、適切な効果のあるものはどういうものなのか、どういうものがあるのか等。","voiceIndex":302,"id":"exchange-138"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういう点では、お金がないためにこの制度を受けられないということがない、いままではきちんとあったわけですから、それをなくしたのであれば、私はそれを復活させてほしいということと、復活ができないのであれば、せめて民間型を非課税の方は無料にということでご検討をお願いしたいと思います。緊急通報システムを。高齢者の世帯に占める割合というのもあわせて教えていただきたいと思います。","respondent":"蓼沼高齢福祉課長","answer":"高齢者の世帯の関係です。平成１７年度の国勢調査の数字を申し上げますと、高齢者のみの世帯が約２万５,０００世帯。それから単身世帯が９,７００世帯、約１万世帯弱です。","voiceIndex":304,"id":"exchange-139"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ、このことについてはもっと知らせていただいて、助かる命を守るというふうなところで、ぜひＰＲをお願いしたいと思います。３分なので、高齢者住宅についてお聞かせいただきたいと思います。高齢者住宅は１２月の初めに１週間の申し込みで登録者を決めていくという制度になっていると思いますけれども、去年の１２月の申込者の人数が何人いたのかを教えていただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"高齢者住宅の昨年の申込者ですけれども、申請が１６４人です。","voiceIndex":306,"id":"exchange-140"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１６４人でいつも入れるのが２０人弱ということで、本当にこの高齢者住宅をもっともっと増やしていただきたいというふうに思うんですけれども、品川区としての高齢者住宅の増設に対しての考え方を教えていただきたいと思います。","respondent":"冨岡高齢事業課長","answer":"本会議のご質問でもございましたけれども、今後の高齢者住宅につきましては、住居系、高齢者の住まいを長期基本計画で検討していく中で検討してまいりたいと考えています。","voiceIndex":308,"id":"exchange-141"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"立ち退きを要求されて高齢者住宅に入れた方というのは、本当にほっとして安心して暮らすことができるというので、本当にその喜びの声が出されています。１６０人中１６人、１７人、１８人しか入れないというところでは、この要求はもっともっと増設をしてかなえていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":310,"id":"exchange-142"},{"speaker":"山路委員","kind":"質問","question":"私のほうからは７４ページ、自転車駐車場使用料について、７８ページ、歴史館使用料について、１３１ページ、マイガーデン運営費負担金について、お伺いをいたします。長時間置きますと１５０円。そこで、料金設定を品川区で統一していただけないでしょうかという相談を、設置者がいろいろ違いますから簡単にはいかないと思いますが、この辺について、どのようにお考えでしょうか、お伺いをいたします。","respondent":"松嶋交通安全担当課長","answer":"区営につきましては、通勤、通学を含めまして、自転車を利用する方への提供として整備しているものですので、特定の駐車場利用者の受益者負担として使用料を徴収しています。そういった意味からも統一を図るということはなかなか難しい問題であるかなと考えております。","voiceIndex":312,"id":"exchange-143"},{"speaker":"山路委員","kind":"質問・要望","question":"しかし区民から見ますと、若いお母さん方は、例えば青物横丁に１日２回とか３回とか短い時間でとめることがあると言うんです。１回ですぐ１５０円かかりますから４５０円かかる。そういうことを区民から考えますと、統一するほうに、品川区のほうで積極的に関係機関に働きかけていただきたいと思いますが、その辺について、もう一度ご答弁をお願いいたします。","respondent":"松嶋交通安全担当課長","answer":"なかなか難しい話です。若干それますけれども、例えば現在駐輪場の運営費というのは２億円を超えるものがかかっております。","voiceIndex":314,"id":"exchange-144"},{"speaker":"山路委員","kind":"質問・要望","question":"歴史館使用料ですが、歴史館に関しましては、何回かいろいろな角度から質問をさせていただきました。昔、品川にいて引っ越した方にご連絡しましたら、懐かしい、品川は大きく変わりましたねと喜んで、それほどふるさとを思う気持ちが強かったんですけれども、この歴史館の入場の、ここ数年の流れはどのようになっているか、お伺いをいたします。","respondent":"富田生涯学習課長","answer":"平成１７年度、若干少なくなりまして、平成１８年度は４カ月工事休館したこともあり、数字的には下がっているところでありますが、今年度平成１９年度につきましては、２月末現在で平成１６年度と同様の内容でありますので。","voiceIndex":316,"id":"exchange-145"},{"speaker":"山路委員","kind":"質問","question":"本年のプレス発表によりますと、おもてなし館を整備ということで、ミニギャラリー部分が２階にできるということが発表になっているんですが、歴史館にある作品を移す検討はどのようになっているのか、お伺いをいたします。","respondent":"富田生涯学習課長","answer":"おもてなし館が来年オープン予定ということで準備をされているようです。その２階のギャラリーの展示内容ですとか、そういったことにつきましては、今後運営される方々とご相談を受けながら調整をしてまいりたいと考えているところであります。","voiceIndex":318,"id":"exchange-146"},{"speaker":"山路委員","kind":"質問・要望","question":"大変作品を展示するにも難しいと思いますが、品川を代表するような、東海道の思い出を感じるような作品をぜひ地元のまちの活性化のために展示していただきたいことを要望しておきます。続きまして、マイガーデン運営費負担金約１６３万円計上してありますけれども、南大井に新しく昨年の予算で区民農園が完成しましたけれども、これは全部区画は売れたんでしょうか、お伺いします。","respondent":"藤田道路公園課長","answer":"マイガーデン南大井ですが、おかげさまをもちまして全部埋まってあります。２月１日から新しいというか、初めてオープンですけれども、皆様方に利用の開始をしていただいたところです。おおむね３.１倍の倍率で、当選された方が今利用をしているです。","voiceIndex":320,"id":"exchange-147"},{"speaker":"山路委員","kind":"質問","question":"当然人気のあるところだと思っていまして、ここ数年、身体障害者の車いす利用者のための農園をお願いしていたんですが、その辺も整備していただいたんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":322,"id":"exchange-148"},{"speaker":"須貝委員","kind":"質問","question":"公立学校施設整備費負担金の中で、荏原西地区小中一貫校建設に対して、国庫負担額として約８,６００万円と記載されております。１０１ページ、安全安心な学校づくり交付金として、荏原西地区小中一貫校建設に対して国庫補助額として約９,８００万円と記載されていますが、これらはどのような工事に対して国より負担それから補助をされているものか、教えてください。","respondent":"市川庶務課長","answer":"ちなみに今私どもの見込みといたしましては、負担金、補助金合わせまして、２カ年度で約６億７,０００万円の助成を受けられる、こういう見込みを立ててあります。","voiceIndex":324,"id":"exchange-149"},{"speaker":"須貝委員","kind":"質問","question":"私の言い方が悪かったのかもしれないんですが、学校教育法を見たらそこには小中一貫校ということは全然記載されていなくて、まして施設一体型というのは、私は学校教育法を見ましたら、小学校、中学校、高等学校、大学等々は載っておりましたが、そこには全く記載されておりませんが、それについて、こういうわけですという理由を教えてください。","respondent":"河野指導課長","answer":"荏原西地区に開校する小中一貫校は、施設は一つですが、荏原平塚中学校と平塚小学校です。","voiceIndex":328,"id":"exchange-150"},{"speaker":"須貝委員","kind":"意見","question":"ということは、法的にはまだ載っていないということですよね。今説明だけで。小学校とはなんぞや、中学校とはなんぞや、高等学校とはなんぞや。ところが小中一貫校に関しては全く記述がありませんが、それについて、簡単でいいんですが、もし何かお答えしていただければありがたいと思います。","respondent":"河野指導課長","answer":"あくまでも法の規定上は、小学校と中学校の併設という形です。","voiceIndex":330,"id":"exchange-151"},{"speaker":"須貝委員","kind":"質問","question":"今、併設だというお話を聞きました。要はそこに正式に認められた小中一貫校という話は、まだ文部科学省でも正式に認可されていないのではないでしょうか。ところが、現実論は正式に認可されていないのに、一体型小中一貫校というのを、正式に文部科学省で認可されていない、法的な根拠がないのに、今進めているというふうに考えていてよろしいでしょうか。あくまでも小学校、中学校ということですよね。","respondent":"河野指導課長","answer":"小学校と中学校の併設です。","voiceIndex":332,"id":"exchange-152"},{"speaker":"須貝委員","kind":"質問","question":"ただ、この四つの自治体を見ますと、奈良市は小中一貫校と呼んでおりますが、約１１０名、小学生、中学生がおります。ですが、これは併設ではなくて隣接で学校をつくっております。小学校と中学校です。予算に載っているわけですから。全国には僻地を除いて、品川区のような施設一体型小中一貫校は、私の調べではどこにもないようですが、これは間違いないでしょうか。それについて見解をお聞かせください。","respondent":"河野指導課長","answer":"法的に全く逸脱はしておりません。あくまでも施設一体型の小学校、中学校の併設校です。","voiceIndex":334,"id":"exchange-153"},{"speaker":"須貝委員","kind":"質問","question":"わかりました。ただ、やれない。確かに１校５５億円もかかります。ただ、その前になぜそれを特区申請として出さないのかというふうに考えますと、やはり法的に問題があるからひっかかっているというような、私はその自治体の方からそういうふうにお聞きをしました。ところが今回のは違うんじゃないですか。では、構わないとおっしゃるのは、どこにその法律が書いてあるんですか。お願いいたします。","respondent":"河野指導課長","answer":"委員は教育職員免許法のことをお話しされているのだと思いますが、教育職員免許法の第１６条の５、第１項というところに、「中学校又は高等学校の教諭の免許状を有する者は、第３条第１項から第３項までの規定にかかわらず。","voiceIndex":336,"id":"exchange-154"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、小学校の免許だけで中学生も教えられる、中学校の免許を持っていれば小学生も教えられる、そんな法律ってあるんですか。少なくとも、ちゃんと東京都から両方の免許を持っていて兼務発令がされれば、それはできますよね。そういうふうなことを、一緒に兼ねてやっていいとはどこにも書いていないと思うんですが、ご見解をお聞かせください。","respondent":"河野指導課長","answer":"兼務発令をされている中学校免許のみの教員が小学校の兼務発令を受け、校長が公務分掌権に基づき学級担任の分掌をさせることは妨げられないということで、文部科学省からの回答もいただいているところです。","voiceIndex":338,"id":"exchange-155"},{"speaker":"須貝委員","kind":"確認","question":"いつまでもあれしてもしょうがないですけれども、では、今のは間違いないですね。それと、もう一度確認をとります。中学校の免許を持っている人は、数学とか社会でとっております。その教科は小学生を教えて構わないですよね。それはもう法律にちゃんと載っております。何でも校長が認めればいい、そんなことが教育職員免許法にあったら、それはみんな簡単じゃないですか。違いませんか。","respondent":"河野指導課長","answer":"ただし、ここで言っている小学校の教科での指導というのは、学習指導要領に定めております各教科、いわゆる国語、算数、社会、理科、生活、音楽、図工、家庭科、この教科を指しております。それ以外の指導ができないということは全くございません。","voiceIndex":340,"id":"exchange-156"},{"speaker":"須貝委員","kind":"質問","question":"最後に、もしそういうことならば、せっかく歳出のほうはきちんと出ているんですから、歳入のほうもそういうふうにしていただけたら、よりわかりやすいんじゃないかと思います。これで質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":344,"id":"exchange-157"},{"speaker":"須藤委員","kind":"質問・要望","question":"シルバーセンターのほうは１６館あるけれども、東品川がここに載っていないで１５館ということなんですが、そのあたりのところを教えていただきたいのと、それから、先ほど集会所使用料にばらつきがあるというような話があったんだけれども、ここも１回から二百何回までシルバーセンターは非常にばらつきがありますよというので、そのあたりの考え方というか。","respondent":"冨岡高齢事業課長、富田生涯学習課長","answer":"それからもう一つ、並べ方の順番ですけれども、これにつきましては、以前からこういう並べ方をしておりまして、予算の編成上の問題もありますので、今後につきましては企画財政課と話をしながら検討させていただきたいと考えています。ほかの諸室につきましては、利用の回数です。","voiceIndex":346,"id":"exchange-158"},{"speaker":"須藤委員","kind":"質問","question":"それぞれ利用回数がここに出ているんですけれども、今、シルバーセンターのほうは目的外の利用というお話をされたんだけれども、ちょっとある人がシルバーセンターを借りに行ったら、貸しませんと。あいているんだけれども貸しませんというふうに言われたということがあるんだけれども、そういうことは普段はないのか、目的外とか、こういう。これは目的外だけ書いてあるわけですか。","respondent":"冨岡高齢事業課長","answer":"シルバーセンターの、これは目的外といいますか時間外というふうにとらえていただくとよろしいんですけれども、シルバーセンターにつきましては６０歳以上の方、区内にお住まいの方が個人で利用されるか、その方たちがグループをおつくりいただきまして。","voiceIndex":349,"id":"exchange-159"},{"speaker":"須藤委員","kind":"質問","question":"平成１７年度は利用者というのが、文化センターだと今言ったように６０万余の人が使っていますよ、シルバーセンターも３０万余の人が利用していますよというような、非常な数の利用者がそこにいらっしゃるわけなので、そのあたりは文化センター、それからシルバーセンター、総合して高齢化社会に向けてどうお考えになっているか、ちょっと教えてください。","respondent":"富田生涯学習課長","answer":"その辺、利用の内容としましては、高齢者の方々のご利用というのも、かなりの割合を占めるという状況にはありますので、そういった面では高齢者団体の方々へのシルバーセンターを含めたそういった施設展開というのも考えていく必要はあろうかと考えています。","voiceIndex":351,"id":"exchange-160"},{"speaker":"須藤委員","kind":"質問","question":"つくられた時代がそれぞれ変遷してきていますので、それぞれの時代に合ってやはり考えていかれたらどうでしょうかという質問をしていたので、そのあたり、もう答弁は結構ですけれども、名称からして、そのあたりも考えていっていただけたらと、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":353,"id":"exchange-161"},{"speaker":"土井委員","kind":"質問・要望","question":"私からは７７ページの区民住宅の借上型に関連をして、これに関連をして幾つかのページがありますけれども質問をすること、それから、１２１ページの職員待機寮に関連をしてお伺いをすること、住宅関係です。そうなると、それをどうするのということがポイントになるので、どうするのか、いろいろ検討はなさっているのではなかろうかと思うので、その辺をお伺いしたいというのが１点であります。","respondent":"齋藤住宅課長","answer":"２９８戸の９２％が、しかとお住まいのところでございまして、残り８％が空き室です。２９８戸は住んでいらっしゃるところもあれば、空室のところもある。そのトータルです。今、委員のほうから、入りと出のお話がありました。１億１,０００万円ほど持ち出しがあります。","voiceIndex":355,"id":"exchange-162"},{"speaker":"土井委員","kind":"質問・要望","question":"今の部分をお話ししますと、最終的にこの問題は、例えばの話ですよ。それはよく計算をしてみないといけない部分だろうと思うんですけれども、そこらも含めてご見解をお伺いします。非常にご丁寧にご説明があったんですけれども、すき間がいっぱいありますので、もともと歳入のところに全部書いておいていただけませんかというお願いをさせていただきたいと思うんですが、いかがでしょうか。","respondent":"齋藤住宅課長、榎本人事課長、片田建築課長、日下部企画財政課長","answer":"区と契約しているわけではございません。地元区は一括して借上をする、こういう義務が生じるものでございまして、２０年間はやめられません。職員住宅の部分ですけれども、職員待機寮は平成１９年４月１日現在で入居率１００％、ただし、区民の災害対策のために２戸別枠でとってありますので。手間暇がどのぐらいかかるのかというご質問ですけれども、実はこの手間暇のかかる想定日数として、建築基準法としては、法律の中で３５日間。","voiceIndex":357,"id":"exchange-163"},{"speaker":"土井委員","kind":"質問・要望","question":"その借上型で、違反になるというか、だから裁判をしてでもやるぐらいのことも含めて、みんな発想をしなきゃいけないんじゃないですか。そうなれば両方で何とかするしかないということになるじゃないですか。ずっとこうやっていて本当にいいのかという話を、放置しているとは言わないけれども、ほとんど放置状態になっているわけですから、これは何とかしなきゃいかんなと思って質問をいたしております。","respondent":"齋藤住宅課長、榎本人事課長、片田建築課長","answer":"都民住宅の借上型は７割ぐらいの入りしかありません。そんなようなことでございまして、どの自治体もこの制度については見直しを国に対して要求しています。その寮の空いているところですけれども、火事が起こったときに、夜中、一時的に避難する場所として２部屋を確保しているというもので。構造計算の問題ですけれども、国のほうとしても円滑化の方針等を出しまして、いろいろな相談窓口を設置するなどして今努力しています。","voiceIndex":362,"id":"exchange-164"},{"speaker":"堺委員","kind":"確認","question":"私のほうからは簡単に、７４ページ、７５ページに出ております区営住宅使用料、また７６ページ、７７ページにかけて掲載されております区民住宅使用料、これに関連して何点かお伺いをします。最初に、区営住宅の申し込みについてなんですが、いわゆる入居資格というんですか、応募資格といいましょうか、これについて確認の意味でちょっと教えていただければと思います。","respondent":"齋藤住宅課長","answer":"区営住宅につきましては一つ、１年以上区内に住んでいるということと、住宅に困窮していること、あとは所得の基準がございまして、その所得の基準以内である、こういうことが規定されてあります。","voiceIndex":367,"id":"exchange-165"},{"speaker":"堺委員","kind":"意見","question":"平成１８年８月に一度、いわゆる使用を承継できる同居者の範囲、これについての見直しがあったんですね。それからまたその後、いろいろな動きの流れの中で、昨年の１２月には今度公営住宅法の施行令、これが改正をされたということから、平成２１年４月からこの法律の施行が始まるということから、東京都におきましても、それに対応すべき諸準備が始められているやに聞いております。","respondent":"齋藤住宅課長","answer":"旧来は３親等、おじ、おば、甥、姪の範囲まで引き続き住めたんですけれども、一定の家族が独占的に使用することは好ましくないということでございまして、平成１５年からは１親等、父子で、昨年の８月からは配偶者まで、ここに制限されておりました。","voiceIndex":369,"id":"exchange-166"},{"speaker":"堺委員","kind":"確認","question":"ちょっとその辺で確認をしておきたいんですけれども、区営住宅についても都営住宅と同じようなことは既にやっていますよということだったのか、東京都が変更すれば区もそういうふうに準じて変更しますよということなのか、ちょっとその辺、教えていただけますか。","respondent":"齋藤住宅課長","answer":"今回東京都が都営住宅の使用承継の例外について見直しをしました。この見直しをした中身というのは、品川区の要綱と同じです。したがいまして、区の基準に都が合ったです。","voiceIndex":371,"id":"exchange-167"},{"speaker":"堺委員","kind":"確認","question":"そうすると、既に区の基準に東京都がということですか。ところが東京都のほうについては、今度は承継については１度から４度と、こういうふうに変わっていますけれども、その辺については、これはあくまでも入居はそうだけれども、使用承継については、東京都のほうの変更になった部分について適用していくんですよという理解をしていいんでしょうか、ちょっとその辺、確認させてください。","respondent":"齋藤住宅課長","answer":"ただ、今委員がご指摘になった障害の程度があれば、区営住宅にも申し込みができる、こういう基準です。先ほどご説明申し上げた使用承継の制度は、どの範囲でもって承継できるか、引き続き住めるか、こういう基準でございまして、その基準は品川区も東京都も同じになったです。","voiceIndex":373,"id":"exchange-168"},{"speaker":"堺委員","kind":"質問","question":"わかりました。東京都の基準と品川区の基準も、使用承継については同じであるですので安心をいたしました。それから次に、代表質問の際に公的住宅について、ＡＥＤの設置についてお尋ねをいたしました。ちょっとその辺をもう一回教えていただけますか。","respondent":"齋藤住宅課長","answer":"自治会の皆さんに講習会を開いて、一般質問の答弁の中でもお答えしましたが、相互に支え合う、地域が支え合う好機というふうに考えておりますので、まずはモデルとして。","voiceIndex":375,"id":"exchange-169"},{"speaker":"堺委員","kind":"質問","question":"もう一つ、区営住宅がありますから、都民住宅とかについては東京都に働きかけていくしかないんですけれども、そういう流れの中で、モデルということですから、ここがいい形でいけば、希望としては残りの区民住宅、あるいは都営住宅等にも随時拡大をしていっていただければありがたいなと思うんですが、その辺についてのご見解はいかがでしょうか。","respondent":"齋藤住宅課長","answer":"その有用性が確認できれば、今、委員がご提案があったように、区営住宅や他の建設型の区民住宅に設置してまいりますし、あわせて有用性につきましては、他の出先も含めて庁内の方にもご紹介をしてまいりたいというふうに考えております。","voiceIndex":377,"id":"exchange-170"},{"speaker":"堺委員","kind":"提案","question":"ぜひ、そういう方向で、この件についても、そこに住んでいる方々の安心といいましょうか、何かあってもすぐその機械がそこにあるということで担保されれば安心感もあるかなと、また代表質問の際にも申し上げましたが、それはあるということに基づいて、この住民の人たちが講習会を行っていただければ、そこでまた共通の、いわゆる共助といいますか。","respondent":"齋藤住宅課長","answer":"耐震診断は平成１８年度で２棟、今年度４棟、来年度で６棟、行う予定です。したがいまして、来年度いろいろ耐震診断の方法や優先順位を取りまとめて、平成２１年以降、順次対応してまいりたいというふうに考えております。","voiceIndex":379,"id":"exchange-171"},{"speaker":"林委員","kind":"質問","question":"相手方がいらっしゃるとか、そういった意味から、こうしてせっかく品川区が立てた計画を、ぜひ平成２０年度の予算書は、最後に繰越明許とか減額補正とか取り消しとかいうことのない来年の３月の予算特別委員会を迎えたいと思うんですけれども、区長が一人でやる仕事ではないと思うんだけれども、トップとしてさまざまな各事業部、総務、企画も含めてそういうところで仕事をする職員の方々へ。","respondent":"濱野区長","answer":"今、平成２０年度の予算を審議をしていただいているわけであります。予算というのは金額で表示した区の行政の計画というふうに思っておりますので、この計画をすべて実行するというのは必要なことだというふうに思っております。","voiceIndex":382,"id":"exchange-172"},{"speaker":"林委員","kind":"質問・要望","question":"ぜひ強い意識で臨んでいただきたいというふうにお願いをしておきます。来年の３月の予算特別委員会を楽しみにしています。この２１万７,０００人という根拠は、おそらく年末調整をしたり、確定申告をしたり、いわゆる国税を申告、納税して、それが区のほうに連絡が入って人数が計算されるというふうに思うんですけれども、この人数の割り出しの根拠を教えてください。どういうことなのか教えてください。","respondent":"武内税務課長、鷹倉区民課長","answer":"特別徴収の法人のお付き合いということですけれども、もちろん年末調整説明会ということで、１０月、１１月にかけて税務署等、一緒に説明会を区も行ったり、あるいは法人会という組織とあるいは青色申告ですとか。経済センサスの意味ですが、事業所の事業活動および企業の状態を調査し、もって我が国における事業所および企業の産業、事業規模等の基本的構造を全国的地域的に明らかにし。","voiceIndex":384,"id":"exchange-173"},{"speaker":"林委員","kind":"質問・要望","question":"例えば保育料のところは何人とか、先ほど来出ている地域センターの利用の人数等、人数を明記するということについて、どうお考えですかと聞いたの、もう答える時間がないからいいです。紙にして、どういうことをやろうとしているお金なのか、やれという委託金なのか、ぜひ資料をお出しいただきたい。まだ聞きたいことはたくさんあるんだけれども、時間がないのでそれだけ聞かせてください。","respondent":"日下部企画財政課長","answer":"人数につきましては、確かにできるだけ明記するような形でわかりやすくということで、今後心がけてまいりたいと、このように考えております。","voiceIndex":387,"id":"exchange-174"},{"speaker":"南委員","kind":"質問","question":"１０２ページの新教育システム開発プログラムについて伺いたいと思います。それから、先ほどは平成１８年度と平成１９年度と、それぞれ別々に委託を受けている、こういうことだったと思いますが、それぞれの内容がどういうものなのかをちょっと伺いたいと思います。","respondent":"藤森小中一貫教育担当課長","answer":"それと平成１９年度からスタートしたものにつきましては、学校運営と学校、教育条件整備の研究委託ですが、こちらは教員と地域等の意識アンケートの集計委託、それと報告書の印刷代、検討委員会の委員謝礼、そして荏原平塚中学校および八潮学園に配置する加配教員の人件費等です。","voiceIndex":390,"id":"exchange-175"},{"speaker":"南委員","kind":"質問・要望","question":"平成１９年度のほうについては、たしか平成１９年度、平成２０年度、平成２１年度と学校、新しいタイプの自立的な学校運営ということで、望ましい学校規模のあり方、再配置のあり方云々という、こういう内容だったというふうに思いますけれども、改めてそのことを確認したいと思いますが、どうなんでしょうか。","respondent":"古里学務課長","answer":"平成１９年度から開始をしたものにつきましては、委員おっしゃったとおり新しいタイプの学校のあり方ということで、私どもの研究タイトルとしては「学校規模の望ましいあり方と配置のあり方の検討および統廃合の実施に伴う諸課題の検討」ということで申請をしています。","voiceIndex":392,"id":"exchange-176"},{"speaker":"南委員","kind":"質問・要望","question":"学事制度審議会の経費、運営委員報酬というのは、そういうことでいいですよね。この学事制度審議会について伺いたいと思うんですけれども、今年の１０月までのスケジュールが立てられているようでありまして、今、当初の設置の時期が随分、数カ月ずれ込んでいるので、この予定スケジュールでは、今どこまでどういうふうに到達したのか、ちょっとその辺について明らかにしていただきたいと思います。","respondent":"古里学務課長","answer":"学事制度審議会における審議スケジュールにつきましては、さきの文教委員会でお示しした審議スケジュール、これに基づいて今鋭意検討をしておるところでございまして、検討状況の内容につきましては、別途中間のまとめ等をお出しするときにご報告をしたいと考えています。","voiceIndex":394,"id":"exchange-177"},{"speaker":"南委員","kind":"質問","question":"どこまで来ているのかということをちょっと聞きたかったんですけれども、このスケジュールでいうと、今、３月ですけれども、２月の時点では、スケジュール上では審議会中間のまとめについて報告というふうになっていて、パブリックコメントの実施についてというふうにあるんですけれども、まだパブリックコメントについては明らかにされていないので、今このスケジュールの点でいえば。","respondent":"古里学務課長","answer":"現在、中間のまとめについて精力的な審議をいただいているですので、先ほど申し上げたとおり、しかるべき時期に中間のまとめについて、ご報告をするということ、これを申し上げたいと思います。","voiceIndex":396,"id":"exchange-178"},{"speaker":"南委員","kind":"確認","question":"今そうしたら１カ月おくれなのか、２カ月おくれなのか、どの程度おくれた状況にあるのかということと、それから、ではそういうことでいくのであれば、１０月までの予定は当然延長しなければいけないというふうに見通しを持っておられるのか、そこを伺いたいと思います。改めてこの問題について伺いたいんですけれども、軽視をしている、こういうふうに私は思いますけれども、それはどうなんでしょうか。","respondent":"古里学務課長","answer":"この諮問に対して今審議会が真剣に検討をなさって、その諮問の答申を出されるわけですから、その答申を受けて、区民の皆さんを含め、区民の委員の方も入った貴重なご論議ですので、その内容を実現する方策を検討するのは私どもの責務ですから。","voiceIndex":398,"id":"exchange-179"},{"speaker":"南委員","kind":"質問・要望","question":"１０月に向けて努力をしていると。したがって、私はこういうふうなことを、答申が出てから改めてその答申に基づいて教育委員会としてはどうしようかというふうなことを諮るべきであって、最初から一定の方向の答申を期待して、それを見越した上で策定するなどという、こういうことはやはり正しくないと思いますので、この点について、明らかに見解をちょっと伺いたいというふうに思います。","respondent":"長田教育次長","answer":"ただ、ここのところの審議会の検討経過の中で、中間答申をどういう形で出すのかというようなことについてはいろいろ議論があります。当初３月に中間答申をということで予定をしていたのも、予定どおりの事実です。","voiceIndex":400,"id":"exchange-180"},{"speaker":"南委員","kind":"質問・要望","question":"やはり誤解を招くようなことは慎んでおくべきだということを改めて申し上げておきたいと思います。それは先ほど申し上げた理由です。やはりきちんとしたパブリックコメントを出して、そして長期基本計画のああいう中身ではなくて、もっとやりとりがきちんとできるような、そういうことを強く求めておきたいと思いますけれども、その件は最終的にはどうでしょうか。","respondent":"長田教育次長","answer":"パブリックコメントについても、予定どおり行う予定です。","voiceIndex":402,"id":"exchange-181"},{"speaker":"三上委員","kind":"質問","question":"５０ページの特別区民税について、それから、１０２ページの学校図書館支援事業委託金４９０万円について、少々お伺いしたいと思います。平成２０年度の中で、もしかするとこういうことが起きてくるのかなということで検討されているふるさと納税と言われているものでありますけれども、これについて品川区としてどういう考え方をされているのか、そこをちょっとお伺いしたいと思います。","respondent":"武内税務課長、工藤品川図書館長","answer":"現状においても、住民税の中に寄附金の控除、そういう寄附をした方については寄附金控除というのがあるんですけれども、それの拡大をしていくという方向で現在検討が行われております。私のほうから学校図書館の支援事業の委託金の件につきましてお答えいたします。こちらのほうの事業は、文部科学省が行っています学校図書館支援センター推進事業というものです。","voiceIndex":405,"id":"exchange-182"},{"speaker":"三上委員","kind":"質問","question":"いままでそうであるのが、これが導入された場合に３１倍の８,１００億円プラスになるということで、８,３６９億円までなるという試算をしているんですよね。ですから、そこらあたりは、やはり今から東京都、品川区だって先進的なことをやっていれば、寄附をしますよという、所得税で取られるよりは控除があるほうがいいと。納めるよりは。そこらあたりはどういうふうにお考えになっていらっしゃいますか。","respondent":"武内税務課長","answer":"言われるとおり、現在国で審議されておりますので、若干は私どもに情報が入ってきているんですけれども、実際、平成２０年度において地方税法の条例改正等の行為を行っていくという状況になりますので。","voiceIndex":408,"id":"exchange-183"},{"speaker":"三上委員","kind":"質問・要望","question":"そういった点から、私はしっかりとそういった点で、今ここにいらっしゃる皆さんの意識というものを、いままでの何かぬるま湯に浸かっているような雰囲気という部分ではないかもわかりませんけれども、そういう状況は変わっていくよと、こういうようなことで、お考えをもう少し進めていっていただきたいなと、こういうふうに思いますが、いかがでしょうか。","respondent":"日下部企画財政課長","answer":"そういう状況にもあります。したがいまして、この寄附税制の動向等もしっかりと見極めながら、さらにしっかりと気持ちを引き締めて財政運営に当たっていく必要があろうと、このように考えてあります。","voiceIndex":410,"id":"exchange-184"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私からは１３２ページ、水族館運営費収入、これはどういうことを聞きたいかというと、前向きに続けていってもらいたいと考えていますので、児童生徒、例えば高齢者を含めて夢が持てる、またもう一回行きたいなと思う施設でいつまでもあってほしいという思いで質問をします。いままでの１０年間はもうある程度調べました。９億３,０００万円ぐらい８年間では負担している。","respondent":"藤田道路公園課長、中島経理課長、宍戸施設担当課長","answer":"私のほうからは水族館にかかわる部分でお答えしたいと思います。それと、駐車場の関係ですけれども、台数が減っているのは、若干ここのところ減っている部分と。ただし、建築基準法に基づく点検なども現在行っていることから、例えば外壁等の小破修繕といったようなものについては。","voiceIndex":413,"id":"exchange-185"},{"speaker":"石田（秀）委員","kind":"質問","question":"水族館からいきます。そうすると必ずぼんと上がって、またどっと５年ぐらいで減ってきて、またぼんとこういうことがあるわけね。ああいうのなんか特にリストアップしておいて、合わせてやるということがあれば、私はやってやれないことはないと思うんだけれども、そういうことも含めて、そういうリストアップをして、それが見合うかどうかは別としても、そういう考えがあるかということを改めて伺いたい。","respondent":"藤田道路公園課長、中島経理課長、宍戸施設担当課長","answer":"そういった活動を通して、皆さんに喜んでもらえる水族館運営に努めていきたいというふうに考えてあります。そういった部分では、駐車場の防災センター側の入り口に人を配置して、安全対策等も十分とりながら対応していきたいというふうに考えてあります。委員今ご指摘のように、耐震工事と合わせて改善ができないかということでリストアップなどいたしまして、方策について探っていきたいと考えています。","voiceIndex":417,"id":"exchange-186"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"そうすると、そういうのをだれがやっていくかということもぜひ検討していただいて、やはり金額がばんばん増えていくよりは、継続的に１０年後でもいい施設であってほしいと思うわけですから、その分の来客者数、バックヤードはお金がかかってくるのはもうしようがないわけですから、そういうのを踏まえて、そういうところの固定客の誘致みたいなものもぜひお互いで、そうしたら。","respondent":"藤田道路公園課長","answer":"今後、さらに区の中で議論を深めて、１０年後につなげていければいいというふうに考えております。一生懸命頑張っていきます。","voiceIndex":421,"id":"exchange-187"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=894#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":123331,"voices":423}},{"id":"h20-20080306-3","meetingId":"h20-c-budget","date":"2008年3月6日","dateIso":"2008-03-06","committee":"予算特別委員会","time":"午前１０時０３分～午後６時２０分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を189件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成２０年度品川区一般会計予算","agenda":"平成２０年度品川区一般会計予算","exchanges":[{"speaker":"渡辺委員","kind":"質問","question":"私のほうは、１５１ページ、結婚サポート、１６９ページ、区民保養所、１４９ページ、水と緑の市町村交流についてお伺いします。初めに、結婚サポート事業、平成２０年度から少子化対策の抜本策で取り組まれる、この事業の背景と現況として区内のまず未婚率を伺いたいと思います。幅が広くなってしまうので、２５歳から２９歳と３０歳から３４歳の２点を男女別でお願いします。","respondent":"鷹倉区民課長","answer":"私どもも当然少子化対策としていろいろな全国に先駆けた対策をとっているわけですが、その前の段階の結婚の段階で何らかのサポートができないか、特に結婚というのはある種の価値観が働きますから、なかなか行政がかわりにくいわけですが、ただ。","voiceIndex":4,"id":"exchange-001"},{"speaker":"渡辺委員","kind":"質問","question":"数字のとらえ方は人それぞれあるかと思います。というのも、自民党の幾つかの県連で出会いパーティーを主催されていて、いずれも盛況で今年で第１０回目を迎えたり、かなり結果も出されているということを伺いました。そういう中で、先ほどの繰り返しになりますが、検討の中で、そういったパーティー形式といいますか、そういったこともあったのか伺いたいと思います。","respondent":"鷹倉区民課長","answer":"ただ、この結婚という問題は、あくまでも個人の発想の部分がありますので、できれば区民の方々が自主的にこういうことをやりたいなと、今おっしゃいました出会いパーティーなんかが出てきたときに、どういう形で区として支援していけるのか、それは今後の検討課題になるのかなと。","voiceIndex":6,"id":"exchange-002"},{"speaker":"渡辺委員","kind":"質問・要望","question":"区民保養施設借上型について伺いたいと思います。この借上型始まって１年、区民要望の反映、それと平成２０年度の予算作成に当たって、施策を伺いたいと思います。それと借上型ということで、利用者は現地で宿泊と食事代を支払うというふうな案内になっていました。よって、仮に利用者がゼロでもこの委託料契約、この額は支払う、そういった保証金のようなものであるのかどうかを伺いたいと思います。","respondent":"鷹倉区民課長","answer":"平均いたしますと４５％、ただ、暖景苑の代替施設ということで立ち上げた関係で、暖景苑の数字を申しますと、暖景苑は３１％ということで、料金的にも委員ご指摘のとおり４,０００万円ということで、効率的な運営がなされているのかなということを考えてあります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういった中で、今年の第１回区議会定例会で濱野区長が施政方針で述べられたように、区民と区との協働という点で私も心から共鳴する中、これから未来志向で考えると、今近畿日本ツーリストということでしたが、大手業者からこういったことも区内の公益団体で取り組む時代になると考えますが、この点を伺いたいと思います。","respondent":"鷹倉区民課長","answer":"今回いろいろの方に使っていただく中で、利用が悪ければ、また新しいホテル、新しい旅館に取り替えていく、こういうような形を考えている仕組みですが、そうしますと、やはりいろいろな旅館に対して、あるいはホテルに対する情報を持っているとか。","voiceIndex":12,"id":"exchange-004"},{"speaker":"渡辺委員","kind":"確認","question":"再度確認ですが、まだ実際にそういったことを別に観光協会と当たっているわけでも私もないですし、業者もないかと思いますが、今後という点での可能性を再度伺いたいと思います。","respondent":"鷹倉区民課長","answer":"去年始めたばかりで、プロポーザル方式をとっていますので、数年間は同じ形で中身を改善しながらやっていきたいと考えています。議員提案の件につきましては、今後の検討課題ということととらえさせていただきたいと思います。","voiceIndex":14,"id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"では次に、水と緑の市町村との交流事業を最後に伺いたいと思います。そして、こういったところへ区民が行こうと思える、また内容がよかった、あるいはもう一度行こう、友達に薦めようという点が大きなポイントになるかと思いますが、今回計上されているマウントしながわ活用事業を生かすにも、企画の組み合わせが非常に重要と思われますが、この点をお伺いしたいと思います。","respondent":"鷹倉区民課長","answer":"新しい新機軸という形でマウントしながわ事業の活用を考えたいということで、去年、調査年、今年度の予算につきましては、調査をより具体的に進めるための調査のための道づくりを考えてあります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"渡辺委員","kind":"提案","question":"議員提案で可決されました文化芸術・スポーツのまちづくり条例の期待もありまして、先ほどの保養所という一つの枠組みもある、そしてこの市町村交流もある、そして生涯学習、スポーツなどもあるということで、それぞれを超えた横断的な取り組みが今後必要になると思われますので、その点のご見解を最後に伺いたいと思います。","respondent":"鷹倉区民課長","answer":"確かに交流事業そのものも横断的ですし、今回新たな条例が提案された。その中にスポーツが入っているですので、ますます今後横断的な形で取り組みを進めていかなければならない、このように考えているところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"金野委員","kind":"質問","question":"私のほうからは、２点にわたってなんですが、１点目が１４３ページの私立幼稚園関係費、２点目が１４７ページの庁舎等維持管理費、この２点を質問します。私立幼稚園の関係費の中から、私立幼稚園の預かり保育事業のきんだぁくらぶについてお伺いしたいと思います。このきんだぁくらぶの概要と、また実施園をお聞かせ願います。","respondent":"高橋幼保一元担当課長","answer":"お尋ねのきんだぁくらぶの実施園のほうからご紹介したいと思います。きんだぁくらぶの実施園は８園ございまして、アライアンス幼稚園、荏原学園旭幼稚園、大井うさぎ幼稚園、亀田幼稚園、そして洗足うさぎ幼稚園、戸越幼稚園、日本音楽学校附属幼稚園、鈴ヶ森めばえ幼稚園です。","voiceIndex":21,"id":"exchange-008"},{"speaker":"金野委員","kind":"質問","question":"このきんだぁくらぶ、幼稚園に通うお母さんも、若干働いているお母さんもいらっしゃって、この８園に関して、特に私の担当する地域では大井うさぎ幼稚園などがあるんですが、そこに通うお母さんたちにとっては非常に、その中で、働くお母さんたちから非常に助かっているという声をたくさん伺います。","respondent":"高橋幼保一元担当課長","answer":"平成１７年度から本格実施ということで、今に至っているところです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"金野委員","kind":"質問","question":"平成１２年から始めていただいて、平成１７年からが本格的ということで、非常に利用されているお母さんたちから声が上がっているのが、やはり平成１７年ぐらいからだったんでしょうか。この８園の幼稚園がみずから手を挙げてするものなんでしょうか、それともこちら側から働きかけて、このきんだぁくらぶをするものなんでしょうか。","respondent":"高橋幼保一元担当課長","answer":"これはみずからの園で実施したいというところについて、品川区が補助金等も出して支援しています。","voiceIndex":25,"id":"exchange-010"},{"speaker":"金野委員","kind":"質問","question":"そうすると、このきんだぁくらぶのこの補助金自体というのは、各私立幼稚園、品川区では２０園ありますけれども、そちらにこういう補助金がおりますよというお知らせ等が行って、やりますかという形で周知を図って進めているものなんでしょうか。","respondent":"高橋幼保一元担当課長","answer":"このきんだぁくらぶを始めるときにおきましては、このお話を、実施に当たりましては、私立幼稚園協会のほうにご案内をしていますけれども、品川区に２０園ございまして、ほとんどの園が預かり保育をそれなりに実施しています。","voiceIndex":27,"id":"exchange-011"},{"speaker":"金野委員","kind":"質問","question":"非常に先ほどから何回も私も言葉に出てしまうほど、保護者のニーズというのが高まってきているのかなというのを非常に感じます。ですので、拡充という部分では、今後どのように区として進めていかれるのか、その点の展望というんでしょうか、お聞かせください。","respondent":"高橋幼保一元担当課長","answer":"今お尋ねの区として預かり保育をどのようにするかですけれども、それぞれの園の状況もございまして、例えば夏休み中も実施するとなりますと、人の問題、園によって園長先生のお話なんかを聞くと、せめて夏休みは職員をお休みさせてあげたいんですという園もございましたり。","voiceIndex":29,"id":"exchange-012"},{"speaker":"金野委員","kind":"意見","question":"ただただ保育園の数をとか、キャパシティを広げるとかというよりは、いわゆる先生の手が欲しい０歳、２歳、３歳の保育園の状況を考えると、幼児になってから保育園から転園をする、そんな状況も加味して、このきんだぁくらぶはこれからニーズにこたえていくべき制度であるだろうなと、そのように思いますので、ぜひ拡充等も、展望も含めてお願いしたいというふうに思います。","respondent":"高橋幼保一元担当課長","answer":"委員おっしゃるとおり乳児の部分と幼児の部分、国の制度の中でも幼児教育の充実ということを言われていまして、品川区の私立幼稚園が担っている幼児教育、５歳児をとりますと、５１％が私立幼稚園にお願いして幼児教育を進めているところで、公立保育園については３１％。","voiceIndex":31,"id":"exchange-013"},{"speaker":"金野委員","kind":"質問","question":"ぜひよろしくお願いいたします。続きまして、１４７ページの庁舎等維持管理費のほうに移りたいと思います。これは構造上の問題だと思いますけれども、設計の段階でお気づきにならなかったのでしょうか。工事の着工から完成に至るまでの間、通常ですと工事、点検等するのが普通かなというふうに思うんですが、そのときに点検はなさってはいなかったのでしょうか。その点、お願いします。","respondent":"中島経理課長","answer":"その関係で少し設計段階で洗面台をドアから離して設置したんですけれども、今委員ご指摘のとおり若干ぶつかる危険性もあるですので、早急に私ども調査させていただいて、必要な改修をさせていただきたいというふうに考えてあります。","voiceIndex":33,"id":"exchange-014"},{"speaker":"金野委員","kind":"質問・要望","question":"この予算も大事な区民の皆さんの税金でもあるわけですので、やはりそういった設計段階からしっかり見ていただきながら、改修していただくのは本当にありがたい限りでありますけれども、やはりそういった一つ一つのことに対しても見ていく必要があるのではないかというふうに思いますので、どうぞこの点を何か検討していただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"私からは１４９ページの奨学金貸付事業について、幾つかお伺いしたいと思います。子育て世代の負担軽減を求める声が高まっておりますけれども、教育費の負担軽減を求める声、品川区にはしっかりと届いているのかどうか、まず認識を伺いたいと思います。","respondent":"鷹倉区民課長","answer":"私ども奨学金ということで、区民の方の負担を軽減するための制度ということで大変喜ばれている、このように考えているところです。","voiceIndex":37,"id":"exchange-016"},{"speaker":"中塚委員","kind":"質問","question":"品川区の奨学金について、公立、私立の在学資金を少し調べてみました。公立は月１万３,０００円、私立は２万８,０００円、まず、この金額の設定の理由といいますか、根拠といいますか、その理由を教えてください。その創設当時からこの金額の推移、どういうふうにたどっているのか教えてください。","respondent":"鷹倉区民課長","answer":"公立で入学準備金が７万円、私立でその３倍近い２０万円、そして在学資金で公立月額が１万３,０００円、私立月額２万８,０００円です。","voiceIndex":39,"id":"exchange-017"},{"speaker":"中塚委員","kind":"質問","question":"私も創設から大体２０年ぐらいかかって、その推移が正直わからなかったもので、創設当時がどうで、今がどういう推移なのか、雑駁でも結構ですけど、ちょっと教えていただけますか。","respondent":"鷹倉区民課長","answer":"正確なことを後でお伝えしたいと思います。","voiceIndex":41,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"推移については後ほどご説明ください。私は今区民の暮らしの実態を見ておりますと、底が抜けたような暮らしの苦しさ、所得を見ますと、サラリーマンの平均給与は９年連続右肩下がり、こうした実態から在学資金を増やす必要があるんじゃないのかと考えています。ぜひそのご見解を教えてください。","respondent":"鷹倉区民課長","answer":"ただ、今後どういう形になっていくかというのは経済状態をよく見守っていかなきゃいけないということはありますが、平成２０年度に関しては据え置くというようなことで進めさせていただいているところです。","voiceIndex":43,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川区よりも若干多いんですよね。なぜ東京都のやつより品川区のほうが安いのか教えていただきたい。奨学金は基本的に併用ができませんから、私はせめて東京都までまずは同額にして、それより充実させることはあっても、低いということはないんじゃないのかなと思うんですけれども、なぜ品川区のほうが少ないのか理由をご説明ください。","respondent":"鷹倉区民課長","answer":"それぞれの自治体がそれぞれの判断のもとに奨学金を運営しているわけです。それぞれの自治体の判断があります。そして、当然議会にご提案して承認を得た上でやってきているものです。東京都は東京都の判断のもとにその数字をつくられたです。","voiceIndex":45,"id":"exchange-020"},{"speaker":"中塚委員","kind":"提案","question":"品川区がどういう判断をしているのか、私はせめて品川区と東京都の奨学金は併用ができないわけですから、せめて同額にすべき、安くさせる理由はどこにもないと思います。授業料、全日制で年間８万２,８００円、今都議会が開催され値上げが提案されているそうですけれども、その金額は年間１２万２,４００円、上がっているんですね。","respondent":"鷹倉区民課長","answer":"私どもも区の奨学金ですから、今後いろいろな区民ニーズを受けながら検討していくことは当然あるわけですから、今のところ、今年度については据え置きという形でご提案申し上げているところです。","voiceIndex":47,"id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"今それぞれ選択肢があるとのご説明がありました。私、せめて東京都並みに引き上げて、さらなる充実を求めていきたいと思います。ですから、品川区の無利子奨学金というのは、非常に喜ばれているんですよね。ぜひ、まずこれを大学生まで広げていただきたい。品川の高校生に対しても、大学支援を応援していただきたいと思うんですけれども、まずはお考えを教えてください。","respondent":"鷹倉区民課長","answer":"ただ、大学生は大学生という形で、ほかの運営主体がそういう役割を担ってやっていくということで、役割分担していくのが一番適切な運営だと思ってあります。","voiceIndex":49,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"一歩足を踏み出すべきではないかと思うんですね。そもそも奨学金は終戦直前から始まって、ずっと無利子が原則でした。しかし、１９８４年から有利子が始まって、今では無利子と有利子が約倍も違っている。伺いたいのは、大学の高い学費が高校生の進路を狭めていると思わないのか、選択といいますけれども、選択しようがない実態をご存じなのか、ちょっと教えてください。","respondent":"鷹倉区民課長","answer":"住民の方が行政サービスを享受していただく、これが適切な運営だと思ってあります。","voiceIndex":51,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"この立場にしっかりまずは立っていただきたいと思うんですね。今年の１月３日の日本学生支援機構の無利子奨学金を受けられなかった、今ちょうど受験シーズンですけど、春の大学受験予定の高校生、無利子奨学金を受けられなかった高校生は全国で約１０万人。この１万人の高校生の気持ちを理解できますか。この不安な気持ち、わかりますか。高校生の気持ちは伝わっているでしょうか、教えてください。","respondent":"鷹倉区民課長","answer":"今の数字の中身、詳しいことはよくわからないんですが、ただ、私ども奨学金を運営する中で、奨学金というのは当然勉学が優秀な方ということを前提としておりますので、今の方がどういう方なのか、優秀なのかどうなのか、その辺のところの数字も入ってくるのかどうか。","voiceIndex":53,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"優秀かどうかわからないじゃなくて、有利子を申し込んで受けられなかった高校生が１０万人、そのうち約１万人が無利子を申し込めなかったわけですね。そこをぜひ見ていただきたいと考えています。そもそも奨学金というのは貸し付けですから、卒業と同時に莫大な借金を背負うことになるわけですよね。ぜひ返済の必要のない給付制度に一歩一歩足を踏み込んでいただきたいと思いますけれども、いかがでしょうか。","respondent":"鷹倉区民課長","answer":"ただ、私ども事前にまとめてお返しするという制度が実はございまして、その制度を使っていただきますと、実はかなり有利に返済額が減るという制度があります。これを積極的に使っていただいている方もいらっしゃるという事実をお伝えしたいなと、このように思ってあります。","voiceIndex":55,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"これで最後になりますけれども、学生の実態、そして卒業後の若者の仕事の実態、そこを全く理解していない、そういう答弁だと思います。そもそも大学の学費が高過ぎることに大きな私は問題があると思っています。世界では学費無償がその流れです。次の世代を大事にしない社会に決して未来はありません。心を寄せていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":57,"id":"exchange-026"},{"speaker":"阿部委員","kind":"質問","question":"国際友好協会、これは財団法人になっているのではありますけれども、この中で毎年のように区から１億円前後お金が出ているわけですけれども、この金額の根拠というのはどのように計算され、また考えられているのでしょうか教えてください。","respondent":"桑村総務課長","answer":"いわゆる補助金の根拠ということになろうかと思いますけれども、一つは国際交流に果たす財団の役割というものを区のほうで認めているわけですので、それに対してどういう事業を友好協会のほうでも検討され、また。","voiceIndex":59,"id":"exchange-027"},{"speaker":"阿部委員","kind":"質問","question":"国際友好協会の全体の収支を見ますと、大体年間１億５,０００万円ぐらいになっているかと思いますが、財団の中での財産収入というのは、その中で６００万円程度、主には区からの支出になっているということを踏まえてお伺いします。その中で、どのような視点で予算査定をされているのか、全体の経費のかかり方がちょっと高いんじゃないかと思われることはないか、その辺をお伺いしたいと思います。","respondent":"桑村総務課長","answer":"友好協会の事業ですけれども、これはいわゆる３都市を中心とする交流事業と、それから実際上区のほうにいらっしゃる外国人の方等についての日本語教室ですとか、あるいは料理教室ですとか、そういった事業をされているわけです。","voiceIndex":61,"id":"exchange-028"},{"speaker":"阿部委員","kind":"意見","question":"評議委員会などに出ましても、やはり出てくる資料も少ないというような現状をこの１年間見てまいりました。財団法人ももっと切り詰め、あるいは経費をいかに有効に使っていくか、そして、それをどのように使っているかを公表するということをさらに推し進めていただかないと、なかなか財団法人の活動として理解が得られないのではないかと思いますが、その辺の考え方をもう一回お願いします。","respondent":"桑村総務課長","answer":"情報公開等の手続もきちっと整っておりますので、不透明ということはちょっと当たらないんではないかというふうに思ってありますけれども、そういった中のもの、いわゆるどういう事業をしているか、あるいはそれについてどう経費をかけていくかということについて。","voiceIndex":63,"id":"exchange-029"},{"speaker":"阿部委員","kind":"質問・要望","question":"関連して、この国際友好協会の役割、今やっている内容というのは、比較的交流にかかわるところが多い。これから品川区がまさに国際都市、その玄関口として機能していくためには、もっと違う形での国際交流あるいは足元での、この品川区内での国際交流というのも進めていくべきだと思うんですけれども、その辺はいかがでしょうか。","respondent":"桑村総務課長","answer":"もちろん地域でのいわゆる国際化、あるいはそういったほかのところのいわゆるもっと違う意味での国際化の事業といったものが必要だというのは、財団法人も十分認識しているところでありますし、私どももそういうふうに考えてありますので。","voiceIndex":65,"id":"exchange-030"},{"speaker":"阿部委員","kind":"質問","question":"この件はこれで終わります。第２に、１５９ページ、犯罪被害者支援についてなんですが、この件につきましては、昨年度一般質問の中でぜひ品川区でも対応をということを言わせていただきまして、新年度予算の中に盛り込んでいただいたことを大変ありがたく思っております。この予算の内訳について簡単に教えていただけないでしょうか。","respondent":"中川原広報広聴課長","answer":"予算の内訳ですが、品川区としましては、犯罪被害者支援の区としての取り組みの内容としまして、区民相談室に総合案内の窓口を設置しまして、そこで相談をお受けする中で、今犯罪に遭われた被害者の方が求めている支援の中に、裁判所とか病院とか。","voiceIndex":67,"id":"exchange-031"},{"speaker":"阿部委員","kind":"質問","question":"この付添人の存在というのは、非常に大切だと考えています。区でも、人権関係の方々にお願いするというふうには聞いておりますけれども、ただ人権意識の高い方というだけではなくて、やはり専門の研修を受けられる必要があるのではないかと思いますが、その点についていかがお考えでしょうか。","respondent":"中川原広報広聴課長","answer":"心のケアについて、役所の職員も含めてですが、心に傷をつけてしまわないようにどう対応するかというような場面、そういったいろんなことが想定されますので、それを先ほどお話がありました支援センターのほうとも共同しまして。","voiceIndex":69,"id":"exchange-032"},{"speaker":"阿部委員","kind":"質問","question":"三つ目なんですけれども、区民保養所についてお伺いします。この借上保養所、先ほども質問にありまして、効率的な運用ができているというような自己評価もお伺いしたんですけれども、本年度の春から年末ぐらいまでの数字を見ますと、利用された方は、３,０００人余りということです。かつ、借り上げの経費は４,０００万円余りかかると。区は持ち出しをすると。この点についていかがお考えでしょうか。","respondent":"鷹倉区民課長","answer":"したがいまして、今委員のご指摘のあった旅館の、部屋数の使われていないところ、これを特定日、より区民が使われる特定日にシフトするような形でやっていきたいなと、このように考えているところです。","voiceIndex":71,"id":"exchange-033"},{"speaker":"阿部委員","kind":"質問・要望","question":"４点目、避難所についてお伺いします。防災の避難所なんですけれども、大地震のあった、例えば中越の地震の避難所の様子などを見ておりますと、アンケートなどでは改善の要望が一番多いのは圧倒的にトイレの改善についてです。","respondent":"久保田防災課長","answer":"さらに実はトイレ対策、仮設便槽だけではどうかという問題もありますので、最近は水洗トイレをやはり壊れていなければ使いたいということで、これはプールの水とか、あるいは学校に設置している井戸なんかを利用して。","voiceIndex":73,"id":"exchange-034"},{"speaker":"阿部委員","kind":"質問","question":"品川では、水洗も普及しておりますが、災害時にバキュームカー、くみ取りの車ですね、あれもやはり必要になってくるかと思います。そういったところとの連携というのは、区としては現在どのようになっていますでしょうか。","respondent":"久保田防災課長","answer":"トイレのくみ取りということも必要になってきますので、これは現在環境清掃事業部のほうで委託している民間事業者を活用してトイレのくみ取りをやるというような形でバキュームカーの活用についても計画しています。","voiceIndex":75,"id":"exchange-035"},{"speaker":"原委員","kind":"質問","question":"私のほうは、先ほど委員からあった１４３ページ、品川区国際友好協会補助金について、それと関連したことでお伺いをしていきたいと思います。","respondent":"桑村総務課長","answer":"国際友好協会につきましては、所管は総務課になります。補助金ですけれども、ちょっと今手元で調べますので、ちょっとお待ちいただきたいと思います。すみません。","voiceIndex":79,"id":"exchange-036"},{"speaker":"原委員","kind":"質問・要望","question":"いいですか。ちょっと意味がわからないようですね。では、基本的なところで、じゃあ、その質問をやめさせていただきまして、申しわけありません。それから、ちょっと先ほど質問をやめたんですけど、これは総務課だけでやっているのか、ほかの都道府県の知事関係の許可を受けているのか受けていないのか、その辺をもう一度ご質問をさせていただければと思います。","respondent":"桑村総務課長","answer":"大変失礼しました。５カ年の補助金の推移ですけれども、平成１５年度からは８,１４１万９,０００円、平成１６年度が７,７３５万４,０００円、平成１７年度が７,７１８万４,０００円、平成１８年度が１億９７５万６,０００円です。","voiceIndex":81,"id":"exchange-037"},{"speaker":"原委員","kind":"質問","question":"もう一度、すみません。もう一度質問の趣旨を申し上げますと、これは登記簿上の財団法人、これが何を、もう少しじゃあ詳しく申し上げますと、１０月からたぶん国のほうでは５年間にかけて移行していく形が出てこようかと思いまして、そこについてちょっとお伺いをしていきたいと思いまして、ご質問させていただきました。ご答弁、よろしくお願いします。","respondent":"桑村総務課長","answer":"いわゆる公益法人の形が今後変わっていくという、いわゆるものですけれども、一定の寄附行為に基づいての公益事業というのが非常に多くなってこなければ、税制の改正ですとか、そういったものが進むというふうに聞いてございまして、その意味では、どういう形で進んでいくか。","voiceIndex":83,"id":"exchange-038"},{"speaker":"原委員","kind":"質問","question":"そうなんです。ですから、一般の財団としての機能で品川区としてはいいのかどうか、これが公益性を持った財団となっていくのかどうか、その辺についてちょっとお考えをお聞かせ願えればと思います。","respondent":"桑村総務課長","answer":"収入で、いわゆる教室等もやっている部分がありますけれども、その意味では、それほど大きな意味での変更は必要ないのかなというふうに思います。ただ、そういう意味では、一定の検討は必要ですので、これから検討させていただきたいというふうに思ってあります。","voiceIndex":85,"id":"exchange-039"},{"speaker":"原委員","kind":"質問","question":"こういったことというのは、財団だけではなくて、たぶん類似しているところでは、ちょっと話がずれちゃうかもわかりませんけれども、宅建協会ですとか、他の団体等について、これから５年間でかなりの見直し等が出てくると思いますので、私のほうではこの数字が先ほど伺った５年間、直近のが出ているのがいい悪いという問題ではなくて、区民の税金を使われて、ここに補助金として入っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-040"},{"speaker":"山元委員","kind":"質問・要望","question":"私は１５１ページの結婚サポート事業について、もうちょっと具体的な内容といいますか、教えていただきたいと思います。区が結婚紹介事業者と連携することによりということなんですが、実際、事業者は決定しているんでしょうか。それともまだ未定なんでしょうか。","respondent":"鷹倉区民課長","answer":"今回予算が議決された後に、業者をプロポーザル方式で選定してまいりたいと考えているところです。","voiceIndex":89,"id":"exchange-041"},{"speaker":"山元委員","kind":"意見","question":"そうしまして、もうちょっと具体的な話にまいりますけども、年に２回、また各３時間相当で定員４０人でセミナーが行われるということなんですが、実際４０人の中は男女４０人、それとも男性だけとか女性だけとかというような何か決まりがありますか。","respondent":"鷹倉区民課長","answer":"今のところ決まりはないわけですけども、一定のお部屋でこういうセミナーをしていくということで、４０人ということで今考えているわけですが、実はこの結婚サポート事業の対象年齢をどうするかという大きな問題もございまして、あるいは対象は当然原則は区民なわけですけども。","voiceIndex":91,"id":"exchange-042"},{"speaker":"山元委員","kind":"意見","question":"本当に真剣に悩んでいる親御さんもたくさんいるかなとは思いますけれども、その中で、もっと具体的になっていきますと、実は専門家による個別相談を毎月２回実施するということなんですが、専門家というのはどういう方たちなのか、また、何人応募なさるかわからないので人数もあれだと思いますが、予定としては何人ぐらい専門家の方をお願いする予定でいらっしゃいますか。","respondent":"鷹倉区民課長","answer":"先ほど申し上げたとおり、４月以降事業者を選定していくわけですけども、今結婚産業といいますか、結婚事業といいますか、いろんな形態があるわけですけども、我々が想定しているのは一定のそれぞれ会員登録されている方の情報のマッチングといいますか。","voiceIndex":93,"id":"exchange-043"},{"speaker":"山元委員","kind":"質問","question":"現実的に事業を行われる場所というのは、どういうところを想定していらっしゃるんでしょうか。","respondent":"鷹倉区民課長","answer":"したがって、今想定しているのは、区役所に来たときに、あれっ、あの方はという、そういうことがわからないような形にすると、より来やすくなるのかなと。より来やすくなる工夫、そういう工夫をして、区民の方に喜ばれる事業にしていきたいなと、このように考えてあります。","voiceIndex":95,"id":"exchange-044"},{"speaker":"山元委員","kind":"意見","question":"まだ予算が通りませんのであれなんですが、現実、やはりお金がかかってくると思うんですけれども、実際どのぐらいで、ここに区民会員は登録料金を割引してくださると書いてあるんですが、現実にやっぱりお金を持っている方、持っていない方がいると思うんですが、どのぐらいの予算でいらっしゃいますか。","respondent":"鷹倉区民課長","answer":"したがって、従来その事業者がそれぞれ持っておられる会員登録料をどのように見ていくか、そして割引をどのように見ていくか、その提案の中からより区民の方が負担しやすい形態のところをとっていきたいなと、このように考えているところです。","voiceIndex":97,"id":"exchange-045"},{"speaker":"山元委員","kind":"意見","question":"実際パートナーを紹介するというのは、どういう形というか、形式というか、例えばコンピュータ診断というか、具体的に何かお考えしていますか。","respondent":"鷹倉区民課長","answer":"したがって、そういうものが提案されてくるのかな。ただ、もっといい方法を提案されてくるのかどうか、これは今後提案を見ていきたいと思ってあります。","voiceIndex":99,"id":"exchange-046"},{"speaker":"井桁委員","kind":"質問","question":"第１点、１５３ページの町会ホームページ作成支援等委託とありますけれども、先ほどホームページの講習会、パンフレットの作成と説明がありましたけれども、具体的にこの講習会は何回、そして対象といいますか、全町会が対象なんでしょうけれども、この講習会について詳しくお伺いします。","respondent":"中山地域活動課長","answer":"現在予定しておりますのは、ホームページ作成講習会として２日間を予定しております。平日の夜と土曜日の午後２時間程度を予定しておりまして、定員としてはそれぞれ２０名程度を考えてあります。","voiceIndex":103,"id":"exchange-047"},{"speaker":"井桁委員","kind":"質問","question":"一度つくって、そのままになってしまったりとか、あと結構各町会で負担をしてつくっているような現状が多々あるんですけれども、維持管理という意味でも、今後この支援というのは講習会の拡大であったりとか、どういった方向に進んでいくのかなというのがちょっと不安なので、その点を方向性といいますか、それをもう一度お伺いします。","respondent":"中山地域活動課長","answer":"これは回数によります。受けられる方の力量にもよりますけども、５回以内の派遣を考えておりまして、予定としては５町会ほどが実際の作成にこの中から入っていければ、一つの目標かなというふうに思っております。","voiceIndex":105,"id":"exchange-048"},{"speaker":"井桁委員","kind":"質問","question":"次、１５９ページなんですけれども、ホームページ等経費とありまして、平成１９年度の予算の中では、ホームページ運用等経費のところだと思うんですけれども、そこで品川区ホームページと書いてあったんですけれども、その予算から比べると、大分今年は３倍強の予算額になっているんですけれども。","respondent":"中川原広報広聴課長","answer":"そういうことで、去年ないメニューもここに入っております。ということで、バージョンアップはしているということです。","voiceIndex":107,"id":"exchange-049"},{"speaker":"井桁委員","kind":"質問","question":"大分予算のほうが増えているということで、今年は機能の充実と先ほど説明にありましたけれども、具体的に、わかりやすくというのはあれなんでしょうけれども、改善であったりとか、そういったところをお聞きしたいと思います。","respondent":"中川原広報広聴課長","answer":"そこで、ＣＭＳという機能を導入しまして、速やかに、今までは１日かけないと新しい情報に更新できないとか、リンクがすぐ切れてしまうとか、いろいろ不具合があったんですが、ＣＭＳという機能を導入することでリンク切れも防げますし。","voiceIndex":109,"id":"exchange-050"},{"speaker":"井桁委員","kind":"意見","question":"このホームページなんですけども、実際に私なんかは使っていて、使いやすいのかなという「はてな」が残ってしまう。その中で、品川区のホームページ、よく私が言われるのは、何かわかりづらいというか、何か変なところに飛んでしまったりとか、あと知りたい情報がすぐわからないとか、そういった声をよく聞いておりますので、ぜひこの辺の改善をますますよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":111,"id":"exchange-051"},{"speaker":"山内委員","kind":"質問","question":"私は１６７ページの災害時応急物資確保経費についてお尋ねします。最初に、毛布クリーニング経費とありますけれども、今年度は１６０万円計上し、そして平成２０年度は９６万円、約１００万円なんですが、この経費というものは使われたからクリーニングするのか、それとも備蓄していて汚れちゃうから毎年クリーニングを重ねていくのか、ちょっとその辺を教えてください。","respondent":"久保田防災課長","answer":"毛布クリーニングの予算の計上の考え方ですけども、昨年は確かに１６０万円ということで、今年は９６万円です。この毛布クリーニングというのは、実は備蓄してある毛布は使っておりません。","voiceIndex":113,"id":"exchange-052"},{"speaker":"山内委員","kind":"質問・要望","question":"このアルファ化米についてちょっとお伺いしたいんですけど、裏に刻印が２００８年２月１９日と出ていました。これはもしかして賞味期限が切れちゃっているのかなと思ったんですが、いいや、食べちゃえと思って食べたんですけど、表に５年保証と書いてあるんですけれども、これは５年保証というのは、５年前の２月１９日にできて、この５年間食べれますよという意味で、５年保証というのをやっているんですか。","respondent":"久保田防災課長","answer":"いわゆる賞味期限ということで解釈していただいて結構だと思います。したがって、５年前に買ったものが５年後に賞味期限が切れるです。委員のおっしゃるのは、２月に切れるということだったと思います。","voiceIndex":115,"id":"exchange-053"},{"speaker":"山内委員","kind":"質問","question":"乾パンを食べるよりは、お水もしくはお湯を入れると大体２０分ぐらいででき上がるんですけれども、非常においしいんじゃないかなと思いまして、ちょっと感心はしたんですが、この備蓄という形で考えますと、どうしてもやっぱり数多く確保しておかなくてはならないと思うんですけれども、今ちょっと平成１５年修正の品川区地域防災計画を見ましたら。","respondent":"久保田防災課長","answer":"品川区の場合は、１日だけじゃなくて約２日間は持ちこたえられるようにということで、約６食、避難者人口が今１０万３,０００人ぐらいおられますので、大体２日分は確保しているということで、４０万食強を確保しているという状況です。","voiceIndex":117,"id":"exchange-054"},{"speaker":"山内委員","kind":"質問","question":"せっかく区がお金を出して購入して備蓄をしているわけですから、これは有効利用する必要があると思うんですけれども、その有効利用について、何かお考えというのはあるのか、ちょっと教えていただけますか。","respondent":"久保田防災課長","answer":"大人の場合はそういうことをやっていませんけども。そういうことを通じて、家庭の中でやはり年に１回ぐらいは試食をして、防災の大切さを考えていただきたいということでやっているということで、特に有効活用のほうは今のところ考えておりません。","voiceIndex":119,"id":"exchange-055"},{"speaker":"山内委員","kind":"質問","question":"私ももらって約２年間ぐらい中に入っていたんですよ。そうすると、忘れられちゃうものかなと思うんですね。あることすら忘れちゃうので、たまたま昨日探したらば出てきて、食べてみようといって食べたんですよね。そういう意味では、食べてもらうという体験をすることが私は大事だと思うんですけども、最後に考え方を教えていただいて終わりたいと思います。","respondent":"久保田防災課長","answer":"学校についても、一部ですが、これは当然試食のように子どもさんたちに食べさせて、防災の大切さをやっぱり味わってもらうと、こういう取り組みをやっている学校も多くあります。","voiceIndex":121,"id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問","question":"１４５ページ、人権啓発、職員研修、１４７ページ、職員健康管理、１５５ページ、近隣セキュリティシステムについてお伺いします。品川区民憲章には、「互いに人権を尊重し、人間性豊かな環境をつくります」と書いてありますけれども、人権はとても幅が広いんですが、今回は少数派、セクシュアル・マイノリティー、性的少数者の人権に絞って伺います。","respondent":"吉岡人権啓発課長","answer":"セクシュアル・マイノリティーの実態につきましては、今委員ご質問の中で述べられましたように、４％、６％というお話がございましたけれども、これはいろいろ、研究者によっても説が分かれているところもありますし、調査によって変わってくる部分もあろうかと思います。","voiceIndex":127,"id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問","question":"私は男性からちょっと相談を受けました。質問を３点いたします。２点目は、養護教諭とか、性教育担当者が悩んでいる子どもの心のケアをしてほしい。三つ目は、性的指向、性同一性障害に関する悩みとか葛藤を相談することのできる窓口をつくってほしい、こういった声が上がっていますが、いかがでしょうか。","respondent":"吉岡人権啓発課長、榎本人事課長","answer":"それからあと、３番目の悩みの相談の場所ですけれども、現在特別に性的マイノリティーの方のご相談の場所という設定にはなってございませんけれども、区民相談室ですとか。研修については、いろんな人権研修という形でそれぞれ分野を区切ってやっておりますけれども、そういう形である程度認知されてきたもの、もしくは最先端のものという形で、まず講師をどういうふうに選ぶかというところと。","voiceIndex":129,"id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろな障害というひとくくりの中に入っているので、ぜひ私は今日このテーマを取り上げましたので、ここのところが前進するようなパンフレットをつくっていただきたいなと思っています。そういった面では、ぜひ大事な税金なので、さまざまな人権の侵害をされている方を救っていく、そういった立場でぜひ資料、パンフレットなどもつくっていただきたいんですが、いかがでしょうか。","respondent":"吉岡人権啓発課長","answer":"それで、ビデオなんですけれども、かなり数がありますけれども、今委員のお話にもございましたように人権の課題というのは、先ほどの性的マイノリティーのお話も含めまして、高齢者の問題ですとか、障害者の問題ですとか、非常に多岐にわたっておりますので。","voiceIndex":132,"id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"平成２０年度の近隣セキュリティのところを見ましたら、予算が平成１７年度の初年度投資のときよりも、額がちょっと増えているということで、子機のところだと思うんですが、どうして予算が増えているのか。子機がどのような中身に変わっているのか。ソフトバンクとの契約がどう変わっているのか、ここをお知らせください。職員のところは、病気休暇の状況をお伺いしたいと思います。","respondent":"高濱生活安全担当課長、榎本人事課長","answer":"近隣セキュリティシステムに関するご質問にお答えいたします。増加分につきましては、最も大きいものが次年度、平成２０年度におきまして第三世代の子機を製造いたしますので、そのための経費になります。年休の取得日数ですけれども、１年間で平成１９年、１４日と７時間です。それから、残業の時間数ですが、直近でとっている平成１８年度が１人当たり年間１０５.３時間です。それから、サービス残業についてはありません。","voiceIndex":134,"id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問・要望","question":"健康管理のところは、休職後の退職された方の人数がわかったら教えていただきたいのと、あと残業で平均を伺ったんですが、一番最も多い方というのはどのくらいいるのかと、あと安全衛生管理委員会の２月の資料のところに、過労死ラインを超えているんでしょうか、１００時間とか８０時間とか、恒常的に月４０時間を超えている職員の、「職員の健康管理のための面接について」という資料があるので。","respondent":"高濱生活安全担当課長、榎本人事課長、中山地域活動課長","answer":"その理由で変える予定です。健康管理の面接の関係ですけれども、１００時間を超えている人は産業医の面接、それから８０時間から１００時間を超えている人は看護師の面接ということで。予算編成の根拠ですけれども、これはプロポーザルの提案の中で子機と通信料の値段が出ているものをベースに積算したものです。","voiceIndex":137,"id":"exchange-061"},{"speaker":"飯沼委員","kind":"提案","question":"下げているひもが細くて首に食い込んじゃってよくないとか、やっぱりそういう親御さんの声もいろいろ聞きながら、こういったところの改善を図ろうとしているのか、ちょっとその辺もお聞かせいただきたいんですけれども、「まもるっち」を始めて、いろいろ効果はあるし、たくさんの人の応援と協力をいただいて、子どもを守ってきていると、このことは重々わかっているんですが。","respondent":"中山地域活動課長、榎本人事課長","answer":"第三世代の切り替えは、国を挙げて、総務省の方針でやっております。平成２２年度にはソフトバンクはすべて第三世代に変わる、これを前提にプロポーザルをやったものです。サービス残業については、ないということです。ただし、今職員団体のほうから調査の依頼が来ているという段階です。","voiceIndex":141,"id":"exchange-062"},{"speaker":"飯沼委員","kind":"質問・要望","question":"「まもるっち」のところなんですけれども、特に親御さんの意見を十分聞いていただきたいなと思うのと、どんどんこのままでいくと予算が増えていくという心配もあるので、ぜひちょっと立ちどまって将来を考える時期ではないかなと思いますので、ぜひ重々考えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":144,"id":"exchange-063"},{"speaker":"藤原委員","kind":"質問","question":"１４５ページ、危機管理室経費、１４７ページ、人事給与関係事務費だと思います。それと、１５１ページの結婚サポートなんですけれども、３本の柱でやっていきますというのはわかったんですけれども、やっぱり一番中心になるのは民間企業にお金を、結婚相談所に登録する方へのお金を助成しますよと、これは助成事業なんでしょうか。","respondent":"桑村危機管理室長、榎本人事課長、鷹倉区民課長","answer":"平成１８年度からの危機管理室の対応状況を報告いたします。それで、あと区でどれぐらい採用の経費がかかっているかということですけれども、事務費のほかには人件費という形になりますので。結婚サポート事業の３本柱、一つ大きな柱として紹介支援という形で会員登録の分があります。","voiceIndex":146,"id":"exchange-064"},{"speaker":"藤原委員","kind":"質問","question":"でも、特例があって、女性のほうが高いパーティーなんかは、いわゆる特定というか、特別のパーティーで、お医者さん、弁護士、それと公務員の方の男性が来るときは、女性の会費のほうが高いわけですから、せっかく品川区がやるんですから、もし望む方がいるならば、公務員の、品川区役所の職員もメーンに出してやっていくというのは、なんか特徴になっていいと思うんですが、その辺、いかがでしょう。","respondent":"桑村危機管理室長、榎本人事課長、鷹倉区民課長","answer":"ただ、日常的には、危機管理はいかに日常的な組織を強くするかということが危機管理の基本ですので。採用の関係ですけれども、区で採用していく方向なのかということですが、事務と技術系の職員につきましては、試験は２３区の共通試験ですけれども。在勤まで広げると、ほかの民間の方をどうするのかというのがあります。とりあえずこの辺から出発したいなと、このように考えてあります。","voiceIndex":150,"id":"exchange-065"},{"speaker":"稲川委員","kind":"質問","question":"午前中からほかの委員の皆様からいろいろあったんですが、１６９ページの区民保養所経費について、それとちょっと外れてしまうのかもしれないですけど、自分の考えと、１６３ページの緊急地震速報について質問をします。そして、その費用がどういう形で流れているのかを教えてください。","respondent":"鷹倉区民課長","answer":"ただし、この事業者については、従来のホテル・旅館と代理店との関係の中でやっていくと、その中でやっていくということで、特に私ども事務費というものはこの中には積算根拠には入ってございません。１室当たりの借上料が幾ら、こういう形で積算しているものです。","voiceIndex":155,"id":"exchange-066"},{"speaker":"稲川委員","kind":"質問","question":"ということは、近畿日本ツーリストには、品川区からお金は、そういう経費的なものは行っていなくてということでよろしいんですよね。ということは、近畿日本ツーリストにはあまりメリットというのは、近畿日本ツーリストのことを考えてもしようがないんですけど、メリットはないということですか。","respondent":"鷹倉区民課長","answer":"この関係の中で一定の収益が上がるというようなことがベースにあって、私どもについて特に受付事務手数料は要求しなくてもやっていけると、こういうことです。","voiceIndex":157,"id":"exchange-067"},{"speaker":"稲川委員","kind":"質問","question":"それで、先ほどＫＮＴが入ることによって、ネットワークがすごく広がるということだったんですが、今借上施設が３件なんですが、これから先、もっと増やしていく予定というのはあるんですか。ネットワークがあると課長はおっしゃったので、今後の展望であちらこちらに今度広がりが出てくるというお話だったので、今後どうなるか教えてください。","respondent":"鷹倉区民課長","answer":"この借上施設は、まず暖景苑を廃止することに伴う区民の保養所ニーズに応えるという形で、暖景苑は４７名定員だったところを今回４５名、３室、１定員が５名のところを、それぞれ三つのホテルですので４５人という形で進めているものです。","voiceIndex":159,"id":"exchange-068"},{"speaker":"稲川委員","kind":"質問","question":"ちょっと後先逆になってしまったんですが、私も新人の研修のときに、これは借り上げではなく、保養所の視察にお伺いをしたのですが、そのとき、私も素人ながら入ったばかりだったんですが、結構赤字が出ているじゃないかという話をしたところ、たしか課長だと思うんですが、あくまでも保養所なので、そこで利益を得てもという、何かそんな遠回しのお話があったんですが、今後保養所全体において。","respondent":"鷹倉区民課長","answer":"保養所といいますか、旅館・ホテルサービスというのは、民間でも当然やられております。区民の方が、区がやっている、提携しているところに行くことによって、より安心して利用されるということがある限り提供していくべきだと、このように考えてあります。","voiceIndex":161,"id":"exchange-069"},{"speaker":"稲川委員","kind":"意見","question":"保養所用のコマーシャルですよね。区民の人たちが気軽にご使用することのできる保養所を目指すのであれば、例えばポスターをつくるとか、夏になったら品川にも海と山がありますよみたいな、そういう感じで何かポスターを区民の施設に貼るとか、そういうお考えはありますか。","respondent":"鷹倉区民課長","answer":"したがって、若干不便さはありますが、ただ、メリットは実はあります。本人確認をするために、はがきというのは一番いいというのがございまして、多少不便はありますけれども、少しこれで様子を見させていただきたい、このように考えているところです。","voiceIndex":163,"id":"exchange-070"},{"speaker":"稲川委員","kind":"質問","question":"次、１６３ページの緊急地震速報についてお伺いをいたします。僕の認識が違ったら大変申しわけないんですが、この設置１１１台と書いてあるんですが、これはよくケーブルテレビが始めた、品川区もそうなんですが、この小さな子機をつける、子機というか、白い、今リースとかを、ケーブルテレビでもやっているのをつけるということなんですか、教えてください。","respondent":"久保田防災課長","answer":"緊急地震速報機器ですけれども、私ども今考えているのは、ケーブルテレビのものじゃなくて、これは平成１９年度の補正予算でお願いしたところで、今導入しているんですけれども、日本気象協会の機器を採用しまして、それで受信するというものです。","voiceIndex":165,"id":"exchange-071"},{"speaker":"稲川委員","kind":"意見","question":"実を言うと、ケーブルテレビがやっている緊急地震速報の機種があると思うんですが、それを私個人的なんですが自宅に設置をして、確かめるにも地震が来なければどういう状況になるかわからないという思いでいたんですが、実際これとは全く違うということなんですが、関連で、今品川区内にどれだけそういうあれが普及しているかというのは把握されていますか。","respondent":"久保田防災課長、堀越行財政改革担当課長","answer":"ケーブルテレビの普及状況は把握しておりません。ケーブルテレビの緊急地震速報ですが、１０月からサービスを開始しまして、今現在９８台個人のお宅に設置されていると、このように聞いております。","voiceIndex":169,"id":"exchange-072"},{"speaker":"稲川委員","kind":"確認","question":"すごく感動しました。けたたましい音が鳴って、「地震が発生します」と言って、しばらくしたら、本当に地震が来たんです。だから、情報にずれがあるんじゃないかという思いがあるんですが、その辺はだれに聞けばいいかわからないですが、やっぱり地震が来なければわからないという、本当に鳴るかどうかもわからないという中で、ただ、テレビ回線の間にかませているだけの機種ですので、その辺の確認を。","respondent":"堀越行財政改革担当課長","answer":"ちょっと今不具合がというようなお話ですので、そこら辺の部分については、いろいろ地震の震度ですとか、いろいろな状況ですとか、設定の状況等もありますので、その部分についてご説明等をしっかりするようにケーブルテレビのほうとも話していきたいと思います。","voiceIndex":172,"id":"exchange-073"},{"speaker":"稲川委員","kind":"質問","question":"時間がありますので、職員の研修経費、１４５ページなんですが、これは本当にただお伺いしたいというだけなんですが、職員の方が入って新人研修のときに、実際どういった研修、もちろん事務的なこととか、さまざまなスキルの向上とか、さまざまなことをやると思うんですが、具体的にどういった研修を新人のときにやるか教えてください。","respondent":"榎本人事課長","answer":"各区につきましては、各区の今までの区の中のいろんな事業の大まかな説明、それから人権研修、その他各区の事情に応じた研修を盛り込んでいるものです。","voiceIndex":174,"id":"exchange-074"},{"speaker":"稲川委員","kind":"質問","question":"実を言うと、庁内、私普通に歩いていて、こういうことをこの場所で言うのがどうかは別にいたしましても、普通に歩いていて、こちらから、例えば職員に対してすれ違うとき、目が合ったとき、会釈をするなり、「おはようあります」。あいさつ、「おはようあります」と言葉に出さなくてもいいですけど、例えば会釈をするとかが必要だと思うんですが、その辺、どうお考えですか。","respondent":"榎本人事課長","answer":"もちろん新人研修の中で接遇等をやっておりますけれども、庁内で歩いているときに、そうすると全員にあいさつをしなきゃいけないという形にもなりますので、どういう場面であいさつをしていくかというところで。","voiceIndex":176,"id":"exchange-075"},{"speaker":"武内委員","kind":"質問・要望","question":"緊急地震速報ですけど、来年度１１１台、それから平成２１年度であわせて１９９台という計画が載っておりましたけども、昨年の９月の補正でモデル設置ですか、これの補正があって、大体今５カ月ぐらいたっているわけですけど、何回か受信をされたのかどうかということと、それから以前に一般質問をやったときの答弁では、非常に通常のものよりも、気象庁のものよりも。","respondent":"久保田防災課長","answer":"緊急地震速報の状況ですけれども、平成１９年度の補正で現在１１施設に１３機設置導入を図っております。正直なところ、まだちょっと導入を図っていて、いろんな検証を始めていて間もなくというところもあるんですけども、何回か受信はしております。","voiceIndex":179,"id":"exchange-076"},{"speaker":"武内委員","kind":"質問・要望","question":"そのような中で、今回１１１台と大幅に予定されて、また来年度もあわせて１９９台ということで、モデル的な、検証はないけれども、やっぱり危険を少しでも回避できるためにということで、こういう形で載せていただいているということは非常にうれしく思っているわけですけども、さっきちょっと質問の中で、カウントダウンどおりにいかなかったとか、そういうお話があったんですけれど。","respondent":"久保田防災課長","answer":"そうは言っても、一刻も早くやはり導入する必要もありますので、そういったところは十分に進めていきたいというふうに考えております。","voiceIndex":181,"id":"exchange-077"},{"speaker":"武内委員","kind":"質問・要望","question":"確かにいろんなものがこれから出てくるのかなと、もっと精度の高いのとか、いろんな形で出てくれば、またそれも検証していただきながら、基本的にはすべての区有施設で可能な限り、平成２１年度以降も検討していただきたいということは要望します。","respondent":"斉藤防災安全担当課長","answer":"したがって、装備品等も配置しておりません。そこでこれを使おうという方針に基づきまして、３点セット、一つには鉄のふた、こちらをあけるスパナといいますけども、こちらをあけるものが一つあります。","voiceIndex":183,"id":"exchange-078"},{"speaker":"武内委員","kind":"質問","question":"私がお聞きしたかったのは、開閉器具の中に今３点セットとおっしゃったんですけど、実は防災課長に個別にちょっとご相談していた経緯があるんですけど、ミニポンプ隊か区民消火隊の関係の方から、いわゆる今お話に出てきたＣ級・Ｄ級にかかわってくるのかもしれないんですけど、消火栓からつなぐときに、消防団の方とかが使っているポンプのつなぎ口ですね、これとミニポンプだとか。","respondent":"斉藤防災安全担当課長","answer":"はい、今回の３点セットの中に含まれております。","voiceIndex":185,"id":"exchange-079"},{"speaker":"武内委員","kind":"質問・要望","question":"その上で中学生にもやっていただいて、そういったいろんな面で防災意識を持ってもらうということだと思うんですけども、これは一応来年度以降全校に広げていくということなんですが、その先々のねらいとして、今中学生が加わって防災訓練というのは、５校ぐらいなんでしょうかね、何校ぐらいかということも教えてもらいたいのと、あとゆくゆくそうした全中学校でこういう形で。","respondent":"久保田防災課長","answer":"中学校のポンプの配備についてですけれども、来年度４校をモデル的に配備して、その後小・中学校全校にこれは広げていこうと考えております。その理由ですけれども、現在新しい被害想定、地域防災計画の改訂によりまして、減災目標というのを定めております。","voiceIndex":187,"id":"exchange-080"},{"speaker":"渡部委員","kind":"質問・要望","question":"ここに住まわれている方々が６月の段階、７月の段階で皆さんご転居されることになると思うんですが、そうなった場合、いわゆるこの災害に当たる職員、ほかにも待機寮があって、全部で７寮ですか、あって、六十数名いるんですが、この部分、ごっそり抜けちゃうんでしょうか、それとも例えばそこで転居されて遠くに引っ越しちゃったら別ですけど、ほかの方がここのいわゆる人数の部分に従事されるのか。","respondent":"榎本人事課長、久保田防災課長","answer":"ただ全員が行かれないものですから、その中で希望する者は西五反田のほうに移りまして、それ以外の方については民間のほうということで、若干減るような形にはなりますけれども、そんなに大きく減るという職員数ではございません。その間、実はこの周辺についてのカバーということにもなるんですけども、そのほかに私ども荏原の備蓄倉庫とか、それからそういったところが近場ではありますので、そういったところからカバーしていくというふうに考えてあります。","voiceIndex":190,"id":"exchange-081"},{"speaker":"渡部委員","kind":"質問","question":"その部分というのは今後待機寮が完成しましても、また地域に開放といいますか、貸し出しは続けていただけるんでしょうか。お教えください。","respondent":"榎本人事課長","answer":"今現在２階にある会議室は、改築後も１階におりるという形で継続して使えるようにいたします。","voiceIndex":193,"id":"exchange-082"},{"speaker":"渡部委員","kind":"質問","question":"１５５ページの近隣セキュリティシステムの運営の部分でお伺いします。先ほど平成２２年にソフトバンク自体が第三世代の改正にすべて切り替わるということであれば、その後の今使っている第二世代の部分も切り替えていかなければならないと思うんですが、あと２年間で切り替えていかなければいけないのかなと思うんですけれども、その辺の計画が、この先の計画がわかれば教えていただけますでしょうか。","respondent":"高濱生活安全担当課長","answer":"センターシステム自体もそれに対応しなければいけませんので、すべてを一斉に行う予定です。したがいまして、夏休みあるいは春休みを予定することになると思います。平成２２年に世代がえになるので、それまでに段階的にというのも同じです。","voiceIndex":195,"id":"exchange-083"},{"speaker":"渡部委員","kind":"質問・要望","question":"前に質問させていただきました切り替えについては、古いやつを返して、新しいものをもらうということで、空白期間がないようにうまくつないでいただきたいと思います。といいますのは、二つですと、というより、三つであれば、例えばそこにおじいちゃんのおうちの電話番号を入れられるとか、また、ちょっと枠が広がるのかなというような思いもあったものですから、お伺いさせていただきました。","respondent":"高濱生活安全担当課長","answer":"それについては、子どもが使用するものですから、それほど大きな変更は加えたくないというのがこちらの考えです。今委員ご提案の通話先、オプション契約における通話先を増やしてはということについては、これは可能ではないかと考えますので、検討させていただきたいと思います。","voiceIndex":197,"id":"exchange-084"},{"speaker":"渡部委員","kind":"質問","question":"この近隣セキュリティシステムなんですが、平成１７年から始まりまして、これでたしか切り替わるのは３回目ですかね、というように認識しておりますが、それでどんどんいいものができてきて、安全を守れるのであれば、僕はそれが一番いいと思います。そういうお話というのは出たことはありますでしょうか、ちょっとお伺いできますでしょうか。","respondent":"高濱生活安全担当課長","answer":"近隣セキュリティシステムの根幹を成す部分に協力者制度というのがあります。実は区が対応するというよりも、協力者が子どもを守るというのが基本になります。したがいまして、その制度を活用する範囲内であれば、他の活用についても検討の余地はあると考えております。","voiceIndex":199,"id":"exchange-085"},{"speaker":"渡部委員","kind":"質問","question":"前々から思っていました防犯上いろいろな広がりというのが、このシステムはできるのかなとは考えておりました。防災センターと通話ができるわけで、何が起こっているかというのが瞬時にわかるというのは、また別の活用で、こればすばらしいのかなというふうに考えていたものですから、今そのような質問をさせていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":201,"id":"exchange-086"},{"speaker":"大沢委員","kind":"質問・要望","question":"１４５ページの男女共同参画、それと職員研修費、そして１５７ページ、タウンミーティング、以上３点についてお伺いします。時間がちょっと余りましたら、もう一点追加をさせていただきたいと思います。このワークライフバランス、先ほど別の委員からもありましたけれども、仕事と生活の両立ということですけど、このアクションプランとはいかなるものか、簡単にご説明願いたいと思います。","respondent":"吉岡人権啓発課長","answer":"それで、アクションプランはこれからまだ検討を進めていく段階ですけれども、男女行動計画の一つの重点的な分野といたしまして、中期的な３年程度のスパンである程度具体的なプランを策定していくようになるものではないかと今のところ考えております。","voiceIndex":203,"id":"exchange-087"},{"speaker":"大沢委員","kind":"質問","question":"数字的なもので、すみません、冒頭に言わなければいけなかったんですけども、前年１７０万円余ということで、今回については１,０２９万６,０００円ということになっています。この二つの策定する事由が増えたからということで、増額になったのですかということを一つ伺いたい。","respondent":"吉岡人権啓発課長","answer":"内容といたしましては、男女共同参画の行動計画を策定するに当たりまして、いろいろな諮問をして、ご意見をちょうだいいたしますのは行動計画推進会議ですけれども、その会議を運営して実際に策定をしていくに当たりまして、いろいろなノウハウ、知識。","voiceIndex":205,"id":"exchange-088"},{"speaker":"大沢委員","kind":"質問","question":"わかりました。切り離して考えします。ちょっと時間がないので、今の質問を終わらせていただきます。今度研修費なんですけれども、昨年職員の研修の再構築ということで項目がありました。今年におきましてはございません。今回におきましては、再構築ということですから何らかの新しい構築をされたと思いますが、何か工夫をされた点がありましたら、簡潔でよろしいのでお答えください。","respondent":"榎本人事課長","answer":"昨年は再構築ということで主に若手職員の育成に向けてどういうふうにするのかということを検討してまいりました。","voiceIndex":209,"id":"exchange-089"},{"speaker":"大沢委員","kind":"質問","question":"五つの研修会に分かれて、４３名の職員の方が仕事の合間を縫って勉強されてきたということですけども、この４３名という５分科会ということの数字といいますか、なぜ４３名、五つというのは事業部ということでわかるんですが、４３名の選考というか人選というか、それはどのようにして数字が出てきたのか、すみません、教えてください。","respondent":"榎本人事課長","answer":"昨年は政策課題研修、５分科会という形で、初めてこういう形でやらせていただきました。それまでは大体２グループでやっていたものなんですが、今回は長期計画の検討に合わせて少し今度は事業部ごとの編成でいこうという形になりました。","voiceIndex":211,"id":"exchange-090"},{"speaker":"大沢委員","kind":"質問","question":"それで、この研修会報告書については、後日各家庭に配布をさせていだたきますと。今、「ふれあい」を手元に質問させていただいているんですけれども、これは私たちのほうでも見せていただけるものなのか、それともやはり、行政の方しか見れないものなのか教えてください。","respondent":"榎本人事課長","answer":"今現在報告書は印刷をかけているところですけれども、もちろん職員だけでなく、議会、それから図書館等にも置いて、区民の方が見られるようにしたいと考えています。","voiceIndex":213,"id":"exchange-091"},{"speaker":"大沢委員","kind":"質問・要望","question":"いずれにしても新しい品川区の船出ですので、よろしくお願いをしたいと思いますし、充実した研修、実り多き研修をしていただいて、すばらしい政策を形成していただきたいと思います。これは回数が減ったのか、何かほかに要因があるのか、ご説明いただきたいと思います。","respondent":"中川原広報広聴課長","answer":"昨年、平成１９年度は５回実施いたしました。平成２０年度は３回を予定しているです。","voiceIndex":215,"id":"exchange-092"},{"speaker":"大沢委員","kind":"質問・要望","question":"これは５回と３回ということで２回減ったと、減った理由が、やる必要がないからということで減ったのか、それとも時期的なもので減ったのか、それをご説明していただきたいと思います。","respondent":"中川原広報広聴課長","answer":"タウンミーティングですが、平成１９年度は各地域に区長が出まして、地域にお住まいの方とひざを突き合わせて、その地域の課題を話し合おうと、そういう趣旨で実施したものです。それで、５回です。","voiceIndex":217,"id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"今３回の予定で、大きな会場で、そして多い人数でということでお話しいただきましたけれども、果たしてそれがミーティングという限りは、やはり意思と意思の疎通が必要なのであって、これはあくまでも政策を皆さんに披露する場所であってはいけないと思うんですが、そこのところはどういうふうにお考えになりますでしょうか。","respondent":"中川原広報広聴課長","answer":"いろんな情報を皆さんに、いろいろ提供する場を設け、そして、意見も言っていただける工夫というのを今後準備を重ねる中でやっていきたいと思いますので、ぜひ会場のほうにお越しいただければと思いますので、よろしくお願いいたします。","voiceIndex":219,"id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"１分残したのは、先ほどの結婚サポート事業についてちょっと１点だけ、すみません、簡単に。さまざま地方では、やはりお嫁さんを募集する、引っ張ってくるということでいろんな農家、農村、そしてまた地方の都市で行われているんですが、国、そして都、流れがありますけど、なぜ今結婚サポート事業を品川区が取り入れたのか、すみません、一言、二言で結構ですのでご説明をしていただきたいと思います。","respondent":"鷹倉区民課長","answer":"一言で言えば、結婚したいんだけど、しにくい状況がこの大都会の中にも、あるいは品川区の中にも生まれているのかなと。したがって、その方のための支援を区がしていく必要があるのかなと、このように考えているところです。","voiceIndex":221,"id":"exchange-095"},{"speaker":"井上委員","kind":"確認","question":"私からは、１５６ページの広報費、１６５ページの防災対策費、１６３ページの、これも防災対策費の中の携帯電話・一斉同報システム維持管理費について伺います。質問に入る前に、今の質問に関連して一つだけ確認をさせてください。","respondent":"吉岡人権啓発課長","answer":"それで、検討をお願いしている事項につきましては、先ほど申しましたような第四次の男女共同参画の行動計画に対する基本的な考え方をご検討いただきたいというのが一つ、それからもう一つが、先ほど出ましたワークライフバランスについて。","voiceIndex":224,"id":"exchange-096"},{"speaker":"井上委員","kind":"質問","question":"それで、広報費なんですけれども、今年は広報費の増額ということで広報紙のページ数が増えるということなんですが、これによって区民のメリットはどのようなものがあるのでしょうか。","respondent":"中川原広報広聴課長","answer":"そのページがお互いの地域センター同士の競争といいますか、意識し合ういい刺激になったというお話もありますので、ぜひ区民の方の編集への参加というのも広報でお願いしまして、そのページにつきましては、そういうことで運営をしていきたいというふうに考えてあります。","voiceIndex":226,"id":"exchange-097"},{"speaker":"井上委員","kind":"質問・要望","question":"そこで、ミニガイドが増えたこともそうですが、区の開催をする区の行事、例えば審議会とか推進委員会などの傍聴機会を増やしていくような開催通知を広報の紙面上で求めたいのですけれども、広報広聴課として、いろいろな区が行っている審議会の掲載基準というものは統一したものがあるのでしょうか。","respondent":"中川原広報広聴課長","answer":"現在、広報紙は区の政策とそれからお知らせですね、いろんな行事のお知らせをメインにやっておりまして、それだけでいっぱいになってしまい、文字も小さくなってしまいましたので、まずそこを基本に考えた上で、今のような区民の方にこれから新しい長期計画をつくる中で。","voiceIndex":228,"id":"exchange-098"},{"speaker":"井上委員","kind":"質問・要望","question":"議会のほうでも議会の登庁表示板が新しくなることによって、委員会の開催や本会議の様子が同時上映されるというように、広く市民に知らせていこうということが、品川区として実践できているなというのを思っているんですが、最近、「広報しながわ」に清掃一部事務組合の定例会議の開催日が掲載をされて、傍聴してくださいというお知らせがあって。","respondent":"中川原広報広聴課長","answer":"今、区民の方の声もたくさん届いているとともに、行政内部からもお知らせしなければならない内容をかなり削っているような状況もありますので、そういった広報紙というツールを使ってお知らせする限界というものもありますので、どういう内容を載せていくかというのは。","voiceIndex":230,"id":"exchange-099"},{"speaker":"井上委員","kind":"質問・要望","question":"やっぱり区報の役割というものがあると思いますから、その辺は区民の声も真摯に受けとめてぜひ検討を続けていただきたいと思います。ホームページやケーブルテレビを見る方の割合をどのぐらいと推定されているのかということと、また、プレス発表資料をどこに配布をして、どういうふうな活用をされているのか教えてください。","respondent":"中川原広報広聴課長","answer":"プレス発表の資料ですが、あれはあくまで今年度の予算の資料としてプレス発表用につくったものですので、マスコミの方々に配布をいたしました。とともに、議員の方々にもお配りしたところです。区政資料コーナーに設置いたしまして、閲覧しています。","voiceIndex":232,"id":"exchange-100"},{"speaker":"井上委員","kind":"提案","question":"私は本当だったら、マスコミにプレスの資料として立派なものをつくるよりも、一番当事者である区民にこそ知らせてほしいなというふうに思っているので、このプレスをどうにか有効に使っていただきたいということが１点と、ホームページで区民からの重点施策を区長がお話になったことについて意見を求めるということですが。","respondent":"中川原広報広聴課長","answer":"プレス発表資料ですが、あれにつきましては、そのほかの団体への予算の説明の資料として使わせていただいております。予算の記事につきましては、各区さまざまな時期に広報紙としてお知らせしております。","voiceIndex":234,"id":"exchange-101"},{"speaker":"井上委員","kind":"質問・要望","question":"ぜひ、何らかの形で、報道機関に先ではなく、当事者の区民に知らせるということを、少し発想の転換をしていただきたいなということは要望させていただきたいと思います。次に、１６５ページの防災対策費の中学校消火ポンプについてお伺いをいたします。この消火ポンプは、災害時に中学生が操作をするということを想定しているのでしょうか。","respondent":"久保田防災課長","answer":"ただ、それだけではせっかくの配備ですので、中学生の皆さんが、やはりそれを見て、自分でもちょっと扱ってみようかなという気運が起こってくれば、既に荏原第四中学校なんかでは、この消火ポンプを使った地区防災訓練に参加しているような、そういうような状況もありますので。","voiceIndex":236,"id":"exchange-102"},{"speaker":"井上委員","kind":"質問","question":"事業所の消防力の強化というところでまずは区ができるところはそういう公共施設なのかなということで配置をされるんだと思うんですけれども、今火災の減災というところで、学校が火災現場になるというのは、一般的に言えば、火の使われているところが少ないというようなところも含めてお伺いをするんですが、災害時の初期消火といえば、素人考えではありますけれども、だれでも操作できる点では。","respondent":"久保田防災課長","answer":"周辺でそういう火災が起きたときには、初期消火としてできる範囲の中で、可能な範囲の中でそういう区民の消火隊と一緒にやっていただければいいかなというふうに考えております。","voiceIndex":238,"id":"exchange-103"},{"speaker":"井上委員","kind":"質問・要望","question":"子どもたちが参加しているし、八潮でもそんなふうな風景を見させていただいていますけれども、そちらをぜひ強力に推し進めていただきたいと思いますが、いかがでしょうか。","respondent":"久保田防災課長","answer":"今お話に出ていたように、荏原第四中学校をはじめ、八潮の学校は地区訓練に参加して、みずからそういう形での参加をしております。学校も地域の一員です。まさしくそういう点では、学校と地域が一体となって防災を強化していく、こういうことがやっぱり大事だと考えています。","voiceIndex":240,"id":"exchange-104"},{"speaker":"井上委員","kind":"提案","question":"時間がないので、ちょっと質問を変更させていただいて、以前に生活者ネットワークでも提案をしていました学校に避難をされる町会の方たちの教室エリアだとか、その地域の表示をするプレートをぜひ設置していただきたいということで、ふだんから学校に行ったときに、そういった意識を持っていくというのを提案させていただいたんですが、すべての学校にそのようなプレートは設置されていますでしょうか。","respondent":"久保田防災課長","answer":"学校に避難町会のプレートですけども、学校に２カ所、このプレートを表示しております。玄関を入りますと、玄関の大体横に、ここの避難所の該当町会は何々町会ですというのを表示されてあります。","voiceIndex":242,"id":"exchange-105"},{"speaker":"若林委員","kind":"質問・要望","question":"１５３ページ、歩行喫煙防止推進経費、１５９ページ、ホームページ等運用経費、それから１６０ページの企画調査費、３点１０分間でお願いいたします。そこの違い。昨年からの予算増の根拠。もう一つ、業者選定をどのようにされているのかというのも教えていただきたいと思います。今後のこの行政評価をどのようにされていくのか、また、今までの評価も含めまして、お答えをいただきたいというふうに思います。","respondent":"高濱生活安全担当課長、中川原広報広聴課長、堀越行財政改革担当課長","answer":"キャンペーンにつきましては、平成１９年度につきましても、１１月中にマナーアップキャンペーンを各駅、今回は四つの駅で実施しております。ホームページ等経費についての増分の説明です。先ほど運用経費については申し上げました。今後につきましては、どのような形、例えば新しい視点ですね、民間との役割分担ですとか、そういった部分も含めまして。","voiceIndex":246,"id":"exchange-106"},{"speaker":"若林委員","kind":"質問","question":"一つ、ぜひ大幅な予算増、これを認めてほしいですので、課長のおっしゃった部分、特にまた検索機能につきましては、私も一般質問等で言わせていただいておりますけれども、昨日も試しに、例えば「介護」という言葉で検索をしますと、ご存じのとおりＰＤＦの欄がずっと並んで、文京区はまた別な大変使いやすいいい検索機能もついておりましたし、ぜひ使う人の身になって。","respondent":"高濱生活安全担当課長、中川原広報広聴課長","answer":"指導員と区と業者との連携ですが、指導員を選定いたしまして、まず最初に４月に私のほうで赴きまして、いろんな指導の方法についての打合せ、またいろんなお願いをいたします。ホームページにつきましては、今までスピードと情報量については何とかここまで来たんですけれども、ご指摘の検索機能がやはりホームページの一応身上というところがありますので。","voiceIndex":250,"id":"exchange-107"},{"speaker":"若林委員","kind":"質問","question":"そうしますと、歩行喫煙のほうの指導員の方は、各駅からこの大井町の区役所の生活安全担当まで来るという意味ですか。","respondent":"高濱生活安全担当課長","answer":"すみません、多少語弊がありました。大井町のエリアを担当している方に関しては毎日指導しているです。ほかの箇所に関しましても、これからも一層指導を強めてまいりたいと考えております。","voiceIndex":253,"id":"exchange-108"},{"speaker":"高橋委員","kind":"質問","question":"１４５ページの危機管理室経費、１４９ページの奨学金貸付事業と、１５７ページの広報関係についてお尋ねします。１４５ページ、私が危機管理だと思っただけなんで、もし款が違ったら、すみません、ご指摘ください。内部通報者制度というのが他の自治体ではあるんですが、品川区の中ではそれがあるんでしょうか。もしないとすれば、導入の検討をされていらっしゃるでしょうか。よろしくお願いします。","respondent":"桑村総務課長","answer":"これは区の中では私どもですといわゆる人事課中心の検討するところ、もう一つは弁護士事務所ですとかマスコミですとか、そういったところへの通報という制度があります。","voiceIndex":257,"id":"exchange-109"},{"speaker":"高橋委員","kind":"質問・要望","question":"１４９ページの奨学金の貸付事業のところで、債権回収業務委託が計上されているんですが、具体的にご説明いただきたいと思います。","respondent":"鷹倉区民課長","answer":"その方について、具体的にはシルバー人材センターなんですけれども、やはり人との接触がすごく上手な方々、そういう人材を活用させていただきまして、対面でお話しさせていただきながら、回収をする、そういう事業を委託しているものです。","voiceIndex":259,"id":"exchange-110"},{"speaker":"高橋委員","kind":"質問","question":"その際、いろいろプライバシーの問題等ありますけども、そのシルバー人材センターの方と契約する際に、どのような配慮というか、注意をされて契約されているでしょうか。","respondent":"鷹倉区民課長","answer":"当然個人情報が絡むわけですから、その辺のところのしばりが当然かかってあります。それとやはり、お宅に訪問していろいろお話しされるわけですから、隣近所にできるだけわからないような形で、十分個人のプライバシーに注意しながらやるように指導しています。","voiceIndex":261,"id":"exchange-111"},{"speaker":"高橋委員","kind":"意見","question":"１５７ページの広報関係のところなんですが、広報経費のところで、「広報しながわ」、先ほどからお話が出ているんですが、８ページに増ページされて、内容も充実されるということなんですが、以前にもお話があったかもしれませんが、どのような配布方法で、区の世帯数のうちのどれぐらいのパーセンテージに配布されているのか、その配布の費用、この金額はいろんなものが含まれていると思うんですが。","respondent":"中川原広報広聴課長","answer":"そのほかは地域センター、図書館、文化センターなど、各公共施設で配布をさせていただいているところです。新聞折り込みの経費ですが、平成２０年度の予算では、３,３９０万円を計上させていただいているところです。","voiceIndex":263,"id":"exchange-112"},{"speaker":"高橋委員","kind":"質問","question":"「広報しながわ」を充実させるということと、あと新聞を配達してもらわないで駅で買ったりする世帯も増えているということですので、それに対応するために、例えばコンビニに置いてもらうとか、あるいは区議会だよりなどは、たしかシルバー人材センターの方が全戸に配布されているんではないかと思うんですが、例えば区議会だよりのような形でやった場合、予算的には相当厳しいのでしょうか。","respondent":"中川原広報広聴課長","answer":"ということもありまして、シルバー人材センターをはじめ、いろんな配布業者に問い合わせをしましたが、どうしてもどこをとりましても、事業所に広報紙を届けてから１週間ぐらいは時間をもらわないとこの部数は配布しきれないということがございまして、やはり、こういった方法。","voiceIndex":265,"id":"exchange-113"},{"speaker":"高橋委員","kind":"質問","question":"それはなぜかというと、七福神めぐりなどは、区外の方もたくさん見えますし、品川区にいろんなところから人が訪れたり、あるいは東京に来ている外国人、観光客などが来れるように区外にそういったガイドマップなどを置かれているんでしょうか。もし、置かれていないんでしたら、どこかに置こうという考えはおありでしょうか。お願いします。","respondent":"中川原広報広聴課長","answer":"観光客とか区外からお見えになる方のためには、観光協会と連携しまして、そういったたぐいのマップをつくる、そういったときに広報は情報提供を協力したり、編集とかも手伝ったりという形で、観光客用には別途いろいろな手段でマップ等々配布をしています。","voiceIndex":267,"id":"exchange-114"},{"speaker":"高橋委員","kind":"質問","question":"それは区外にも置かれているということでしょうか。","respondent":"中川原広報広聴課長","answer":"区外といいますと、特別区の区政資料コーナーとか、やはり、インターネットとかでプリントアウトできるような形にしたりとか、置く場所はなかなか限られてしまいますので、お手元に届きやすいような方法を工夫しています。","voiceIndex":269,"id":"exchange-115"},{"speaker":"高橋委員","kind":"質問","question":"イメージアップ経費のところで、イメージアップのところかちょっとわからないんですが、先ほどちょっと職員の方のお話が出たんですが、職員の方で顔写真入りの名札と、そうでないのをつけていらっしゃる方がいるんですが、私すみません、勉強不足でわからないんですが、その違いというか、全員がそうされていない何か理由があるんでしょうか、すみません。","respondent":"榎本人事課長","answer":"今現在、基本の名札は小さい氏名札という形で決めております。それを今ちょうど職員証をリニューアルする段階に来ましたので、顔写真つきの首からつり下げる方向に統一しようとする形で今準備作業を進めているところです。","voiceIndex":271,"id":"exchange-116"},{"speaker":"本多委員","kind":"質問・要望","question":"やはり、日本人なら国歌を歌うとか、学校なら校歌を歌うとか、自民党でしたら党歌を歌えるとか、そういう何かすごいなと本当に思いまして、その辺が自主的な取り組みなのか、その辺をちょっと教えていただきたいと思うんですけども、あと平成１９年度の成人式の参加率ですとか、あと平成２０年度のこの予算の見込みですとか、平成２０年度というと、ちょうど昭和の最後の年に出生をされた方たち。","respondent":"桑村総務課長","answer":"今後ですが、正直いいまして、若干ずつは下がっていくのが実情です。来年度は一応予算上は３,０００人規模を予定していますが、２,７００人台になるだろうなというふうに思っております。そういう意味では、少しずつ人数が減っていくのが今のところ実情です。","voiceIndex":275,"id":"exchange-117"},{"speaker":"本多委員","kind":"質問・要望","question":"行政と取り組むものに参加するというのは、やっぱり成人式が一番参加率が高いんでしょうか。ほかの取り組みでもっと参加とか、その辺、どういうふうにとらえているのか。例えば、その一つで、区民アナウンサーですとか、いろんなそういう区政参画に携わっていただきたいなとちょっと思ったんですけど、その辺だけ簡単に教えてください。","respondent":"桑村総務課長","answer":"どのような参加率かというのはちょっと私もとらえてございませんけども、せっかく来ていただいた実行委員の方が、この後区政の中でいろんなことをやっていただくのは望んでいるところでございまして、今年の基本構想等の策定委員会の中でも、いわゆる成人というか。","voiceIndex":277,"id":"exchange-118"},{"speaker":"本多委員","kind":"質問・要望","question":"１９６８年にカネミ油症というんでしょうか、皮膚のいろんな被害等がありまして、ＰＣＢの廃棄物を保有する場所の囲いを設けるですとか、その扱いについてはいろいろと法的にも整備がありまして、その収集運搬などの許可とか、取得などの確認ですとか、保管するなら仮囲いするというようなことになっているんですけど、そういう確認作業というんでしょうか、その辺を教えていただきたいと思います。","respondent":"宍戸施設担当課長","answer":"高濃度ＰＣＢの廃棄物処理委託に関してです。区では、廃棄物処理法のしばりにより、廃棄処分できないＰＣＢ、高圧コンデンサーあるいは蛍光灯安定器を多数持っております。数ですけれども、高圧コンデンサーが６１台、それから安定器につきましては、２,０８９個ぐらいあります。","voiceIndex":279,"id":"exchange-119"},{"speaker":"本多委員","kind":"質問・要望","question":"そういう処理をされていただくんですけれども、処理、何年ぐらいあとかかっていくのか、２０１６年を期限とする処分が義務づけられているんですけれども、品川区内の処理の計画といいますか、その辺を改めて教えていただきたいのと、あと各自治体でやるということだと思うんですが、広域的な確認とかは特にないんでしょうか。","respondent":"宍戸施設担当課長","answer":"ところが、中央防波堤にできた処理工場なんですが、なかなか安定的に操業できない状況にございまして、今蛍光灯の安定器の中でも、樹脂型というものは受け入れているんですけれども、アスファルト型はちょっと受け入れができないというふうな事情もございまして。","voiceIndex":281,"id":"exchange-120"},{"speaker":"南委員","kind":"質問・要望","question":"１６１ページの新基本構想・長期基本計画策定経費、この問題で伺いたいと思います。総括については、どのような内容か、かいつまんで教えていただきたいと思います。","respondent":"福島長期計画担当課長","answer":"基本構想の過去２回の総括ですが、今回の基本構想の改定に当たりましては、基本構想等策定委員会に諮問いたしまして検討していただきました。","voiceIndex":286,"id":"exchange-121"},{"speaker":"南委員","kind":"質問","question":"私はその策定委員の方々にお示しをした資料、そしてその資料を品川区としてどのように認識されたのかというその中身、総括は策定委員会にしていただいたというお話なんですが、区としての認識を伺いたいと思って聞きました。","respondent":"福島長期計画担当課長","answer":"過去２回の基本構想ですけれども、それにのっとりまして基本計画をつくり、また実施計画をつくり、着実に区政を運営してきたというふうに総括しております。","voiceIndex":288,"id":"exchange-122"},{"speaker":"南委員","kind":"質問・要望","question":"総括したことは承知しているんですけれども、中身についてどのようにこれから１０年、２０年先の区政運営をするに当たって、今とりわけ何が必要なのか、そして、どういう区民のニーズがあって、今の区政の現状がどこまで到達してどうなのかという、そこのあたりを、具体的な中身を教えていただきたいというふうに申し上げたんですけど。","respondent":"福島長期計画担当課長","answer":"これから先、１０年先、２０年先の具体的な中身ですけれども、今回お示ししております基本構想、その中に基本方針という形で示しているものです。","voiceIndex":290,"id":"exchange-123"},{"speaker":"南委員","kind":"質問","question":"その辺の認識についてひとつ伺いたいと。そして、同時に、自治体のあり方として、住民の命と暮らしを守ることを最優先にするべきだ、こういうふうに思うわけです。この点の認識についても伺いたいと思います。","respondent":"福島長期計画担当課長","answer":"都市像の中では、第２の都市像の中で、平和で人権を尊重される社会を目指しますという都市像の実現に向けて、そういう形で基本方針を載せているものです。","voiceIndex":292,"id":"exchange-124"},{"speaker":"南委員","kind":"質問","question":"これから計画しつつあるものについては、かなり丁寧に説明をいただけましたけれども、今までのものについての説明はほとんどされませんでした。私は総括が十分ではないんじゃないかというふうに思わざるを得ません。そういう上にのっとって新たな構想をつくるべきだ。改めて総括について、どういうふうにとらえておられるのか、そこをもう一回伺います。","respondent":"福田企画部長","answer":"したがいまして、長期基本計画の検討に際して、現在の長期基本計画について、どこまでを総括というかという問題はあるかもしれませんけれども、振り返ってみると、このように考えております。","voiceIndex":294,"id":"exchange-125"},{"speaker":"南委員","kind":"質問","question":"何回聞いても具体的な、どういうふうに総括をしたということの具体的な提示はありませんでした。残念。どうしてこれが説明いただけないんでしょうか。大まかな中身について説明してくれと３回言いましたけど、全然されません。じゃあ、総括はしなかったんですか。なかったんですか、ちょっとそこを改めてもう一回聞いて、あるんであれば、中身をちゃんと教えてください。","respondent":"福島長期計画担当課長","answer":"最初に答弁したときに、第三次長期基本計画について総括の資料を策定委員会の皆様にお示しし、また、説明し、その中で議論いただいたということを説明したと思いますが。","voiceIndex":296,"id":"exchange-126"},{"speaker":"南委員","kind":"質問・要望","question":"ちょっと本当にもったいない、８分経過しましたので、きちんと中身について教えていただきたいというふうに思うんです。どこのどういうものを指すのかをちょっと説明していただきたいと思います。置いていかれるだけになってしまっているんじゃないかという危惧を私はするんですけども、この点について、どういうふうに区としての見解を持っておられるのか、その辺についてちょっと伺いたいと思います。","respondent":"福島長期計画担当課長","answer":"その内容につきましては、こちら第三次長期基本計画の「都市像」、あわせまして、「活力にあふれた個性あるまち」から始まりまして、「最後の計画の実現に向けて」まで、全１５ページにわたる内容ですので、それについて策定委員会ではご説明申し上げたものです。","voiceIndex":298,"id":"exchange-127"},{"speaker":"南委員","kind":"質問","question":"区がどういうふうな立場で区政運営をしていきたいというふうに考えているのか、そこが全く今の説明では見えません。しかし、これは区の一定の見解も全く入っていないんでしょうか。なぜ今回の基本構想の前文にはそこがないのか、どうしても、どこで聞いても、そこに対する明確な理解でき得る回答がされていないんですよね。改めて私はこの場で伺いたいと思います。きちんとわかるように答弁してください。","respondent":"福島長期計画担当課長","answer":"先ほど言いましたように、６ページにあります「都市像の実現に向けて」ということで、最後ですけれども、「平和で人権が尊重される社会を目指します」という形で明確に基本方針を述べているところです。","voiceIndex":300,"id":"exchange-128"},{"speaker":"南委員","kind":"質問","question":"不十分です。私は初めて新しく区長に就任された濱野区長が、一番最初に手がけるこの基本構想は、きちんとした格調高い理念がしっかり区民に伝わる、そういう内容であってほしいというふうに思うんです。したがって、ぜひとも今までずっと１期目と２期目に盛り込まれていたこういう精神は、しっかり叙述をするべきだというふうに思いますので、ちょっと区長の見解を伺いたいと思います。","respondent":"福島長期計画担当課長","answer":"繰り返しになりますけれども、こちらにきちっと記述をしていますし、また前２回の基本的な理念ですとか、そういったものは継承しているものでありますし、区民の福祉向上に全力を挙げていくという基本姿勢は変わらないものであるというふうに考えております。","voiceIndex":302,"id":"exchange-129"},{"speaker":"南委員","kind":"質問・要望","question":"私は極めて残念だというふうに言わなければいけないと思います。そういう点で、答弁を求めてもしない。これから議員も参加した長期基本計画の策定作業に入っていきますけれども、そういう場面で、やっぱり広くさまざまな声を聴取して、そして真摯な姿勢でやっぱり計画づくりに当たっていただき、いろいろな意見を聞いて盛り込んでいただく、そういう姿勢を改めて求めたいというふう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":304,"id":"exchange-130"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それと、１６１ページ、ボランティア・ＮＰＯ等との協働のしくみづくりについてお伺いします。それとあとは、区役所内に職員、若い職員も多くいると思うのですが、その職員に対してさまざまなアンケートをして、今なぜ若い人たちが結婚をしないのかというのを身近な人たちから情報を得るというのも一つの案だと思いますので、その辺の内容をもし検討されていたら教えてください。","respondent":"鷹倉区民課長","answer":"職員に対する部分、これは私どもイントラネットでアンケートをとれるような形になってありますので、職員にどういう形にすればこういうものに参加しやすいか、ぜひアンケート等もとっていきたいなと、このように考えているところです。","voiceIndex":306,"id":"exchange-131"},{"speaker":"石田（慎）委員","kind":"質問","question":"先ほどマスコミ等というお話がありましたが、実際プレス発表後の反応というか、もし幾つか例があったら教えていただければと思います。","respondent":"鷹倉区民課長","answer":"一番反響が大きかったのが、そのＮＨＫ、これをご覧になった方が区民だけじゃなくて、周辺部分も含めていろんな方から電話がかかってきております。仕事が手につかないぐらいに、これも仕事なんですが、かかってきております。","voiceIndex":308,"id":"exchange-132"},{"speaker":"石田（慎）委員","kind":"質問","question":"例えば、まず問い合わせももちろんマスコミがあった中で、ほかに例えば区民等がどのようなことをやるのか、例えば若い人が実際にこの事業について概要を聞きたいとか、そういった区民からとか区外でも構いませんが、そういった内容を少し教えていただければと思います。","respondent":"鷹倉区民課長","answer":"これはシルバーの男性のほうから、いつから申し込めるんでしょうかと、こういうような話が結構多いという状況です。","voiceIndex":310,"id":"exchange-133"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"それともう一つ、これも要望になってしまうかもしれないんですが、ぜひ例えばひとり親家庭の方とか、そういった方たちの、もともと登録料を安くするという中で、できたら無料化とか、やはり子どもを持っている親というのは、なかなかそれこそ本当に出会いがない。子どもにつきっきりで、なかなか出会いがない中で、ぜひその辺をご検討していただければと思うのですが、ご見解をよろしくお願いします。","respondent":"鷹倉区民課長","answer":"まだ、新しい事業で、これから立ち上げていくですので、議会も含めていろんな方のご意見をお聞きしながら育てていきたい事業と考えています。","voiceIndex":312,"id":"exchange-134"},{"speaker":"石田（慎）委員","kind":"質問・要望","question":"時間がなくなってしまったので、要望というかですね。ＮＰＯとボランティア、さまざまなボランティア活動があると思うんですが、今なかなか活動してくださる方がいなくなってくる中で、しっかりと区としても側面からバックアップ、例えば保険制度をしっかりするとか、そういったことをぜひとも取り組んでいただければと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":316,"id":"exchange-135"},{"speaker":"西本委員","kind":"質問","question":"１５３ページの地域振興事業、１６７ページの備蓄物資管理、それから１７１ページの原小学校の跡地利用について、それぞれお聞きします。それから、備蓄物資ですが、これは一般質問等々でも質問していますけれども、食物アレルギーの対応ですね、備蓄するということで検討は進んでいるのかお聞きしたいと思います。","respondent":"中山地域活動課長、久保田防災課長","answer":"この地域振興事業のところで、団塊の世代を含めた人材育成のご質問がありましたけれども、もちろん地域のコミュニティづくりですから、そういう側面もあるわけですが、ここの部分はどちらかというと従来は町会。備蓄物資の中でのアレルギーの対応ですけども、これも一般質問でご答弁したところですけれども、アレルギー対応は非常に難しい面があります。","voiceIndex":318,"id":"exchange-136"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、こういうシルバー大学の卒業生であるとか、町会等々とかとリンクできるような仕組みづくりをやはりきちっとつくっていけないものかなというふうに思っております。それの考え方をお知らせください。少なくともすぐやっていただきたいのは、ミルクです。それから関連して、防じんマスクとか、防ダニシーツ、これらはこの備蓄の物資の中に入っているんだろうかということでお聞きしたいと思います。","respondent":"堀越行財政改革担当課長、中山地域活動課長、久保田防災課長","answer":"それで、そちらの部分と、それからほかの団体との、ＮＰＯとのネットワークとか、そういったことも視野に入れまして。それをさらに発展させて、今おっしゃったようなさらにコミュニティビジネス的な自主事業になるかどうかというのは、今後の推移。防じんマスク、ちょっとその後が聞こえなかったので恐縮なんですが、おそらく火災なり何なりしたときの対応ということだとは思うんですけども。","voiceIndex":321,"id":"exchange-137"},{"speaker":"西本委員","kind":"質問・要望","question":"ですから、そのアレルギーを持っている子どもたちのために、その対応のミルクがありますから、ちょっと高目です、しかしながら。それはちゃんと備蓄していただきたいというふうに思っております。ですから、アレルギーの対応については、児童保健事業部であるとか、いろいろなところで知識を豊富に持っていますので、そこのところの連携も図りながら、いろいろ勉強していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":325,"id":"exchange-138"},{"speaker":"山路委員","kind":"質問","question":"私のほうからは、１４９ページ、庁舎整備費について、１５７ページ、航空写真撮影についてお伺いをいたします。航空写真撮影ですが、予算書には約７９万８,０００円計上してありますが、隔年撮影されるという説明が先ほどございましたが、撮影した後、どういう使用をされるのかお伺いをいたします。","respondent":"中川原広報広聴課長","answer":"これは２００５年に出しました写真集「まちの鼓動」の中にも、そういったまちの変貌をおさめて区民の方にご紹介したり、今度、「Ｗｅｂ写真館」で先ほどインターネットの充実経費の中にあるんですが。","voiceIndex":327,"id":"exchange-139"},{"speaker":"山路委員","kind":"提案","question":"昨日も確認をしてきたんですけど、区民が本庁舎を訪れられて空から見た品川区、どこに学校があるか、どこに駅があるか、またどこに品川区役所があるかを知るということは非常に大事だと思うんですね。それと、設置場所、防災センターの横のほうに置いてありましたが、区民により見やすい、こういうふうに今度の写真を生かされたらどうかと提案いたしますが、どのようにお考えでしょうか。","respondent":"久保田防災課長","answer":"公共施設等も一部変更にはなっているんですけれども、あれは３階の防災器具を撤去するときに、やっぱり一緒に古いから撤去しようかと、こういう考えもあったんです。","voiceIndex":329,"id":"exchange-140"},{"speaker":"山路委員","kind":"質問・要望","question":"池の部分は、黒い泡がいつもたまっていたので心配していたんですけど、今日は早速行動に移られて、水を抜いて、これから掃除しようというところまで気をつけていただいていることは非常にうれしく思うわけですが、全体的に総合デザインというものを、品川区の顔でもありますし、これから初めて日曜日に品川区を訪れる方が。","respondent":"中島経理課長","answer":"今後古い庁舎ではありますけれども、これから例えば総合庁舎の耐震化工事等もありますので、その中でもっときれいなことができるようなことも含めて検討させていただきたいというふうに考えてあります。","voiceIndex":331,"id":"exchange-141"},{"speaker":"山路委員","kind":"質問","question":"周りの部分は掃除をされていると思うんですが、果たして中のほうは掃除をされているかなという、昨日も３階、５階、本庁舎を見てきまして、議会棟の５階、午前中は女性トイレを我が党の金野委員がお願いしましたが、私も男性用の便器の中の清掃が非常に気になりますので、どのようにされているかお考えをお伺いいたします。","respondent":"中島経理課長","answer":"やはり、トイレの便器につきまして、これも毎日時間を決めて各フロアの清掃をしてございまして、使うときに不快な思いをしたりとか、不潔感がないような形で清掃するように業者には指導しています。","voiceIndex":333,"id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"私は１４５ページ、危機管理室経費、１５３ページ、生活安全推進費、１６３ページ、防災体制整備費、ちょっと関連した話なんで、危機管理室長にお聞きしたいと思います。品川区内で突発的事故や事件が発生したとき、犯罪、水害、地震、前に崖崩れがあったようなことを記憶しておりますが、火災や疾病や大きな事故が起きたとき、一般職員から管理職にはどのように連絡されてくるのでしょうか。","respondent":"桑村危機管理室長","answer":"先ほどもほかの委員の方にご説明申し上げましたけど、基本的に危機管理は、日常の業務の中でこなすというのがまず基本です。そういう意味では、例えば水害等でしたら防災課、まちづくり事業部を中心に、基本的なそこの部隊が連絡網を持ってあります。","voiceIndex":336,"id":"exchange-143"},{"speaker":"須貝委員","kind":"質問","question":"昨今国のほうで、今回海難事故で、防衛省の通報体制が本当に問題になったと思いますが、緊急事態が発生したとき、品川区では管理職、あと緊急事態、ちょっと大きな事故の場合として想定していただいてもいいんですが、副区長、そして区長までにその内容が伝わるまで、どのぐらいの時間がかかるんでしょうか。その双方をちょっと教えてください。","respondent":"桑村危機管理室長","answer":"ですので、そこの情報をとったところが、例えば職員が対応した場合に、基本的にはそこの管理職にまず電話するんでしょうけれども、それと同時に、危機管理室長、あるいは職員からなかなか判断がきかないかもしれませんけれども。","voiceIndex":338,"id":"exchange-144"},{"speaker":"須貝委員","kind":"質問","question":"そうすると、今電話でというお話だったんですが、先ほどもちょっとほかの委員が別のところでお話ししていましたが、区が関係者や関係機関から連絡を受けたときに、一斉に連絡する、緊急情報発信システムというのは、何か構築されているということではないんでしょうか。","respondent":"桑村危機管理室長","answer":"ただ、先ほど例えば警察等の情報でしたら、そこのところの部署と、それから私どもと、それから今ですと広報というような形で決めていますけれども、三つのところがまずそこに集まってくるということで基本的に判断して、そこから流し方を決めようということはありますので。","voiceIndex":340,"id":"exchange-145"},{"speaker":"須貝委員","kind":"質問","question":"ちょっと我々なんか議員であるということで、まちの中を歩いているときに質問されることがあるんですね。そうすると、「これ、何なんですか。事件なんですか、事故なんですか」と聞かれたときに、お答えがしようがない。何かそういう情報をやはりちょっと区民、我々区民の代表として動いているわけですが、知らせてもらえるようなシステムは構築できないかどうか、ちょっとそれだけお聞かせください。","respondent":"桑村危機管理室長","answer":"その意味では、そういう必要な部署へメール等の配信というのは考えるわけですけども、そのときに対応するというときに、正直言って情報の流し方というところまで果たして私どもうまくいけるかどうか、なかなか難しい問題だと思いますので検討させていただきたいと思います。","voiceIndex":342,"id":"exchange-146"},{"speaker":"須貝委員","kind":"質問","question":"ぜひ、この間もちょっと上空を旋回していたら、火事が旗の台のほうであったということで行ってまいりましたが、ぜひ何とかいい方向で、瞬時にわかるようにお願いしたいと思います。公園には水洗トイレがあります。でも、もし、近くにそういう使用できるトイレがあればあるで、また大勢の区民の方が助かる、ストレスも解消されるということも考えられると思うんですが、その辺、ご見解をお聞かせください。","respondent":"久保田防災課長","answer":"新潟・中越でもそうでした。避難所の数が１００以上にもなって対応できないということがあるので、今はやはり学校を基本に避難所はやっていただきたいと、こういうことです。","voiceIndex":344,"id":"exchange-147"},{"speaker":"松澤委員","kind":"質問","question":"１５３ページ、町会・自治会館等葬祭設備補助に関連して１点と、同じく１５３ページ、生活安全推進事業に関連して１点。３月１日から３月７日まで、明日まで火災予防運動なんですね。新聞報道等によりますと、荒川区なんかは全家庭につける、助成するなんていう話もありますけれども、品川区は火災警報器の助成について、どのような考えを持っておられるんでしょうか。","respondent":"久保田防災課長","answer":"現在これは東京都の火災予防条例でこれはそういうふうに義務づけになっているんですけれども、品川区の対応としては、消防署とまずは一緒に連携して、やはり各家庭に対するＰＲ、あるいは普及啓発を果たしていこうということで、いろんな場でこれはＰＲ活動をしております。","voiceIndex":347,"id":"exchange-148"},{"speaker":"松澤委員","kind":"質問","question":"今これは大変進歩しまして、壁掛け、今までは上につけなくちゃいけないなんて言っていたんだけど、壁掛けができるようになったんですね。それで、町会に行きますと、やはり会館につけたいんだけど、部屋数が多いので何とか助成してくれないかなという声が大きいんですね。そのような意味では、これを改正して、町会会館で助成できるような形がとれないものでしょうか、この点についてお伺いしたいと思います。","respondent":"中山地域活動課長","answer":"全体の制度としてやる場合には、ちょっとこれはまた町会会館数は相当ありますから、予算も含めて、これはまた別途検討の余地があるかと思いますが、新たな工事に際して出てくるような場合については柔軟な運用は可能かと考えております。","voiceIndex":349,"id":"exchange-149"},{"speaker":"松澤委員","kind":"質問","question":"生活安全推進事業に関連してですけど、防犯カメラというのは、品川区でも平成１７年から助成をしていますけれども、当時防犯カメラを設置するということについては、肖像権とか、あるいはプライバシーの問題とかで反対意見が相当あったんですけども、近年何ですか、判例があったとか何とかで、大分声が弱まってきたように感じているんですけど、その辺についてちょっとご見解を伺いたいと思います。","respondent":"高濱生活安全担当課長","answer":"防犯カメラに関する判例ということですが、これは平成６年に大阪のほうで、公共の場にいる人については、プライバシーは極めて制限されたものになる。","voiceIndex":351,"id":"exchange-150"},{"speaker":"松澤委員","kind":"質問","question":"そうすると、大体団体ですから１０カ所とか、ちょっとそのぐらいつけるのかなというふうに思うんですけど、予算をつけるのは可能なんですね、みんなで頑張ろうということになれば。ただ、毎年ランニングコストがかかるんですよね。","respondent":"高濱生活安全担当課長","answer":"今後ともそういう面での働きかけ、また何とかそういう面で出していけないかということを検討させていただきたいと思います。","voiceIndex":353,"id":"exchange-151"},{"speaker":"松澤委員","kind":"意見","question":"現在申請中を含めても４団体、ランニングコスト、１年間で半額助成で２０万円ですよね。１年間で２０万円。そうしたら、東京都に出せじゃなくて、区で独自で半額助成したっておかしくないと思うのね。やはり、防犯の面からしたら、これは独自に考えるべきだと思いますので、その辺、ちょっとお考えをお聞かせください。","respondent":"高濱生活安全担当課長","answer":"非常に大切なことと思いまして、できればと思います。私の立場で言えることかどうかちょっとわからないんですけれども、ぜひ何とかしていけないかということを区の中でもいろいろご相談させていただきたいと考えております。","voiceIndex":355,"id":"exchange-152"},{"speaker":"松澤委員","kind":"質問・要望","question":"応援してまいりますので頑張っていただきたいと思います。時間がないので３点目。１６３ページの医療救護体制の整備および救護所の設置について。この予算の内容をちょっと手短にお聞かせいただきたいと思います。","respondent":"久保田防災課長","answer":"これは一つは薬品のランニングストックということで、薬剤師会に薬品を委託で保管していただいていますので、その経費が主なものです。","voiceIndex":357,"id":"exchange-153"},{"speaker":"松澤委員","kind":"質問","question":"いろいろ薬品の整備あるいは災害のときに応急救護所をつくる。いろいろ絵にかいてこういうふうにしたい、計画というのはできますけれども、やはりそれを運用する努力、運用する団体がうまく話し合いができないとうまくいかないと思うので、その辺、しっかりと連携できるような決意というんですかね、時間がないのでお聞きしたいと思います。","respondent":"久保田防災課長","answer":"今年度その辺の関係する医療関係者を集めて連絡会議を開いていきたいと考えております。","voiceIndex":359,"id":"exchange-154"},{"speaker":"川西委員","kind":"質問・要望","question":"１番目の職員研修ですが、午前中から午後にかけても出ていましたので、ここで伺いたいのは、特別区の新任研修ではなくて、品川区独自の研修の内容について、もし平成２０年度具体的にどういう項目の、区の施策の説明とかいろいろ、さっきちょっとおっしゃっていましたが、具体的にわかったら挙げていただきたいと思います。","respondent":"榎本人事課長","answer":"区のほうの新任研修の具体的メニューですけれども、大体３日間ぐらいをメニューで、事務・技術系、それから保育士・看護師系と分けて、医療系・技術系、分けてやっているところです。","voiceIndex":362,"id":"exchange-155"},{"speaker":"川西委員","kind":"質問・要望","question":"そういう品川区の行政のあり方、それからもう一つは、例えば私一般質問でいたしましたけど、今の社会的情勢の中で、地球環境ＣＯ２問題で、品川区の取り組みについて、どのように取り組んでいくかという具体的なことを若い方々に教えていかなくちゃならない。このテーマに私が今取り上げました何点かのことを具体的に提起して、研究のテーマにしていだたくというような今後の方向性を伺いたいと思います。","respondent":"榎本人事課長","answer":"それで、食育、健康の部分ですけれども、今現在はちょっと食育関係は研修のメニューでは入っておりませんけれども、健康管理とあわせて今後検討していきたいと思います。","voiceIndex":364,"id":"exchange-156"},{"speaker":"川西委員","kind":"質問・要望","question":"ぜひ、よろしくお願いいたします。ぜひ何かの機会に取り入れていただきたいと思います。次に移りまして、１４９ページの国文学研究資料館の一時利用についてです。私、遠いところに住んでおりますが、私のところへも国文学研究資料館の利用についてはぜひ自然環境を残して利用を考えてもらいたいという意見が寄せられてきておりますが、その辺について一時利用のあり方について伺います。","respondent":"堀越行財政改革担当課長","answer":"それに合わせて暫定利用といたしまして、区のほうで使用しない部分については暫定的な開放という形で考えております。できるだけ保存するという形でご利用いただくような、そういう形で今検討を進めております。","voiceIndex":366,"id":"exchange-157"},{"speaker":"川西委員","kind":"質問・要望","question":"お答えはありがたかったんですが、何か気持ちが伝わったかどうかというのがちょっといまいちです。要するに、あの自然環境を一時利用にしても、今後の活用にしても、ぜひ残してほしいというのが周辺、あそこに通える人たちの区民の願いなんです。これをぜひ要望で申し上げておきますけれども、忘れないでいただきたいと思います。平成２０年度の事業内容について最初に伺いたいと思います。","respondent":"高濱生活安全担当課長","answer":"生活安全サポート隊は、現在１３名の警視庁ＯＢをお願いしておりまして、５台の車でまちを見守っている事業です。中身につきましては、防犯広報あるいは緊急時における防犯パトロール、また近隣セキュリティシステムの対応、また歩きたばこについて行っております。","voiceIndex":368,"id":"exchange-158"},{"speaker":"川西委員","kind":"質問・要望","question":"紙１枚のパンフレットでもいいんです。まちの中を、例えば２台ですから、２日に一遍になりましょうか。２日に一遍はあなたのまちには回っていますとか、８・３運動でこういうふうにこの時間帯ではこんなことをしていますよというチラシみたいなものを、新しく品川区民になった住民の方とか、地域センターに置いていただくようなことは、ここに入っていないんでしょうか、伺います。","respondent":"高濱生活安全担当課長","answer":"チラシの配布、生活安全サポート隊独自でチラシの配布というのは行っておりませんが、各サポート隊の車両、必ず月に３回まちのパトロールをやっておりまして、その際に各戸に住民の方々と一緒に防犯チラシを配布しております。","voiceIndex":370,"id":"exchange-159"},{"speaker":"川西委員","kind":"質問・要望","question":"そういう危険個所とか。ですから、できれば、巡回ルートが区民に周知できるようなものを今後考えていただければと思います。これは要望にしておきます。それで、ちょっと時間がありますので、お答えだけいただきますが、１４５ページ、非核平和都市品川宣言事業の中身、それから、初めてかと思いますが、１８３ページの住宅・土地統計調査費、この中身をお願いします。","respondent":"桑村総務課長、鷹倉区民課長","answer":"平成２０年度の非核平和事業の中身ですけれども、一つは広島、長崎、広島については中学２年生、全校お一人ずつということで、いわゆる記念式典等に参加して、それについてのまた発表レポートをやっていただくもの。調査事項としましては、住宅の構造だとか階数、建て方、建築時期だとか床面積、その他細かなことを調べていくわけですけれども、これを踏まえて、これは全国ベースでやっていくものですので、全国的にそういうことをとらえて。","voiceIndex":372,"id":"exchange-160"},{"speaker":"川西委員","kind":"質問","question":"その住宅・土地のほうのことですけれども、これは初めての事業で、国の政策に基づいているんですか、それと同時に無作為でおやりになる事業なのか、その辺もちょっと伺います。","respondent":"鷹倉区民課長","answer":"国の統計調査ということで実施してまいります。品川区として、今のところ５９３調査地区というような形で国のほうからお話が来てあります。具体的には１万３４世帯というような形で今割当が来ているところです。","voiceIndex":375,"id":"exchange-161"},{"speaker":"堺委員","kind":"質問","question":"私のほうから１４９ページ、今も出ておりましたが、国文学研究資料館跡一時利用経費、それから１６１ページの一番下に書いてあります新基本構想・長期基本計画策定経費、これに関連してお伺いをします。","respondent":"中島経理課長","answer":"その内訳ですけれども、駐車場の暫定整備、こちらにつきまして１,３００万円、それと庁舎内の文書庫等の移設があります。こちらが約１,３００万円、維持管理費といたしましては、約４１６万円余です。","voiceIndex":378,"id":"exchange-162"},{"speaker":"堺委員","kind":"確認","question":"その維持管理等は区が行うと、内容は下記のとおりですということで、１番から９番まで出ておりますが、この費用ということになるんですか。要するに、この総務委員会に出た資料では、「品川区への売却までの間、無償で借り受けることができることとなったため、使用貸借契約を締結する」というご説明の文書が出ておりますので、ちょっとその辺を確認させていただけますか。","respondent":"中島経理課長","answer":"その後、引き続いて区のほうに無償で貸し付けてもらうということで、無償で引き継いだ後、実際には４月以降ぐらいになると思いますけれども、建物の関係の維持管理費がこちらに載っているものです。","voiceIndex":380,"id":"exchange-163"},{"speaker":"堺委員","kind":"質問・要望","question":"建物の維持管理ということは、ですから、私がお尋ねさせていただいたように、この総務委員会で出された書面の１番から９番まで、この維持管理、この費用ですかというふうに、よろしいですか、確認させていただきたい。","respondent":"中島経理課長","answer":"今委員のご質問のとおり、この５番に出ている維持管理費です。","voiceIndex":382,"id":"exchange-164"},{"speaker":"堺委員","kind":"質問","question":"そうすると、あそこのそれまでの間は暫定開放で、その間、要するに今ある建物等はたしかそのままお使いになるかなという想定でいきますと、これから３年間、あそこのそういう維持管理がいわゆる俗に言うランニングコストというんですか、かかってくるという中で、今年度は約３,０００万円近く、これは駐車場の云々とかありますから、来年度以降は若干減るのかもしれませんが。","respondent":"中島経理課長","answer":"この建物の部分で申し上げますと、あと一部駐車場として使う部分ですけれども、こちらに計上していますのは、細かく言いますと、７月からの金額想定でやってございましたけれども、早目に借りることができましたので、これに約２割乗せたぐらいの金額が年間の経費ということで。","voiceIndex":384,"id":"exchange-165"},{"speaker":"堺委員","kind":"確認","question":"その大体本契約、売買契約というんですかね、これはいつごろになる予定なんですか。その本契約ができた以降も、今おっしゃっておられた建物等については取り壊すまでの間は維持管理、これは区が負担していくわけですから、その辺をちょっと教えていただければと思って確認で質問させていただいています。","respondent":"中島経理課長","answer":"というのは、予算編成の段階では、３月から借りられる見込みがまだたっていなかったものですので、その分の予算はこちらには、ですから、３カ月分につきましては計上されてございません。","voiceIndex":386,"id":"exchange-166"},{"speaker":"堺委員","kind":"質問","question":"わかりました。この点につきまして、私は代表質問の中で、基本的な理念について、ちょっと３点にわたってお尋ねをさせていただきましたが、今回プレス発表資料によりますと、計画をつくるに当たって、策定委員会での検討を基本として、「これまでいただいたさまざまな意見をはじめ、議会にもご意見を伺い、さらに区内事業者３,０００社を対象に、昼間区民の意識調査を行う。","respondent":"福島長期計画担当課長","answer":"私のほうから、こちら昼間区民のアンケート世論調査につきましてご説明します。区内３,０００社を対象にですが、品川区内、現在２万１,０００社余りあります。その中から、３,０００社を絞りまして世論調査をしたいというふうに考えてあります。","voiceIndex":388,"id":"exchange-167"},{"speaker":"堺委員","kind":"提案","question":"品川区内に約２万１,０００社、そのうち３,０００社ですから、バランスですので、ぜひお願いしたいと思います。それで、今日提案をしたいのは、今回この基本構想策定を記念して、お子さんたちによる記念公園をおつくりになると、こういうのもプレス発表でされていますね。要するにこの基本計画について、お子さんたち向けのも、何かわかるようなものをつくっていただければと思いますが、いかがでしょうか。","respondent":"福島長期計画担当課長","answer":"お子さんたちにもわかるような資料をです。当然必要なことだと思いますので、また公園をつくっていく上でも必要なことだと思いますので、ぜひ作成について検討していきたいというふうに思っております。","voiceIndex":390,"id":"exchange-168"},{"speaker":"林委員","kind":"質問・要望","question":"それで、総務費のところで、どういう質問の仕方、何ページというふうに聞かなきゃいけないんですけど、消えた部分というのがいろいろあるんですよね。そういうところの案内というのを、先ほども質問が出ていた行政評価、事務事業評価も、あれはなぜ消えたのかなと思うんだけども、消えちゃった。これは何するのというのはわかりますから、こういう説明欄がなぜ変わるのかという説明をしていただきたい。","respondent":"中島経理課長、鷹倉区民課長、日下部企画財政課長、西島会計管理者","answer":"トイレの材質につきまして、誤解を招かないような表示を検討させていただきたいと思います。経済センサスに関しては、委員ご指摘のとおりです。ただ、いずれにしましても、消えたもの、あるいは内容に変更があったもの、これは冒頭説明の中で十分説明しきれない部分はありますが。一方、コンビニの収納が平成１６年度から国保が先に始まりまして、平成１６年度で７万３,３８６件、平成１７年度が１１万９,６８９件。","voiceIndex":393,"id":"exchange-169"},{"speaker":"林委員","kind":"質問","question":"２０万円しか変わらなくて、こっちは何万件と件数が減っているわけですよ。それから、新しい機構については、ぜひ委員会のほうにどういう機構でこういうお金を出資して、こういう役割を持つものだというのを説明をしてほしいなというふうに思いますので、お願いしておきます。期間がね。第六次の実施計画というのは我々の手元に来ているんだけど、第七次の実施計画というのはつくられているんですか。","respondent":"日下部企画財政課長","answer":"最後のご質問ですけれども、第七次の実施計画については、今回は作成しておりません。作成をしていないといいますのは、実は平成１９年度から３カ年で実施計画をつくっております。","voiceIndex":398,"id":"exchange-170"},{"speaker":"林委員","kind":"質問","question":"だから、この平成２０年度というのは、品川区というのはどういう思いでやっていくのか。第六次の長期基本計画というのは、去年の２月、３月につくられたものなんですよ。平成１９年度がずっとこういうふうに運営をされてきた、経営をされてきた。第七次がなければ、平成２０年度はどうするんですか。それから、長期基本計画については、平成２０年度は第三次長期基本計画でいくんですね。","respondent":"福田企画部長","answer":"一方で、ご議決いただいた基本構想は、これは明確な指針としていますし、さらにその下には、現在の第三次長期基本計画、これについても区はその方針に従いまして運営していくと、こういう関係にあります。","voiceIndex":400,"id":"exchange-171"},{"speaker":"林委員","kind":"意見","question":"この第六次までの実施計画は、都と区の財調制度の基本的な数字も違うんですよ。変わってきている。大きく変わっているんですよ、都と区の。品川区の財源の３分の１を占める財調についての都と区の比率が変わってきた中で、その前に濱野区長の初めての前書きが書かれているんだけど、ほとんど第五次長期基本計画と同じなんだ。皆さん方の手腕は信頼していますけども、頑張ってください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":402,"id":"exchange-172"},{"speaker":"安藤委員","kind":"質問・要望","question":"総務費、人件費全般についてお伺いいたします。それで、委託先の請負労働者の人数を教えてください。いつも出してもらえないんですけども。例えばすまいるスクールなどは、私も昨年視察に行きましたけども、どこの学校に、１日に何人ぐらい派遣会社からスタッフが来ているかというのは、シフト表などから容易に把握できるわけなので、わかるところだけでも教えていただきたいと思います。","respondent":"市川庶務課長","answer":"すまいるスクールの業務委託についてのスタッフの人数ですけれども、これはおおむね平均して１すまいるスクール当たり、１日当たりで４人ないし５人、これが平均的な人数です。","voiceIndex":404,"id":"exchange-173"},{"speaker":"安藤委員","kind":"質問","question":"すまいるスクールは、例えば一例だったんですが、委託先の労働者の人数全体としてつかんでいないんでしょうか。","respondent":"榎本人事課長","answer":"要はどれぐらいのサービスの時間をやってもらうかという形で算出根拠になりますので、人数ですと、例えば１０時間やっているときに２時間の人が５人いる場合、それから５時間の人が２人いる場合、それはそれぞれ変わってきますので、そういう形でのつかみ方はしておりません。","voiceIndex":406,"id":"exchange-174"},{"speaker":"安藤委員","kind":"質問・要望","question":"大崎の労政事務所のホームページを見ますと、そこにも書いています。「派遣は例外」と書いています。ここで確認したいんですけども、派遣は臨時的、一時的なものであり、常用雇用の代替にしてはならないということと、あともう一つ先ほど言いました偽装請負、発注者から直接業務の指示や命令をされる場合は偽装請負であるということに関しては、この認識に立っているということでよろしいでしょうか。","respondent":"榎本人事課長","answer":"それぞれ法令に定めたとおり運用適用しているものです。","voiceIndex":408,"id":"exchange-175"},{"speaker":"安藤委員","kind":"質問","question":"その立場に立っているということだったと思います。そのうち、ちょうど３年たつ、平成１６年６月に始まったわけですから、３年後の平成１９年５月で２園が中止になりました。ここでちょっとお伺いしたいんですが、なぜ東中延と東品川、そして中延と五反田もわずか１カ月だけ雇用形態を変えて、中止になったんですが、なぜ３年でこのオアシスルームをやめたんでしょうか。","respondent":"小林保育課長","answer":"オアシスルームの設置に関しましては、基本的には地域の需要に応じて設置をするようにしております。その運営に当たりましては、派遣職員も含めてそれぞれ適切な配置に心がけて対応しています。","voiceIndex":410,"id":"exchange-176"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと私は大崎五反田地域に住んで動いているんですけども、五反田で需要がない、オアシスルームの需要がないわけはないなと思うんですが、やはり需要がなくなったんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":412,"id":"exchange-177"},{"speaker":"安藤委員","kind":"質問","question":"その５園のうち、中原保育園だけが今年の４月で業務終了ということになるんですけども、こういう東大井、旗の台、大崎、大井倉田のほうは、３年を超えているんですけども、継続して業務、オアシスルームをやると、これはどういう契約、雇用形態といいますか、業務形態で行う予定なんでしょうか。","respondent":"小林保育課長","answer":"中原につきましても、地域の需要から考えますと、お願いいたしておりますのは、今度はぷりすくーる西五反田で、委託形態でオアシスルームを予定しておりますが、立地から考えて、中原の位置よりも、西五反田より五反田駅に近いところでの需要対応が必要と考えたところです。","voiceIndex":414,"id":"exchange-178"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと答弁漏れだと思うんですが、ほかの４園。東大井、旗の台、大崎、大井倉田のほうは、これまでは正規と業務派遣により対応しておりますけども、それはどうなるんでしょうか。","respondent":"小林保育課長","answer":"それぞれ地域の需要とそれに対応する適切な人員配置ということで対応しております。それ以外の理由は特にございません。","voiceIndex":416,"id":"exchange-179"},{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、今までは正規と業務派遣により、３年間東大井、旗の台、大崎、大井倉田は運営してきたわけですけども、今年も継続するに当たって、どのような職員の体制といいますか、派遣を使うのか、請負でやるのか、委託でやるのか、それとも正規でやるのかということを教えていただきたいというような質問でした。","respondent":"小林保育課長","answer":"例えば、再任用で充てたいと思いましても、その年、再任用が何名採用できるのか、また勤務不能なところに無理やり配転することもいかがなものでしょうか。そういった状況、そして需要を含めて正規職員を基本に臨時職員や派遣も含めて配置をしています。","voiceIndex":418,"id":"exchange-180"},{"speaker":"安藤委員","kind":"確認","question":"まだ決まっていないということなんですかねということを１点確認したいのと、もし仮に派遣の方をこれからも使うということになると、もちろんその現場で頑張っておられる派遣の皆さんが職を失うということは絶対あってはならないんですけれども、もともと先ほども首相も国会で答弁していますけれども、臨時的、一時的な業務にしか充てられないと答弁ありましたけども、そういう立場からすると。","respondent":"小林保育課長","answer":"そういった点からいっても、適切な雇用というのがオアシスの事業の場合、派遣だけに頼るのではなく、派遣も含めて有効活用し、適切な配置をしていることが裏付けられていると考えております。","voiceIndex":420,"id":"exchange-181"},{"speaker":"安藤委員","kind":"意見","question":"クールオフという言葉がありましたけれども、たしか私がちょっと間違っているかもしれないんですけど、３カ月ぐらい派遣の方に休んでもらって、そうなれば、臨時的、継続的なものとは見られないからまた派遣として登用できるという理解があるんですけれども、そのクールオフについてちょっと説明してください。","respondent":"榎本人事課長","answer":"派遣法の中の解釈の中で、連続でどれぐらいかという実例の中でそういうような見解が示されているというものです。","voiceIndex":422,"id":"exchange-182"},{"speaker":"安藤委員","kind":"質問","question":"それを聞いております。それを活用しているということなんでしょうか、その制度といいますか。どういうところからそういう通達があったんでしょうか。","respondent":"榎本人事課長","answer":"それで、人材派遣の部分ですけれども、もちろん今回も保育士４０数名を新規採用する中においても、派遣職員で働いていた方も入っておりますし、非常勤の職員で入っていた方もありますし、それぞれ各自の努力の中で正規職員につく方も多いというものです。","voiceIndex":426,"id":"exchange-183"},{"speaker":"三上委員","kind":"質問・要望","question":"１６９ページの区民保養所経費、それから１６３ページ、学校等の避難所機能充実について、時間がないでしょうから、あればそれに関連する形でちょっとお伺いしたいと思います。それから、学校等の避難所機能の件で、学校避難所訓練ということでちょっとお伺いしたいんですけれども、３月２日の日に平塚小学校で三つの町会が集まって避難所訓練を行いました。","respondent":"鷹倉区民課長、久保田防災課長","answer":"箱根荘の露天ぶろの改修時期ですが、平成１５年７月に浴室改修ということで露天ぶろを設置しています。学校避難所訓練ですけれども、これは震災時に避難所をどうやって運営していくかという観点に立って、その一環として行っているものですので、基本的には避難所を運営する主体になっている防災区民組織の本部長を中心にということなので。","voiceIndex":429,"id":"exchange-184"},{"speaker":"三上委員","kind":"質問・要望","question":"箱根荘のほうですけども、露天ぶろをつくられたということで、これに関して何か区民の方から要望とか、何か苦情とか、そういうのが聞かれていないかどうか、ちょっとお伺いします。それから、学校避難所の場合、じゃあ防災という考え方から本部長が責任、そうなると、学校の先生方の参加についても、先ほどの昼間の質疑等で、学校でも自主防災組織をつくらなければならないと。","respondent":"鷹倉区民課長、久保田防災課長","answer":"私直接は聞いていないんですが、ただ、私も何度か現場を見に行っていて、自分自身で感じているのは、男性と女性の露天ぶろがあるわけですけども、男性の露天ぶろのほうが若干見通しが悪いなと。主にこの区役所もそうなんですが、職員が中心になって、まず初期消火に努めると、そのための組織整備をしなさいと、こういうことになっていて、それで整備されているものですので、学校避難所の場合には全く違うんですが。","voiceIndex":432,"id":"exchange-185"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう部分について、この中でもどなたかそういうのを体験された方はいらっしゃらないですか。それこそやはり皆さんの中で、この冬期間にどういう状況になっているのか泊まっていただきたい。担当の課長、山田副区長、長い間事業部長をやっていたから、当然泊まっているかと思うので聞こうと思ったらいないですから。お子さんたちの参加というのはほとんど少なかったですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":435,"id":"exchange-186"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"普通の品川荘、箱根荘でありますけれども、これは差し引きをすると１億円以上のお金が出ているんだということだと思うんですけれども、これについては、保養所のもちろん規模もあるので、さまざまな検討が行われていると思いますが、今後どのようにしようとお考えになっているのか、また、変な話、直営とかいろんな方法があるじゃないですか。その方法の種類をもし教えていただければ。","respondent":"榎本人事課長、鷹倉区民課長","answer":"それからあとは異業種交流ということで、宿泊研修でのメニュー、それから経営戦略というメニューでの、やはり２日間のメニュー、それから経営戦略全般ということで、各界のトップクラスの方を講師に招いた形での自治体経営。その手法の中で、箱根荘と品川荘は今後どういうふうにしていくかは別なんですが、新たなやり方として借り上げの方式、これも一つの新たなやり方なのかなというふうに、種類としては考えてあります。","voiceIndex":437,"id":"exchange-187"},{"speaker":"石田（秀）委員","kind":"提案","question":"ゼロ、ゼロは。それで区に提出してくる。そういうことを考えると、区民サービスが低下しているということは踏まえておいてもらわないと、そういうことがあるということは踏まえて、だけれども、そうじゃないことにしていくよという何か提案がないと、私はもう一段そこは答弁をいただきたいな。そこら辺のところの考え方というのは、頭の中でお持ちなのかどうかも含めて教えていただきたい。","respondent":"榎本人事課長、鷹倉区民課長","answer":"管理職研修ですけれども、やはり、こういう研修というのは新しい視点、もしくは考え方のきっかけづくりにすごく役立つものと認識しております。そういった意味からも、いろんな業種の人との交流等を大事にしていきたいと思っています。具体的に箱根荘を考えてみますと、今自然公園法上の中にありまして、なかなか建て替えも難しいような状況。したがって、これは将来的にどこかと何かがあるということは非常に難しい話だと思ってあります。","voiceIndex":440,"id":"exchange-188"},{"speaker":"石田（秀）委員","kind":"意見","question":"保養所のほうはやめておきます。よろしくお願いします。研修なんですけど、ぜひ今年は何人か行かれた、特にその中に事業部長も行ったという実績があるように、ぜひそれだけお願いをしてやめます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":443,"id":"exchange-189"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=896#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2008-01-01&TermEnd=2008-12-31"}],"sourceMeta":{"pages":0,"characters":130060,"voices":444}}]);
